export const ARCHITECTURE_DOCS_CONTENT: Record<string, string> = {
  "core1ab-guide": "<nav class=\"field-nav\" aria-label=\"Guide contents\"><h2>Contents</h2><a href=\"#start\">00 \u00b7 Start here: the agent's mission</a><a href=\"#evidence-gate-r2\">00A \u00b7 Physics R2 evidence gate</a><a href=\"#workflow\">01 \u00b7 End-to-end execution map</a><a href=\"#intake\">02 \u00b7 Intake, boundaries and working contract</a><a href=\"#scope\">03 \u00b7 Research the syllabus and decompose the topic</a><a href=\"#research\">04 \u00b7 Search and source research protocol</a><a href=\"#coverage\">05 \u00b7 Build the question coverage denominator</a><a href=\"#sl1sl2\">06 \u00b7 Smart Skills: identity before cognitive claims</a><a href=\"#solve\">07 \u00b7 Solve first: find the decisive construction W</a><a href=\"#operations\">08 \u00b7 Seven operations: distinguish the decisive act</a><a href=\"#difficulty\">09 \u00b7 Demand scoring and D3/D4 discipline</a><a href=\"#blueprint\">10 \u00b7 Resolve the Blueprint without contaminating it</a><a href=\"#adapter\">11 \u00b7 Design and populate the topic adapter</a><a href=\"#warrants\">12 \u00b7 Build the disciplinary claim and warrant register</a><a href=\"#core1a\">13 \u00b7 Core1A: write a real textbook, not a task bank</a><a href=\"#visuals\">14 \u00b7 Figures, representations and learner ergonomics</a><a href=\"#freshness\">15 \u00b7 Core1B: engineer a genuinely fresh task</a><a href=\"#journey\">16 \u00b7 The six-stage Core1B learning journey</a><a href=\"#main\">17 \u00b7 Standalone subtopic units and integrated MAIN</a><a href=\"#diagnosis\">18 \u00b7 Diagnose evidence, not the learner's personality</a><a href=\"#worked\">19 \u00b7 Worked design mini-cases across subjects</a><a href=\"#binder\">20 \u00b7 B1\u2013B7: evidence join and falsifiers</a><a href=\"#implementation\">21 \u00b7 Implement native records and learner runtime safely</a><a href=\"#qa\">22 \u00b7 Mechanical QA and adversarial tests</a><a href=\"#review\">23 \u00b7 Independent review, separation and release</a><a href=\"#batch\">24 \u00b7 Batch strategy, coverage closure and corrections</a><a href=\"#templates\">25 \u00b7 Reusable workpack and handoff templates</a><a href=\"#done\">26 \u00b7 Definition of done and failure checklist</a><a href=\"#references\">27 \u00b7 Authority, references and actual reading order</a></nav><article class=\"field-body\" id=\"guide-content\"><section class=\"field-section\" id=\"start\"><h2>00 \u00b7 Start here: the agent's mission</h2>\n<p>Build a learner's ability to perform the <em>decisive intellectual work</em> of an unfamiliar, authentic topic question. Core1A makes the reasoning intelligible and teachable. Core1B makes the learner perform it before it is revealed, then compare, diagnose, repair and transfer. A Core2 question remains its own source-bound assessment. The unit is successful when its evidence joins are defensible, not when a page looks polished or contains many questions.</p>\n<aside class=\"callout\"><strong>Read first.</strong> This guide is an author-facing execution manual, not the master specification or a reviewer appointment. Read <a href='../AGENTS.md'>AGENTS.md</a>, <a href='../Start_here.md'>Start_here.md</a>, <a href='../CURRENT_CHECKPOINT.md'>CURRENT_CHECKPOINT.md</a>, <a href='../docs/product-scope.md'>product scope</a>, <a href='../docs/agent-entry/00-required-reading.md'>required reading</a>, the <a href='guidebook.html'>architecture guidebook</a>, and the <a href='core2-source-to-learning-pipeline.html'>Core2-led source pipeline</a>. Resolve the actual owner instruction and master Issue #1. If the authoritative source is inaccessible, record HOLD and the precise retrieval failure; candidate-only work needs explicit scope permission. Do not silently substitute this guide for authority.</aside>\n<p>Platform method is reusable; content and academic rules are not. Physics, Mathematics and Chemistry have separate disciplinary warrants and Blueprints. The NSEJS preview also contains Biology: this guide can support an explicitly authorized Biology workpack but does not itself expand the three-subject product scope, approve a Biology Blueprint, or appoint its owner. Always identify the selected subject and examination.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Do</th><th scope=\"col\">Do not</th></tr></thead><tbody><tr><td>Teach a transferable construction, derived from real source demands and scientific or disciplinary evidence.</td><td>Write generic notes then attach unrelated hard practice and call it exam coverage.</td></tr><tr><td>Select the shortest valid route; protect the decisive move.</td><td>Assign D3/D4 because the source is an Olympiad item, the explanation is long, or there are many calculations.</td></tr><tr><td>Create standalone Core1A/Core1B per authorized subtopic and integrate MAIN across genuinely connected subtopics.</td><td>Force every operation cell to be filled or count duplicate links as unique questions.</td></tr><tr><td>Retain source fidelity, candidate status and exact version history.</td><td>Invent source IDs, missing figures, keys, receipts, approval or learner mastery.</td></tr></tbody></table></div>\n<p><strong>First handoff:</strong> issue a brief readback of scope, authority, pins, current baseline, workpack, exclusions and the next bounded deliverable. If asked for a blind review, do not read this author guide first; follow the <a href=\"../docs/agent-entry/07-independent-review.md\">source-only reviewer protocol</a>.</p><p><strong>Physics production update.</strong> The new <a href=\"#evidence-gate-r2\">section 00A</a> is the required R2 evidence-gated entry after Owner adoption. The present status is PILOT, not approved production. Begin by comparing the teaching brief, Golden Sample SHA and evidence packet; do not self-certify academic qualification. The base guide still explains how to teach, and other subjects require their own approved quality contract.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"evidence-gate-r2\" data-contract=\"quality-gate-r2\"><h2>00A \u00b7 Physics R2: evidence-gated author submission and Golden Sample</h2>\n<aside class=\"callout\"><strong>Mandatory entry for Physics agents after adoption; pilot today.</strong> The existing chapters 01\u201327 explain <em>how to create</em> good Core1A/Core1B; R2 adds <em>what an author must prove</em> before asking for review. The current policy is <code>PILOT_AWAITING_OWNER_GOLDEN</code>, not an active publication/branch-protection gate. Read the <a href=\"../docs/agent-entry/quality-gate-r2/README.md\">R2 Quickstart</a> and <a href=\"../docs/agent-entry/quality-gate-r2/AUTHORING_QUALITY_CONTRACT_R2.md\">full R2 Quality Contract</a> before starting any new Physics production workpack. R2 is Physics-specific: it does <strong>not</strong> silently change Mathematics, Chemistry or Biology subject rules.</aside>\n<h3>R2 replaces self-certified PASS with three independently separable proofs</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Layer</th><th>Required artifact / proof</th><th>What it cannot claim</th></tr></thead><tbody>\n<tr><td><strong>Author \u2014 science and instruction</strong></td><td>Actual student-facing Core1A, solved independent physics, dimensions/signs/limits, physical figures, misconception repair, three progressive anchors, Core1B distinct W, six stages and Core2 identity. Every key claim points to exact file SHA-256, numbered source lines and verbatim excerpts.</td><td>No author can declare its own scientific/QRT/B1\u2013B7 verdict.</td></tr>\n<tr><td><strong>Machine \u2014 evidence integrity</strong></td><td>Closed <a href=\"../docs/agent-entry/quality-gate-r2/evidence-packet.schema.json\">JSON Schema</a>, <a href=\"../docs/agent-entry/quality-gate-r2/verify_evidence_packet.py\">byte/quote/reference validator</a>, deliberately failed negative cases and exact-head HTTP Chromium receipts.</td><td>A green validator proves inspectable evidence, <em>not</em> correct teaching or independent learner mastery.</td></tr>\n<tr><td><strong>Reviewers \u2014 scientific and cognitive challenge</strong></td><td>Separate R00 technical and unexposed R01 academic/QRT <a href=\"../docs/agent-entry/quality-gate-r2/REVIEWER_AND_GOLDEN_TEMPLATES.md\">receipts</a> after source-scope review. R01 independently solves before viewing an author key, checks actual transfer and B1\u2013B7.</td><td>Authors cannot forge reviewer receipts, rename a self-check as blind review or use a test run as approval.</td></tr>\n</tbody></table></div>\n<h3>What exactly must an author submit?</h3>\n<p>Copy the <a href=\"../docs/agent-entry/quality-gate-r2/EVIDENCE_PACKET.template.json\">full R2 Evidence Packet template</a> into <code>review/quality-packets/physics/PHxx/&lt;task-uid&gt;.packet.json</code>. Its placeholders intentionally <strong>fail</strong>. Replace them with real paths, exact SHA-256 values, smallest supporting line intervals, verbatim text and an explicit why-this-proves-the-claim warrant. Link each finding to the actual generated page and task revision. A chat message saying &ldquo;B1\u2013B7 passed&rdquo;, a long checklist, or a screenshot of a completed field is not evidence.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Core role</th><th>Non-negotiable witness</th><th>Fail-closed falsifier</th></tr></thead><tbody>\n<tr><td><strong>Physics science</strong></td><td>First-principles derivation, independent second check, units/sign conventions, applicability bounds and counterexample. Diagrams must show physically relevant labels and relationships.</td><td>Omit density from a pressure-gradient equation, flip the frame or draw an inconsistent ray: the independent proof/figure check must detect it.</td></tr>\n<tr><td><strong>Core1A</strong></td><td>Phenomenon, prerequisites, causal mechanism, worked warrant, meaningful figure, FOUNDATION/CONNECTED/ADVANCED examples, specific misconception and repair, independent synthesis and cold-readable challenge.</td><td>Remove the exam question/answer key. If the chapter is only a formula and solved question, or an untaught assumption is required, B3 stays HOLD.</td></tr>\n<tr><td><strong>Core1B</strong></td><td>Side-by-side anchor versus new problem, distinct decisive work W, independently solved shortest route, specific diagnose/repair and a fresh changed-condition task.</td><td>Replace numbers in the Core1A example; if the same W solves the task, B4 fails even when the task renders and its answer is correct.</td></tr>\n<tr><td><strong>Core1B runtime</strong></td><td>Immutable revision-bound first response before help, ordered exposure H1/H2/H3, separate repairs, protected boundary answer, refresh/reset preservation, storage/stale failure.</td><td>Block storage, show help early, change content revision or retry; old answer must remain intact and no precommit explanation may leak.</td></tr>\n<tr><td><strong>Core2</strong></td><td>Complete stem/figure/options, independent correct-key reasoning, exact item UID/source status, attempt-first response and honest Core1A/B route links.</td><td>Remove a necessary figure, force save failure or hardcode a Reviewed badge for an unqualified item: hold the affected card.</td></tr>\n</tbody></table></div>\n<h3>Prove the guard can reject defects, not just accept good data</h3>\n<p>The first Golden Sample needs actual injected failure logs for all eight cases: <code>WRONG_DIMENSION</code>, <code>WRONG_SIGN_OR_LIMIT</code>, <code>NUMERIC_CLONE</code>, <code>HINT_LEAK</code>, <code>BAD_SOURCE_FIGURE</code>, <code>SAVE_FAILURE</code>, <code>STALE_REVISION</code> and <code>FALSE_REVIEW_BADGE</code>. Thereafter each item includes the three required cases (wrong dimensions, numeric clone, hint leakage); full inherited browser/state regression runs on the batch, with all new Physics models and D4 proofs reviewed individually. Do not handwrite &ldquo;REJECTED&rdquo; in a JSON field without the corresponding actual fault-injection command, failure and inspectable log.</p>\n<h3>Agent execution commands and exact dispositions</h3>\n<pre><code># First pin the actual source revision and current contract version.\ngit rev-parse HEAD\npython -m pytest -q\npython -m pytest -q tests/test_physics_quality_gate_r2.py\n\n# Replace with a real completed packet; the unfilled template must fail.\npython docs/agent-entry/quality-gate-r2/verify_evidence_packet.py \\\n  review/quality-packets/physics/PHxx/&lt;task-uid&gt;.packet.json\n\n# PR level: becomes a required blocking check only after Golden adoption.\npython docs/agent-entry/quality-gate-r2/enforce_pr_packets.py \\\n  --base &lt;40-character-pinned-parent-sha&gt;</code></pre>\n<p>The best author-side validator result is <code>EVIDENCE_STRUCTURALLY_GROUNDED</code> with <code>academic_status=HOLD</code> and <code>review_required=true</code>. A schema/Python PASS is never an R01 acceptance. The current repository policy returns <code>PILOT_NOT_ENFORCED</code> until the Owner accepts a single fully reviewed Golden Sample; see <a href=\"../docs/agent-entry/quality-gate-r2/quality-policy.v1.json\">policy state</a> and <a href=\"../docs/agent-entry/quality-gate-r2/enforce_pr_packets.py\">production scope checker</a>. Required GitHub status checks, CODEOWNERS and reviewer permissions must be configured for actual enforcement.</p>\n<h3>Golden once, delegated batches thereafter</h3>\n<ol><li><strong>Golden:</strong> Author one complete representative Core2 + real textbook Core1A + genuinely fresh Core1B. R00 checks code/bytes; independent R01 checks the science and demand, with real error and negative tests. The Owner accepts the <em>versioned exemplar and standard once</em>.</li><li><strong>Activation:</strong> Authorized integrator pins the accepted SHA and signed Owner-G0 receipt, changes policy from PILOT to ACTIVE and makes the workflow a required branch-protection check. Until this is actually configured, never say authors are technically blocked by production CI.</li><li><strong>Production:</strong> Every changed Physics content file and changed Core2 UID needs a grounded packet. An unselected independent sample (proposed minimum 20% with at least one per topic) and <strong>100% of new laws, D4 proofs, key disputes and failures</strong> get delegated reviewer attention. Report sampled/unsampled independently.</li><li><strong>Escalation:</strong> One P0 science contradiction, protected-answer leak, evidence forgery or false review status stops the affected batch; independently inspect the same defect family and require new source revision and evidence. Do not remedy a bad page by changing its review labels.</li></ol>\n<aside class=\"callout\"><strong>Owner direction:</strong> Owner approval is required <em>for the first accepted Golden Sample/standard</em>, not separately for every routine question. R00 and R01 reviewers undertake the delegated continuing QA. Redistribution-rights evaluation is outside this R2 educational-quality addendum; it is not used to substitute for science/attempt/source-identity checks. The original cross-subject guide remains a teaching method, but the Physics R2 evidence contract controls claim promotion after explicit adoption.</aside>\n<p>Continue the normal method below: research \u2192 solve \u2192 qualify the subject warrant \u2192 construct Core1A \u2192 design fresh Core1B \u2192 implement native journeys \u2192 independently audit. **R2 adds an auditable completion contract at each step; it does not replace the pedagogy.**</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section><section class=\"field-section\" id=\"workflow\"><h2>01 \u00b7 End-to-end execution map</h2>\n<div class=\"route-grid\"><div class=\"route\"><h3>Question route \u2014 what must be done?</h3><p>Inventory source \u2192 exact question, variants, figures and key \u2192 SL1 \u2192 SL2 proposal under subject rules \u2192 independent QRT \u2192 native Core2 identity \u2192 required construction.</p></div><div class=\"route\"><h3>Exposition route \u2014 what must be taught?</h3><p>Scope and syllabus \u2192 book, reference, experiment or proof \u2192 exact source units \u2192 claim/condition ledger \u2192 qualified disciplinary warrants \u2192 construction requirements.</p></div></div>\n<div class=\"join\"><strong>Join on exact W, direction, conditions and source role</strong><span> \u2193 Blueprint cell + topic adapter + warrant + construction binder</span><span> \u2193 Core1A teaching + fresh Core1B INSTANCE + cross-instance MAIN</span><span> \u2193 technical verification + independent B1\u2013B7/academic decisions + owner release</span></div>\n<p>The subject Blueprint, rubric and adapter are inputs to the question route, not things invented after selecting difficulty. Research and exposition preparation may proceed concurrently with source intake when authorized; the actual Owner's authoring sequence still governs. In the WPE pilot the specific gate is completed Core2 scope acceptance \u2192 Core1A acceptance \u2192 Core1B; never generalize an exception granted in a different workpack. A candidate may be useful before qualification, but the UI and records must say so.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Gate</th><th scope=\"col\">Work product</th><th scope=\"col\">Stop / return</th></tr></thead><tbody><tr><td>G0 \u00b7 Baseline</td><td>Scope and version pins, existing inventory, role/branch readback, accepted workpack.</td><td>Missing authority, wrong base, cross-agent collision.</td></tr><tr><td>G1 \u00b7 Sources and science</td><td>Source/claim registers, scope taxonomy, source identity and key/figure custody, warrant checks.</td><td>Missing originals, unresolved scientific contradictions, rights or subject specification.</td></tr><tr><td>G2 \u00b7 Core1A</td><td>Construction-led teaching, progression, figures, anchor, misconception and exit witness.</td><td>Textbook does not teach W, or imports unsupported assumptions.</td></tr><tr><td>G3 \u00b7 QRT and binding</td><td>Exact task routes, five factors, source roles, cell-to-instance bindings, gap notes.</td><td>No defensible cell, paused cell, inconsistent demand, missing subject rubric.</td></tr><tr><td>G4 \u00b7 Core1B</td><td>Fresh task, protected W, six-stage journey, differentiated repair and boundary.</td><td>Anchor is copied, protected step exposed, MAIN is disconnected.</td></tr><tr><td>G5 \u00b7 Implementation</td><td>Native validators, full tests, exact HTTP runtime and independent technical review.</td><td>Stale/failed test, leakage, wrong revision, inaccessible route.</td></tr><tr><td>G6 \u00b7 Academic/release</td><td>Trusted independent review and Owner/Shared release evidence for exact revision.</td><td>Any mandatory gate HOLD or FAIL; do not merge/deploy on green CI alone.</td></tr></tbody></table></div>\n<p>These G0\u2013G6 labels are a useful workpack checklist used in the PH01 pilot; reconcile them with the repository's <a href=\"core2-source-to-learning-pipeline.html\">eight-stage Core2-led source pipeline</a>, not a new authority hierarchy.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"intake\"><h2>02 \u00b7 Intake, boundaries and working contract</h2>\n<ol><li>Read the current repository instructions in full. Resolve selected subject, examination/curriculum, grade, chapter, exact subtopics, authoring phase, review scope and repository write permissions.</li><li>Pin base branch/head/tree, current canonical registry, source inventory, native skill revisions, Shared QRT/rubric, subject Blueprint, topic adapter, scientific library, schemas, validator and renderer/runtime. Use content digests, not just version strings. Record unavailable files and local-only roots.</li><li>Read existing Core1A/B, Core2, other agents' assignments, recent review comments and the actual status of every proposed source. Verify existing work before creating anything. Never take another agent's topic or alter shared runtime without coordination.</li><li>Map acceptance criteria to specific artifacts and tests. Use separate branch/draft PR, preserve prior revisions; agree on bounded batch and reviewer handoff. Keep source originals and learner data in protected custody, not public Git.</li><li>Report candidate-only scope, HOLD items, owner questions and known technical restrictions. Start with the first unresolved gate rather than jumping to HTML.</li></ol>\n<pre><code>INTAKE READBACK (illustrative, not a native schema)\nworkpack / author / authorized reviewer:\nsubject + examination + syllabus version:\nchapter / subtopic IDs / exclusions:\nowner scope + decision reference:\nbase branch, commit, tree:\nauthority docs + access status:\nsource registry, source archive, SL1/SL2, QRT rubric:\nsubject Blueprint, adapter, warrant library, schemas:\nexisting lesson/package/runtime/review revisions:\ndeliverables / acceptance witnesses / test commands:\nshared paths requiring platform-owner review:\nHOLDs / unselected dependencies / rights / resource limit:\nallowed actions: read / candidate edit / PR / merge / release (separate)</code></pre>\n<aside class=\"callout\"><strong>STOP rule.</strong> Do not invent a missing subject Blueprint or approve a topic by editing a status field. If master issue access fails, state exact failure, identify the actual Owner's limited instruction, and distinguish a read-only plan from authorized candidate changes. The owner-local workspace is not implied available to remote agents.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"scope\"><h2>03 \u00b7 Research the syllabus and decompose the topic</h2>\n<p>Begin with an authorized topic and its curriculum/exam scope. Read the current official syllabus, prescribed text and edition, prerequisite statements and relevant reference material. Compare with the assessment corpus, including source questions whose keywords differ from the chapter title. A subtopic is a reusable construction, not a heading, exam year, band or isolated formula.</p>\n<ol><li>Create a chapter concept map: entities, quantities/definitions, assumptions, laws or theorems, operations, representations, common errors, limiting cases and prerequisite relations.</li><li>Split into stable subtopic IDs where the protected move or knowledge prerequisites materially differ. Combine fragments only when the learner must use them in the same construction; do not hide a cross-topic law inside a subtopic just to raise coverage.</li><li>For each subtopic specify an observable competency: given X and permitted Y, independently construct/decide W by a valid route Z, state conditions, and check the result. Separate forward/reverse and direct/inverse constructions; directional asymmetry matters.</li><li>Identify scope roles: syllabus-core candidate, prerequisite bridge, extension, outside owner scope. Mark any unsupplied syllabus or unselected content explicitly. A source's appearance in a chapter does not prove current syllabus eligibility.</li><li>Build a prerequisite DAG (no cycles, no unresolved IDs). Classify each actual question at its decisive construction rather than stamping the entire subtopic D3/D4.</li></ol>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Example (illustrative only)</th><th scope=\"col\">Construction split</th><th scope=\"col\">Important boundary</th></tr></thead><tbody><tr><td>Physics: motion</td><td>Signed coordinate \u2192 distance/displacement \u2192 velocity \u2192 acceleration \u2192 graph translation \u2192 constant-a validity \u2192 relative motion \u2192 circular motion.</td><td>Momentum/forces may use velocity or acceleration but are not thereby kinematics-primary.</td></tr><tr><td>Mathematics: linear constraints</td><td>Represent condition as equation \u2192 solve within domain \u2192 test inconsistent/redundant constraints \u2192 prove parameter feasibility.</td><td>Forward solution versus inverse parameter proof may be different operations.</td></tr><tr><td>Chemistry: stoichiometry</td><td>Balanced equation \u2192 amount-of-substance mapping \u2192 limiting reagent \u2192 yield/mixture constraints \u2192 validate physical domain.</td><td>Mass conservation is not equality of reactant mole counts; reaction conditions must be specified.</td></tr><tr><td>Biology (only if authorized): inheritance</td><td>Allele/genotype distinction \u2192 cross representation \u2192 probability under assumptions \u2192 test exception.</td><td>A Mendelian model does not universally imply independence or complete dominance.</td></tr></tbody></table></div>\n<aside class=\"callout\"><strong>Deliverable.</strong> A scope matrix with stable IDs, prerequisites, official scope citations, direction, expected representations, competency and boundary. Do not select a new subject/topic or impose a universal number of subtopics.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"research\"><h2>04 \u00b7 Search and source research protocol</h2>\n<p>Search is evidence discovery, not qualification. Use the highest-authority available sources and preserve the difference between what was located, visually checked, byte-verified and academically accepted. Work source-first: build the denominator before claiming coverage.</p>\n<ol><li>Inventory the existing repository's Core2 registry, banks, source evidence, textbook references, previous topic maps, historical duplicate IDs and open gaps. Read exact metadata, not just a dashboard count. Source roles and source-year claims may disagree.</li><li>Use official examination body archives: search exam name, year/session, set/code, question paper, final answer key, corrected key and syllabus. Follow the publisher archive rather than a stale deep link. Verify the printed paper header, page, language, code and actual question number. For a mathematical proof, use a trusted text or authoritative definition; for Chemistry/Biology, verify conditions and scope against suitable disciplinary references.</li><li>Search both question routes and exposition routes. Search by equivalent descriptions, graph types, formula variants, alternate names, cross-topic contexts and original language if relevant. Include the full relevant corpus, not only easy-to-find exemplars. Read surrounding source passages, captions and diagram labels.</li><li>For PDFs inspect the exact pages and figures visually, not only extracted text. Record exact printed page versus PDF index, source URL, retrieval date/status, edition, paper/code, question number, original stem/options, relevant assets and final key version. If originals are restricted keep them in authorized private custody. Hash actual bytes with SHA-256 where acquired; record unavailable hashes, never substitute a URL or fabricated digest.</li><li>If a publisher PDF is unavailable, try the official archive and alternative official URLs. Secondary copies or indexed text may support provisional scope screening; label secondary/partial evidence and note discrepancies. Never treat a retyped diagram or coaching key as official custody. Keep the original and correction records separately.</li><li>Independently solve before looking at the key where the review requires it. Reconcile final versus tentative keys, dropped questions, alternative answers, ambiguities and incorrect statements. Do not silently 'correct' an official key. Report contradiction or HOLD to the appropriate reviewer and preserve evidence.</li><li>Deduplicate by canonical identity and exact content revision; distinguish multiple occurrences, versions, language variants and collisions. Do not equate similar topics or matching external ID strings. Cross-check bank UID/revision against registry UID/revision and source evidence.</li></ol>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Evidence state</th><th scope=\"col\">Permitted claim</th></tr></thead><tbody><tr><td>LOCATED / metadata-only</td><td>Identity or scope prospect; no original text/figure/key claim.</td></tr><tr><td>Publisher visual check</td><td>What was actually visible in that paper/key and which page; not retained byte custody.</td></tr><tr><td>Secondary or indexed text</td><td>Provisional screening only; state missing originals and figure limitations.</td></tr><tr><td>Exact original bytes + verified locator</td><td>Integrity/custody evidence; still not correctness, rights or QRT approval.</td></tr><tr><td>Independent source + discipline review</td><td>Specific reviewed evidence, subject to review scope and rights.</td></tr><tr><td>Authorized release</td><td>Only after all applicable release gates and exact content/reviewer pins.</td></tr></tbody></table></div>\n<pre><code>SOURCE REGISTER (conceptual fields; map to actual SL1 schema)\nsource_id / occurrence_id / canonical_question_uid (nullable)\nsource_type: exam | textbook question | exposition | reference | authored\nissuer / book edition / exam date / paper code / question / printed page\nretrieval URL, timestamp, retrieval status, original byte SHA-256 or HOLD\nstem, options, figure assets and key digests held privately when required\nofficial paper identity / final key identity / key conflict / dropped status\ncontent_revision_sha256 / duplicate or variant relation / custody / rights\nscope role / reviewed source role / assigned topic owner / missing evidence\nsource notes and correction history</code></pre>\n<p>Source intake entry: <a href=\"../docs/agent-entry/01-source-intake.md\">01 source protocol</a>. Never force-add owner-local source PDFs, private learner data or unlicensed assets to Git.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"coverage\"><h2>05 \u00b7 Build the question coverage denominator</h2>\n<p>For each corpus item, record exactly one scope disposition, even if it is irrelevant. Begin with registry records, and then maintain external locators separately for items not yet admitted. Review every row; a source map is not exhaustive just because it contains many associations.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Disposition</th><th scope=\"col\">Handling</th></tr></thead><tbody><tr><td>Direct topic-primary</td><td>Identify W and shortest valid route. Join to construction teaching and fresh transfer only when defensible.</td></tr><tr><td>Cross-topic prerequisite</td><td>State exact prerequisite, primary owner and boundary. Coordinate; do not claim the whole question or transfer ownership.</td></tr><tr><td>Other topic primary</td><td>Exclude with concrete reason; retain in denominator.</td></tr><tr><td>Dropped / cancelled</td><td>Study only; no scored exam-coverage credit.</td></tr><tr><td>Ambiguous identity / missing source</td><td>HOLD; resolve variants/figure/key/custody before admission.</td></tr><tr><td>External locator not in registry</td><td>No canonical ID or bank ID; propose intake to owner/platform agent.</td></tr><tr><td>Authored/synthetic</td><td>Practice or controls only; distinct from authentic source counts.</td></tr></tbody></table></div>\n<p>For each directly mapped question, maintain a construction signature, source shortest route, proposed primary operation/band (or HOLD), exact subtopic and scope role, source key/figure status, focused Core1A teaching anchor, exact Core1B cycle, novelty delta and independent review status. A bridge must teach the precise prerequisite, not just cite the chapter.</p>\n<p>Audit associations at task level. Use focused direct, focused prerequisite, supplemental related, weak and dropped study-only labels as author triage if helpful; they are not native source role or approval statuses. Preserve history and remove/replace misleading principal links via a versioned correction, not erasure. Compare the source W against the task W; broad similarities do not prove exact fit.</p>\n<pre><code>Coverage report \u2014 separate denominators\ncanonical metadata rows inventoried / total\nofficial paper locators screened / declared corpus\nexact original bytes verified / missing or conflicts\nauthenticated examination questions (unique identities)\ndirect exam vs prerequisite vs authored counts\nexisting source-to-learning associations (many-to-many)\nfocused / supplemental / weak / dropped associations\nauthor candidate instances and MAIN, by operation and actual band\nindependently qualified source items and teaching/assessment constructions\nunresolved syllabus gaps / corpus gaps / cross-topic handoffs / release gates</code></pre>\n<aside class=\"callout\"><strong>Real-world lesson.</strong> In PH01 a ledger reconciled 95 existing Physics metadata records, 20 external 2025 locators and 87 preparation associations. Only 12 associations were author-nominated focused direct and six focused prerequisites; 13 were flagged weak. Zero authenticated or independently qualified items were claimed. Those historical counts describe one pinned candidate audit, not current platform status or a generic target. A count is not an academic verdict.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"sl1sl2\"><h2>06 \u00b7 Smart Skills: identity before cognitive claims</h2>\n<p>Use native Smart Labelling 1/2 and the actual contracts. SL1 establishes source identity, integrity, paper/key/figure correspondence and practice eligibility; these are separate gates. SL2 proposes the intellectual requirement of an exact task; it does not own independent QRT or scientific review. Read <a href=\"../docs/agent-entry/02-skills.md\">native skill entry</a> and <a href=\"../docs/smart-skills-integration.md\">integration contract</a>. The owner-local R2 candidates may not be installed or accessible remotely. Verify actual skill, version and checker output before claiming they were used.</p>\n<ol><li>Bind exact source occurrence, question revision, option order, figure revision, key version and source role. Run the appropriate SL1 integrity checker when available; preserve native report and its pins.</li><li>Optional real learner P1 is evidence only when the original unassisted response and exposure history exist. Static question analysis can proceed with P1 absent/unknown. Do not invent learner evidence or block learning solely because P1 is absent.</li><li>Write an independent solution as an author proposal before classifying. SL2 records the decisive work, shortest valid route, alternative routes and operations, conditions, factors, source role and evidence. Avoid retrofitting labels to pre-existing lessons.</li><li>Pass exact records to the separately appointed QRT reviewer; preserve source-only first pass if requested. If a real skill is unavailable, return an explicit candidate research ledger, not a fabricated native SL report or success.</li><li>Store native reports and reviewer receipts separately. A checker's exit zero is the selected mechanical gate only. No SL3, fabricated human review record or invented universal schema.</li></ol>\n<p>The authority chain is exact source \u2192 SL1 \u2192 proposed SL2 \u2192 independent QRT. The parallel source-exposition route still needs qualified warrants and the actual construction binder.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"solve\"><h2>07 \u00b7 Solve first: find the decisive construction W</h2>\n<p>Do not start writing a lesson from the final answer. For each exact source problem reconstruct the shortest valid route under its stated givens. Write what the learner must produce, what is already given, what must be inferred, and where an incorrect but plausible model diverges.</p>\n<ol><li>Transcribe the requested result and all constraints exactly, including figure axes, option semantics, units, physical/mathematical domain and answer multiplicity. Check if the statement is underdetermined or contradictory.</li><li>Solve with the simplest valid subject-appropriate law, definition, procedure or proof. Find a second shorter route, shortcut, symmetry, invariant, option-elimination route or counterexample where legitimate. A multiple-choice option can materially reduce work; score the real task including its options.</li><li>Identify the one move that most directly decides success. Ask: if the learner were given this move, would the remaining work become routine? Conversely, if only the prerequisite ideas were given, what decision still remains? Record competing operations and why the selected one wins.</li><li>Record the construction signature: ordered dependencies, direction of transformation, model/system and assumptions, representation invariant, decisive work, output/check and failure boundary. A signature is semantic, not a keyword match.</li><li>Separate intrinsic difficulty from language, arithmetic clutter, many subparts, optional help, unfamiliar terminology or learner-specific difficulty. If the shortest route is simpler, change the nomination instead of inflating the lesson.</li><li>Attach exact source role and scope. A source may be D2 while a separately authored transfer is D3/D4. Treat both as distinct scored tasks; do not rewrite original demand to match a desired cell.</li></ol>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">QRT slot</th><th scope=\"col\">Operational interpretation (resolve exact template)</th></tr></thead><tbody><tr><td>X</td><td>The precise crux, target, distinguishing condition, invariant or claim that the learner must confront.</td></tr><tr><td>Y</td><td>Prior demonstrated idea, relation, skill or anchor legitimately available to the learner; not the answer to this task.</td></tr><tr><td>Z</td><td>The route or bridge from Y toward X; support can orient without completing the decisive step.</td></tr><tr><td>W</td><td>The protected intellectual decision/inference/translation/bridge/warrant; what must remain learner-owned.</td></tr></tbody></table></div>\n<aside class=\"callout\"><strong>Example.</strong> A train-intercept source might be solved by a short positive-time tangency condition. An authored delayed-start/disjoint-window task additionally requires a constrained global minimum. They share a family but are not equal tasks. The original may be a short MODEL/APPLY candidate; the transfer may be a harder MODEL candidate after independent factor review.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"operations\"><h2>08 \u00b7 Seven operations: distinguish the decisive act</h2>\n<p>The seven labels form the current proposed common interface. Always consult the resolved Shared QRT template and applicable subject-specific column boundary; examples below explain the distinction, not an independent score. Do not label a task by the action word alone: a question that says 'explain' may demand a proof, and a long calculation may be APPLY.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Operation</th><th scope=\"col\">Protected W / evidence</th><th scope=\"col\">Core1A construction</th><th scope=\"col\">Core1B fresh move / common competing operation</th></tr></thead><tbody><tr><td>RETRIEVE</td><td>Select fact/category by defining condition; verdict plus discriminator.</td><td>Rule, condition, near-neighbour, trap, self-check.</td><td>Classify fresh cases with condition; if law choice decides, MODEL; execution, APPLY. D3.1 paused in current Physics.</td></tr><tr><td>EXPLAIN</td><td>Causal or mechanistic link from principle to outcome.</td><td>Principle \u2192 each warranted link \u2192 changed-condition prediction.</td><td>Fresh phenomenon; explain every link; proof of claim may be JUSTIFY, choice of law MODEL.</td></tr><tr><td>APPLY</td><td>Execute known relation with valid applicability and mapping.</td><td>Conditions \u2192 symbols/units/signs \u2192 execution \u2192 independent check.</td><td>Fresh data and applicability trap; if deciding which relation is central, MODEL.</td></tr><tr><td>MODEL</td><td>Select/formulate law, variables, system, assumptions or strategy.</td><td>Rival models \u2192 assumptions \u2192 discriminating evidence \u2192 short use.</td><td>Defend choice in unfamiliar case; if coordination of stages is decisive, SYNTHESIZE.</td></tr><tr><td>REPRESENT</td><td>Translate while preserving invariant or meaning.</td><td>Source-target correspondence in both directions; back-translation.</td><td>Construct fresh graph/equation/table/diagram; if translation is incidental, APPLY.</td></tr><tr><td>SYNTHESIZE</td><td>Find dependency, bridge quantity or ordering that coordinates ideas.</td><td>Stages \u2192 dependency map \u2192 justified bridge \u2192 complete route and check.</td><td>Fresh multi-stage construction; if one model choice alone decides, MODEL.</td></tr><tr><td>JUSTIFY</td><td>Prove/refute by warrant plus conditions; distinguish implication and converse.</td><td>Claim \u2192 law/definition and conditions \u2192 proof \u2192 boundary/counterexample.</td><td>Fresh claim or inverse constraint; examples alone do not prove a general claim; simple recall is not proof.</td></tr></tbody></table></div>\n<p>For every nomination ask which alternative operation would be most defensible on the shortest route, and what evidence falsifies the chosen label. Some exact tasks legitimately remain UNCERTAIN or MISMATCH until adjudicated. Do not split a single decisive question into seven artificial labels.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"difficulty\"><h2>09 \u00b7 Demand scoring and D3/D4 discipline</h2>\n<p>Score learner-owned work on the exact attempt or exam question, unassisted, against the authorized subject rubric. Shared Physics draft references the five 0\u20132 components below. Obtain the actual rubric anchors before deciding each integer; this table is a reading aid, not a replacement rubric for any subject.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Factor</th><th scope=\"col\">Question to ask</th><th scope=\"col\">Evidence to record</th></tr></thead><tbody><tr><td>Concept/model selection</td><td>Is the principle given, retrieved, discriminated or formulated?</td><td>List genuinely plausible models and the assumption decision.</td></tr><tr><td>Representation translation</td><td>Does success require mapping across representations or is a picture incidental?</td><td>Identify invariant, direction and exact correspondence.</td></tr><tr><td>Reasoning chain length</td><td>Which dependent steps must the learner connect?</td><td>Write the shortest dependency chain, not number of lines in the solution.</td></tr><tr><td>Algebra/computational load</td><td>What exact symbolic/numeric work remains after the decisive route?</td><td>Show simplification, elimination or symbolic burden; do not score arithmetic repetition twice.</td></tr><tr><td>Trap/exception sensitivity</td><td>Which plausible incorrect model or boundary reverses the result?</td><td>State the competing claim, condition and evidence needed to reject it.</td></tr></tbody></table></div>\n<p>For the current draft Physics rubric: D3 = 6\u20137, D4 = 8\u201310. The Shared rubric also records D1 0\u20132 and D2 3\u20135; D1/D2 teaching Blueprints remain SPEC_PENDING, not a license to invent them. Each factor has one grounded evidence sentence. Avoid double counting e.g. the same graph transform as both an unexplained model decision and a second full reasoning chain. Score the source, anchor, INSTANCE and MAIN independently as required; actual level may be below a tile band and must be labelled honestly.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">D3 candidate (Physics draft)</th><th scope=\"col\">D4 candidate (Physics draft)</th></tr></thead><tbody><tr><td>At least two connected ideas/conditions with a material dependency; important bridge remains learner-owned.</td><td>Unfamiliar transfer and/or exception/boundary/converse where familiar response fails; decisive abstraction/strategy/warrant remains learner-owned.</td></tr><tr><td>Teach components and bridge explicitly; support can orient component ideas.</td><td>Teach an exception construction and transfer contrast; support clarifies constraints/invariants without solving strategy.</td></tr><tr><td>Reject if direct substitution or rote fact solves the exact task.</td><td>Reject if a short standard formula or a single known rule bypasses the proposed higher demand.</td></tr></tbody></table></div>\n<aside class=\"callout\"><strong>Never force a band.</strong> D3.1 remains PAUSED in the referenced Physics program. D4.1, D4.2 and D4.3 are not automatically mandatory occupied cells. An empty cell with a documented gap is preferable to a mislabeled task. Subject-specific approved definitions take precedence. No fixed 21/28/42 or other historical program target becomes universal.</aside>\n<pre><code>QRT AUTHOR NOMINATION (not a native receipt)\ntask_id + exact content revision + source role:\nrequested output + given support:\nshortest valid route (steps and assumptions):\ncredible alternative routes / shortcuts:\nprimary operation + competing operation(s) + decisive W:\nX / Y / Z / W resolved from actual template:\nfactor 1..5: score, actual evidence, rubric reference:\nsum / proposed band / actual task scope:\nfalsifier: what shorter route or missing assumption changes the band?\nsource vs authored band separate; author status PROPOSED\nindependent QRT reviewer / receipt: HOLD until trusted external evidence</code></pre><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"blueprint\"><h2>10 \u00b7 Resolve the Blueprint without contaminating it</h2>\n<p>A Blueprint defines the cognitive and pedagogical architecture for a subject, independent of the topic. It binds a band \u00d7 operation cell to its QRT template, protected work, teaching/assessment anatomy, hint/picture/check objectives, evidence criteria and gap handling. The topic adapter instantiates disciplinary content; it is not a second Blueprint.</p>\n<p>Current reference: <a href=\"../templates/physics-blueprint/physics-blueprint.D3-D4.json\">Physics Blueprint v0.2.0</a>, DRAFT_OWNER_REVIEW, 14 D3/D4 cells; it references Shared 28 QRT templates (four bands \u00d7 seven operations), not 28 approved Physics teaching cells. Read the actual pinned Shared templates and rubric from the authorized native source; workspace copies may be unavailable remotely. Do not use Physics-specific cells, score calibration or WPE schemas as Mathematics/Chemistry authority.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Layer</th><th scope=\"col\">Stable responsibility</th><th scope=\"col\">Do not put here</th></tr></thead><tbody><tr><td>Shared</td><td>Canonical roles, identity, permissions, QRT interface and governance.</td><td>Topic facts or unilateral academic receipts.</td></tr><tr><td>Subject Blueprint</td><td>Cognitive cell, band protection, reusable anatomy and evidence criteria.</td><td>Topic values, named chapter examples or one-off fixes.</td></tr><tr><td>Disciplinary library</td><td>Reviewed law, proof, definition, model, mechanism, assumptions and limits.</td><td>Student status or inferred source admission.</td></tr><tr><td>Topic adapter</td><td>Context-specific models, variables, cases, representations, traps, anchors, tasks/checks and bindings.</td><td>Unilateral common rubric/cell changes.</td></tr><tr><td>Construction binder</td><td>Exact source/target/warrant/lesson/assessment B1\u2013B7 links.</td><td>Claim of semantic sufficiency merely from matching IDs.</td></tr><tr><td>Renderer / runtime</td><td>Project native records, persist and protect attempts, navigation.</td><td>Reclassify tasks or auto-approve a learner.</td></tr></tbody></table></div>\n<ol><li>Choose the actual subject, pinned Blueprint ID/version/digest, resolved cell template and authority status. Verify all dependencies, including native adapter/skill versions; equal version strings can have different bytes.</li><li>Read the complete cell and common rules, not only the column label. Identify required adapter slots, teaching anatomy, protected W, band carriers, picture stages, hint boundaries and evidence criterion.</li><li>Populate topic-specific slots and build against the existing schema. If a required reusable capability is missing, issue a Blueprint gap note to the Oracle/owner; builders change only the adapter within their authority.</li><li>Oracle adjudicates gap: ADAPTER_CAN_HOLD_IT, ACCEPTED with new Blueprint version, or REJECTED with reason. Pin new bytes, rebind and rebuild affected tiles; keep historical fixtures. Do not edit common rules just to make one task pass.</li></ol>\n<pre><code>BLUEPRINT GAP NOTE (actual Physics draft shape)\ngap_id, date, builder, tile_id, instance_or_question\nblueprint_version, adapter_version\ncould_not_build\nmissing_slot_or_rule\nchange_outside_adapter_needed\nproposed_blueprint_change\noracle_decision: ACCEPTED(new version) / REJECTED(reason) /\n                 ADAPTER_CAN_HOLD_IT(how)</code></pre><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"adapter\"><h2>11 \u00b7 Design and populate the topic adapter</h2>\n<p>Read <a href=\"../docs/agent-entry/03-blueprint-adapters.md\">adapter entry</a>. Resolve the selected subject's actual schema; below is a conceptual inventory. An adapter should make the Blueprint executable without smuggling in new authority. It contains topic-specific data and explicit bindings to scientific/disciplinary warrants, not vague prose like 'apply Newton's laws' or 'solve the equation'.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Operation slots (Physics reference; consult actual contract)</th><th scope=\"col\">What to bind</th></tr></thead><tbody><tr><td>Facts / RETRIEVE</td><td>Fact, deciding condition, holds/fails, near neighbour, trap cases, quick check, misconception, picture, fresh case axes.</td></tr><tr><td>Mechanisms / EXPLAIN</td><td>Phenomenon, principle, each causal link with warrant, changed-condition prediction, restatement trap and picture states.</td></tr><tr><td>Procedures / APPLY</td><td>Relation, applies/fails conditions, symbol/meaning/unit/sign mapping, condition traps, checks and safe ranges.</td></tr><tr><td>Models / MODEL</td><td>Candidate laws or systems, assumptions, discriminating features, applies/fails conditions, keyword lures and system choices.</td></tr><tr><td>Representation pairs / REPRESENT</td><td>From/to, invariant, correspondence rules, scale/sign/axes conventions, classic distortions.</td></tr><tr><td>Multi-step patterns / SYNTHESIZE</td><td>Stages, bridge, dependency order, ideas combined, independent second route/check, cross-topic owner.</td></tr><tr><td>Claims / JUSTIFY</td><td>Claim, law/conditions, derivation steps, where it fails, converse traps, counterexample.</td></tr><tr><td>All cells</td><td>Exact anchor, fresh task axes, diagrams with reasoning role, checks, source roles, prerequisites, scoring evidence, status and pins.</td></tr></tbody></table></div>\n<pre><code>ADAPTER BINDING (illustrative, not a replacement for schema)\nsubject_id / topic_id / adapter_id / version / SHA-256\nsubject_blueprint: ID/version/digest; QRT template ref\nsubtopic: stable ID, scope role, prerequisites, conventions\nconstruction signature: direction, X/Y/Z/W, decisive model/bridge\nwarrant IDs: claim, assumptions, domain, conditions, proof/check\noperation-specific slots: models/procedures/representations/claims...\nsource IDs and content revisions; source role; exact fit status\nCore1A worked-anchor IDs and teaching steps\nCore1B INSTANCE IDs / MAIN cell membership\nwrong-model IDs, diagnostics, repairs, boundary tests\nfigure input/authorship/rights, caption and reasoning step\ncandidate status, gaps, author and independent reviewer evidence</code></pre>\n<p>Record old and new adapter version/digest, exact target memberships, source and support revisions, and backwards-compatible historical paths. If one subtopic legitimately needs multiple instances in a cell, check the actual contract: the historical Physics Blueprint describes one per subtopic, while later authorized candidate contracts can differ. Do not silently override the pinned schema. Keep MAIN membership explicit and verify all bound instances rather than relying on a cell-label list.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"warrants\"><h2>12 \u00b7 Build the disciplinary claim and warrant register</h2>\n<p>A textbook passage is evidence for a candidate statement; a usable warrant states why that statement licenses a particular inference and when it does not. Reconcile official syllabus, text, examples, definitions, laws, figures and independent subject knowledge. Treat claims, conditions, derivations, applicability and exceptions as linked records.</p>\n<ol><li>Read exact exposition passages and relevant figures in context; separate the source wording from your original explanation. Record page/section locator, exact claim and source role. Respect copyright and use original diagrams/examples in learner content.</li><li>Normalize conventions and entities before deriving: units, signs, frames, variable domain, system boundary, reference state, idealizations, significant figures, notation and measurement limits as appropriate.</li><li>Derive or verify each relation from accepted principles. Check dimensional consistency, limiting cases, sign, conservation, mathematical domain, experimental assumptions and counterexamples. Where a proof or mechanism is not justified within level scope, state the prerequisite and source, do not hand-wave.</li><li>For Mathematics distinguish definition, axiom, theorem, proof, example and converse; specify variable domain and nonzero divisors. For Chemistry distinguish balanced stoichiometry, equilibrium versus kinetics, reaction conditions, species/charge, phase and measurement assumptions. For Biology distinguish mechanism, observational association, model/probability assumptions and exceptions. For Physics state system/frame, law, signs, conditions and limits. These examples guide review, not approved subject rubrics.</li><li>Link each warrant to the exact teaching derivation and task step it supports. Unreviewed scientific or disciplinary claims remain HOLD. If a source statement conflicts with a verified law/key, preserve both and request independent adjudication.</li></ol>\n<pre><code>WARRANT RECORD (conceptual)\nclaim_id / subject / subtopic / source_ref + exact locator\nstatement and law/definition/model\nassumptions and applicability conditions\nderivation or proof steps + reason for each\nunits/signs/domain/species/system conventions\nfails_when / limiting or counterexample witness\nindependent verification (calculation, alternative proof, reference)\nCore1A teaching step IDs / Core1B protected move IDs\nauthor status / scientific reviewer receipt / source rights status</code></pre><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"core1a\"><h2>13 \u00b7 Core1A: write a real textbook, not a task bank</h2>\n<p>Core1A should read as a coherent learning chapter. Start from a concrete phenomenon, example or disciplinary question, then develop conceptual understanding before procedures. A learner must be able to read each subtopic independently, reconstruct its reasoning and see how to check it. Do not make the learner chase unrelated links to understand a missing derivation.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Teaching sequence</th><th scope=\"col\">Evidence that must be visible</th></tr></thead><tbody><tr><td>1 \u00b7 Orient</td><td>Phenomenon/problem, why it matters, clear competency, conventions, knowns/unknowns; no exam answer leak.</td></tr><tr><td>2 \u00b7 Prerequisites</td><td>Short bridge for each needed idea, diagnostic or exact prerequisite link; no assumed invisible knowledge.</td></tr><tr><td>3 \u00b7 Build the idea</td><td>Ordered conceptual narrative: observation \u2192 model/definition \u2192 derivation \u2192 meaning \u2192 consequence. Each step has action and why valid.</td></tr><tr><td>4 \u00b7 Conditions and limits</td><td>Explicit applicability, assumptions, units/signs/domain, exception and comparison with a tempting wrong model.</td></tr><tr><td>5 \u00b7 Represent</td><td>Original labelled figure, table, graph or proof structure tied to a named reasoning step; explain correspondence and check.</td></tr><tr><td>6 \u00b7 Progressive examples</td><td>FOUNDATION: one idea; CONNECTED: link ideas; ADVANCED: changed context/condition and justified reasoning. These are teaching tiers, not automatic D-bands.</td></tr><tr><td>7 \u00b7 Worked anchor</td><td>Distinct completed example at intended actual demand, all learner steps and warrants visible, independent check, no reuse as protected task.</td></tr><tr><td>8 \u00b7 Misconception</td><td>Plausible wrong model, its tempting premise, separating question, repair and test that disproves it.</td></tr><tr><td>9 \u00b7 Exit and synthesis</td><td>Short retrieval/reasoning exit task with full answer and independent check; connect to next construction, Core1B and source return.</td></tr></tbody></table></div>\n<p>Write for a curious learner, not an expert who mentally fills missing steps. Explain why a relation applies, not just which formula to memorize. Use consistent variable names throughout. Make a sign convention visible before using negatives; derive a theorem before applying its converse; distinguish molecular and macroscopic pictures. Where a visual is unnecessary, record why rather than drawing decorative stock diagrams.</p>\n<p>For D3, teach component ideas and their bridge. For D4, add where the familiar rule fails and compare two different-looking situations with the same governing structure. A worked anchor may teach a general theorem; the Core1B must not merely ask the learner to reproduce that exact proof with different symbols. Plan the anchor and fresh task together but keep their data/unknowns and protected moves distinct.</p>\n<aside class=\"callout\"><strong>Author self-test.</strong> Remove the answer key and solve the proposed Core1B using only what Core1A explicitly teaches and authorized prerequisites. If you need an unstated principle, B3 is missing. If you can copy the worked anchor without choosing or reconstructing W, B4 is missing. Fix both before rendering.</aside><aside class=\"callout\"><strong>R2 Core1A submission test:</strong> the chapter must supply nine concrete teaching witnesses, a full science derivation and separate dimensional, limit and independent checks. Each witness requires a real file hash, verbatim excerpt and line reference in the <a href=\"../docs/agent-entry/quality-gate-r2/EVIDENCE_PACKET.template.json\">evidence packet</a>. Word counts, headings or answer-key style paragraphs are never proof of B3. See <a href=\"#evidence-gate-r2\">00A</a>.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"visuals\"><h2>14 \u00b7 Figures, representations and learner ergonomics</h2>\n<p>Every diagram has a job: clarify the situation (S1), connect prior knowledge (S2), or support construction without completing W (S3). Use the exact template's objective and preserve answer boundaries. Original source figures require separate custody and permission; do not redraw them and claim authenticity. For authored examples use original SVG or verified generated assets with accurate data and text equivalents.</p>\n<ol><li>Prepare a figure manifest: scene/representation ID, source or authorship, reasoning-step ID, data/coordinate convention, phase (GIVENS/ATTEMPT/RECONSTRUCT/ANSWER), alt/caption and rights. For graphs verify scale, axes, units, labels, slopes, vertices, areas and sign. For geometric drawings verify angle/length relationships or mark schematic. For Chemistry/Biology verify structures, entities, labels, mechanisms and direction.</li><li>Cross-check text, visual and numerical data against one another; a correct answer paired with an inaccurate diagram fails. A picture must not reveal the decisive model, completed target graph, option elimination or solution through title, alt text, tooltip, hidden DOM or filename.</li><li>Prefer original task-input figures bound to content revision. Show only givens before first attempt. Solution figures belong to reconstruction/answer phases. Provide equivalent givens in accessible text, not an answer transcript. Use readable labels (Physics draft guidance \u226514 px), meaningful contrast and non-color cues.</li><li>Render full-page responsive layouts; use real semantic headings, native controls, visible focus, descriptive links, touch targets around 44\u201348 px, accessible text alternatives, no clipped graph or horizontal page overflow. Test tablet portrait 1000\u00d71600 and landscape 1600\u00d71000 when applicable; include keyboard and touch.</li><li>Check the exact learner page over HTTP with real assets and JSON, not just a screenshot of local source. Distinguish source-preview, learner mode and reviewer/source notes; audit Conditions should not pollute learner instructions.</li></ol>\n<p>See <a href=\"production-checklist.html\">production checklist</a> and <a href=\"review-guide.html\">review &amp; audit guide</a>. Record visual checks and failing cases; an author-created figure can be useful even if original exam figure custody remains HOLD.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"freshness\"><h2>15 \u00b7 Core1B: engineer a genuinely fresh task</h2>\n<p>Core1B is not an extra solved example. The learner must perform the same construction family while confronting new conditions, target or representation that require independent reasoning. Match W and scientific coverage without cloning the route. Assess the unassisted task as it actually appears before any support; the anchor may explain the principle, not disclose the exact decisive response.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Novelty lever</th><th scope=\"col\">Good change</th><th scope=\"col\">Weak change</th></tr></thead><tbody><tr><td>Unknown direction</td><td>Forward explanation \u2192 inverse constraint or feasibility with independent validity check (only if teaching covers inverse reasoning).</td><td>Same formula and givens, solve same unknown with renamed objects.</td></tr><tr><td>Conditions</td><td>Change domain, sign, model regime, exception or competing assumption that changes decision.</td><td>Change values without changing decisive reasoning.</td></tr><tr><td>Representation</td><td>New source graph, table, equation or scene requiring preserved invariant.</td><td>Identical graph with relabelled axes, or already-completed target representation.</td></tr><tr><td>Dependency</td><td>New bridge/order or real integrated constraint whose solution requires multiple taught ideas.</td><td>Concatenate unrelated subquestions to raise score.</td></tr><tr><td>Warrant</td><td>New claim, necessary/sufficient condition, converse or counterexample.</td><td>Repeat exact theorem and proof already written in Core1A.</td></tr><tr><td>Check</td><td>Require independent check, domain rejection, limiting case or changed-condition transfer.</td><td>Answer supplied by hint, title or option pruning.</td></tr></tbody></table></div>\n<p>Construct task \u2192 solve without help \u2192 compare to anchor \u2192 search a shorter legitimate route \u2192 score \u2192 check the actual cell/coverage \u2192 revise. Do not force D4 merely by adding arithmetic. A mathematical proof may legitimately be harder due to new feasible-set reasoning; a short source formula may not be. Record what is held invariant and what is novel.</p>\n<pre><code>ANCHOR VS TRANSFER REVIEW\nanchor_id / exact anchor decisive move / taught prerequisite and condition\nfresh_task_id / distinct givens, unknown, context, representation, condition\ncommon construction signature and direction\nnew learner-owned W (not supplied by anchor or hints)\nshortest valid unassisted route + alternative route\nwhy a memorized anchor cannot answer the new task directly\nCore1A sufficiency check: all needed principles taught or valid prerequisites\ncandidate primary operation + five-factor evidence\nwrong model / separating evidence / repair / changed condition\nindependent B3/B4 adjudication: HOLD until reviewed</code></pre><aside class=\"callout\"><strong>R2 freshness enforcement:</strong> compare the exact worked anchor and the proposed protected problem as two complete texts, including W and shortest route. The validator detects obvious number swaps; the independent reviewer must still catch equivalent proofs disguised with different nouns, labels or contexts. A matching algorithm is B4 HOLD even when the answer is correct. Bind the comparison in <a href=\"../docs/agent-entry/quality-gate-r2/EVIDENCE_PACKET.template.json\">the R2 packet</a>.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"journey\"><h2>16 \u00b7 The six-stage Core1B learning journey</h2>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Stage</th><th scope=\"col\">Learner action</th><th scope=\"col\">Author's design / evidence</th></tr></thead><tbody><tr><td>1 \u00b7 Predict</td><td>Commit to a specific sign, model, outcome, relationship or condition before solving.</td><td>Prediction is meaningful and not a disguised hint; record it with first answer.</td></tr><tr><td>2 \u00b7 Attempt</td><td>Construct own response including W and a check.</td><td>Fresh task, givens-only visuals, no completed inference. Persist immutable first response before hint/reveal/help.</td></tr><tr><td>3 \u00b7 Reconstruct</td><td>Compare own reasoning with complete valid route.</td><td>Full post-attempt reasoning, alternative accepted routes, rubrics, warrants, rejected reasoning and independent check.</td></tr><tr><td>4 \u00b7 Diagnose</td><td>Identify first divergent inference in saved response.</td><td>Specific wrong models, discriminating questions, no diagnosis from wrong number alone. Self-report is not automatic misconception classification.</td></tr><tr><td>5 \u00b7 Repair</td><td>Rebuild the exact faulty step with correct model/condition.</td><td>Link to Core1A reasoning step and require revised reasoning saved separately; mark helped.</td></tr><tr><td>6 \u00b7 Boundary test</td><td>Solve a fresh changed condition before boundary model appears.</td><td>Change assumption, sign, limit, converse or representation; save boundary attempt and exposure before reveal; close with valid warrant.</td></tr></tbody></table></div>\n<p>Hints are optional support, not a parallel answer track. H1 CLARIFY: state the crux without making it. H2 CORRELATE: connect to a prior demonstrated idea Y. H3 OPEN_THE_WAY: orient the route Z while preserving W. Do not insert the final choice, decisive substitution, proof, answer or eliminations. In the PH01 protected runtime the stricter policy was H1\u2192H2\u2192H3 only after first response persisted; apply the actual authorized policy rather than weakening it. Record ordered exposure, including linked textbook/source, hints, reconstruction and boundary answer.</p>\n<p>Core1A can be read independently. In an attempt flow, clicking out to it must preserve accurate exposure history; help before attempt means the response is not unassisted. Do not assume that no in-app help log proves no external study. A learner who sees a solution and then repairs is learning, but that helped revision is not independent mastery. An answer without the operation evidence remains uncertain.</p>\n<aside class=\"callout\"><strong>Source return.</strong> Where a real authorized Core2 question exists, return to its exact identity and independently answer it before showing its own solution/key. A metadata link or locator-only record is not a native Core2 learner attempt. Never display a missing source as an authentic question, or expose its answer via a preparation link before its protected attempt.</aside><aside class=\"callout\"><strong>R2 live failure proof:</strong> capture actual HTTP Chromium evidence of help before initial submission, failed storage, retry without losing the first response, stale question revisions, and reveal gating. Each failed-save injection must show that the answer stayed closed. A prewritten stage script or a PASS field alone is insufficient; submit exact negative logs and browser receipts. See <a href=\"../docs/agent-entry/quality-gate-r2/AUTHORING_QUALITY_CONTRACT_R2.md\">section 4 of R2</a>.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"main\"><h2>17 \u00b7 Standalone subtopic units and integrated MAIN</h2>\n<p>Use the actual subject/owner contract. In the NSEJS PH01 workpack, the Owner required each M01\u2013M08 to have its own independent Core1A and Core1B HTML. Each route shows only its subtopic's INSTANCE tasks. MAIN is a separate chapter-level cycle for each populated cell, not a replacement for subtopic learning.</p>\n<ol><li>Build standalone Core1A narrative and Core1B scoped route for every authorized subtopic. Use precise IDs and scope selectors, a chapter overview, exact teaching anchors and source links. The learner need not navigate an unrelated subtopic to start.</li><li>For every target, bind the appropriate Core1A coverage and exactly the required INSTANCE cycle under the actual schema. Record source roles and actual bands separately; avoid using the same task identity for different prompts.</li><li>For each populated cell, inspect the pinned contract's MAIN requirement. In the NSEJS Physics C06 v1.1 candidate it is exactly one MAIN per cell, binding all instance target IDs with at least two distinct subtopics. Do not apply C06 as universal subject law.</li><li>Design a coherent MAIN problem whose genuine decisive work integrates the bound constructions: shared context, common state or dependent quantities, explicit model transfer. A list of independent mini-questions or a MAIN that merely references an instance ID without using its construction fails semantic integration.</li><li>Resolve infeasible membership through a new legitimate construction, corrected scope or explicit HOLD; never create arbitrary fillers to satisfy a mechanical count. If a new instance changes a cell, revise MAIN identity, membership, reasoning, boundary and support if needed. Keep historical MAIN and original responses.</li><li>Score MAIN on its own shortest valid route and actual operation. Independent reviewer must check whether all claimed instance families are materially exercised. Do not pretend exact membership proves actual integration.</li></ol>\n<p>For navigation, use stable relative links from chapter \u2192 subtopic lesson \u2192 scoped practice \u2192 exact source record and back. A user opening a source map should be able to identify the strongest focused route and see weaker/supplemental practice separately. If a source is not registered, route to a publisher-locator proposal rather than inventing a bank card.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"diagnosis\"><h2>18 \u00b7 Diagnose evidence, not the learner's personality</h2>\n<p>A wrong answer has multiple causes: misunderstood concept, wrong sign, model assumption, representation mapping, arithmetic slip, omitted reasoning, unclear prompt or guessed option. The diagnosis must be tied to the saved reasoning. Build a short error tree for each task.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Evidence pattern</th><th scope=\"col\">Diagnostic separator</th><th scope=\"col\">Repair</th></tr></thead><tbody><tr><td>Wrong governing model</td><td>Ask which assumption selects the model; compare a rival under changed condition.</td><td>Rebuild selection table and test discriminating feature.</td></tr><tr><td>Correct model, wrong representation</td><td>Ask what invariant maps to the target: slope, area, sign, correspondence, scale or entity.</td><td>Reconstruct element-by-element, then back-translate.</td></tr><tr><td>Correct expression, numerical slip</td><td>Ask learner to estimate or substitute back.</td><td>Repair arithmetic without falsely claiming misconception.</td></tr><tr><td>Correct number, missing warrant</td><td>Ask which condition makes inference valid; test a counterexample.</td><td>Reconstruct the warrant; record insufficient independent evidence until shown.</td></tr><tr><td>Generalization beyond domain</td><td>Ask whether the converse or removed condition holds.</td><td>Give valid counterexample or boundary proof, revise rule with domain.</td></tr><tr><td>Missing/empty answer or no reliable evidence</td><td>Do not diagnose; record MISSING, UNKNOWN or INSUFFICIENT_EVIDENCE as authorized.</td><td>Offer a suitable prerequisite or retry with exposure tracked.</td></tr></tbody></table></div>\n<p>Do not label a learner with MISCONCEPTION solely from a checkbox, one wrong numeric answer or an author-proposed wrong model. The blueprint's observations are DEMONSTRATED / UNCERTAIN / MISSING / UNKNOWN; use the actual vocabulary and scope. Do not automatically award DEMONSTRATED from a completed form, a correct answer with help, or a self-report. B6 is about quality of the diagnostic and changed-condition task, not a proof that a learner holds a particular idea.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"worked\"><h2>19 \u00b7 Worked design mini-cases across subjects</h2>\n<p>These are original, illustrative training examples for authors. They do not assert source authenticity, selected subject scope, approved QRT labels or band scores. Use the actual subject Blueprint and review to qualify any real task. Each mini-case contrasts an anchor with a possible fresh transfer and a falsifier.</p>\n<h3>Physics \u00b7 From measured acceleration to velocity and position</h3>\n<p>Anchor: teach a signed piecewise a\u2013t graph starting from v\u2080, area increments v, then v\u2013t area increments x. Work a single reversal and a zero-acceleration interval; independently check endpoint x and path. Transfer: new a\u2013t graph with different nonzero initial velocity and two reversals; construct v\u2013t and x\u2013t, split absolute area at each zero, compare with changed initial state. W is preserving the derivative/area relationship through interval boundaries. A student who sets v=0 when a=0 needs the specific repair \u201czero increment preserves carried state.\u201d A direct source problem with no reversal might be easier than the transfer. Candidate REPRESENT, not automatically D3.</p>\n<h3>Mathematics \u00b7 Linear constraints and inverse feasibility</h3>\n<p>Anchor: teach elimination for two independent linear equations, with a check by substitution and the rank/consistency idea. Example x+y=8 and x\u2212y=2 gives (5,3). Transfer: x+y=8 and 2x+2y=k, with x,y nonnegative integers; prove which k permits solutions, give the full feasible set, then add x\u2212y=2 and decide uniqueness. The second equation is dependent, not a second independent constraint; k=16 is necessary and sufficient, and the added equation selects one feasible pair. W is feasibility/warrant and independence, not rote elimination. Boundary: if k changes, no solution even though each equation alone has solutions. This is a mathematical example, not a Physics cell calibration.</p>\n<h3>Chemistry \u00b7 Limiting reagent, reaction conditions and inverse constraints</h3>\n<p>Anchor: teach mole ratios from a balanced reaction, limiting reagent by comparing reaction extents, excess and conservation; assume complete reaction under stated model. Original symbolic reaction 2A+B\u2192C, with A and B amount measured in moles and no side reaction. Transfer: available A=6 mol, B=b mol, measured C=2 mol at completion under the ideal model; determine feasible b, identify limiting reagent and leftovers. C=min(3,b); b=2, A remaining2 mol, B exhausted. Boundary: if yield is only 50% of theoretical, observed 2 mol is impossible because max theoretical3 gives max1.5. W may be MODEL/JUSTIFY depending on the exact givens and route; check atom/charge balance for a real chemical equation rather than treating abstract A/B/C as a named chemistry reaction. Do not infer kinetics or equilibrium from ideal stoichiometry.</p>\n<h3>Biology \u00b7 Conditional inference in inheritance (if authorized)</h3>\n<p>Anchor: under a single-locus complete-dominance model, teach genotype/phenotype, gamete probabilities and the Punnett representation. Transfer: a dominant-phenotype individual crossed with a known recessive homozygote produces a recessive offspring. Under the model and verified parentage the first parent must carry the recessive allele; infer genotype, then predict offspring probabilities and test changed penetrance assumptions. W is a conditional inference from observed outcome, not merely filling a table. One family sample does not guarantee future ratios; changed penetrance weakens the phenotype\u2192genotype inference. A Biology-specific reviewer and approved rubric would be required.</p>\n<aside class=\"callout\"><strong>Cross-subject lesson.</strong> Keep the transferable workflow and evidence discipline, not the Physics laws, factors' calibration or cell counts. Each subject's independent reviewer must evaluate actual assumptions and shortest routes. These mini-cases are author-exposed training material, never source-only review packets.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"binder\"><h2>20 \u00b7 B1\u2013B7: evidence join and falsifiers</h2>\n<p>Use the actual binder contract and evidence format; a field marked true or a matching ID is not proof. Provide a concrete witness and a way to falsify it for every requirement. B7 retains Physics/provenance wording in the Physics reference; in another authorized subject resolve the approved disciplinary/provenance analogue, not an invented schema migration.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Obligation</th><th scope=\"col\">Evidence witness</th><th scope=\"col\">Falsifier</th></tr></thead><tbody><tr><td>B1 \u00b7 Target</td><td>Exact task revision, scoped W, direction, source role, subject operation/demand and construction ID.</td><td>A keyword match or lower-level shortcut decides a different operation.</td></tr><tr><td>B2 \u00b7 Construction signature</td><td>Model/system/condition, dependencies, invariant/bridge, ordered reasoning and anchor-to-transfer join.</td><td>Direction or prerequisite differs; related topic does not carry same W.</td></tr><tr><td>B3 \u00b7 Teaching sufficiency</td><td>Exact Core1A steps, proof/derivation and example covering each required decision and limit.</td><td>A learner needs an untaught law or condition to complete fresh task.</td></tr><tr><td>B4 \u00b7 Fresh reconstruction</td><td>New task, different condition/unknown/representation, valid shortest route and novelty comparison.</td><td>Same anchor derivation with new nouns, answer in task header, or copied source stem.</td></tr><tr><td>B5 \u00b7 Attempt protection</td><td>Exact-revision browser evidence of persisted immutable original, ordered exposure, boundary gating, refresh and failure behavior.</td><td>Answer/graph/alt text leaks pre-attempt, failed storage still reveals, stale state imported.</td></tr><tr><td>B6 \u00b7 Diagnosis / changed condition</td><td>Specific wrong models with separator, repair linked to teaching, independently solved changed task.</td><td>Generic 'check your work', diagnosis from final number only, boundary merely repeats original.</td></tr><tr><td>B7 \u00b7 Physics/provenance or approved subject analogue</td><td>Law/proof/conditions independently reviewed, original source/key/figure custody, permissions and pin chain.</td><td>Wrong sign/units/domain, unresolved source collision, fabricated receipt, unlicensed asset.</td></tr></tbody></table></div>\n<p>Review B1\u2013B7 separately from seven noncompensatory gates: source authenticity, content correctness, cognitive qualification, teaching sufficiency, assessment validity, implementation and release authority. Any applicable missing evidence is HOLD; demonstrated contradiction is FAIL. A polished page, correct result, valid schema or green CI cannot compensate. An author packet is evidence for reviewers, not a human approval receipt.</p><aside class=\"callout\"><strong>R2 B1\u2013B7 join:</strong> append an evidence role and exact SHA-256/line quote to each declared witness; every role resolves in the <a href=\"../docs/agent-entry/quality-gate-r2/evidence-packet.schema.json\">packet schema</a>. The byte validator can expose fake references but cannot grade true Physics, teaching or demand. Independent R01 checks B1\u2013B7 and reports a scoped receipt; an author packet cannot set ACADEMIC_ACCEPTED.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"implementation\"><h2>21 \u00b7 Implement native records and learner runtime safely</h2>\n<p>Read actual schema/validator/runtime before writing. Native Shared records and source identifiers are not interchangeable with a topic's adapter. Use the actual subject namespace and versioned migration; historical WPE v1 and Physics candidate contracts are not general schemas. Prefer additive files and bounded changes, reuse appropriate shared runtime by agreement, and do not silently rename statuses or patch common rules to satisfy tests.</p>\n<ol><li>Write the source register, scope map, warrant records, topic adapter and target/instance bindings first. Then create teaching and attempt support records, route manifest, source preparation map, original figure manifest, review packet and handoff. Validate exact references, all IDs unique, source roles, membership, version/status invariants and no cross-subject leakage.</li><li>Keep the prior content and support bytes immutable; bind each attempt to task ID and exact content revision, including task input figures, hints, boundary solution and any other decisive inputs. Use a separate namespace or explicit reviewed migration for revised content. A new version must not silently inherit previous attempts or grant learner status.</li><li>Use a real persistence API with error handling; save prediction + first reasoning before any reveal. Maintain separate exposure, reconstruction, self-report, repair and boundary records. If storage is unavailable or a write fails, fail closed: no new hints, reconstruction, boundary answer or mastery event; preserve copyable input.</li><li>Validate unknown/duplicate/stale IDs and invalid revision/status at load. Render only the intended scope and exact requested cycle. Test bad/stale URL, malformed stored state, missing package/support, failed hash, storage denied/quota and network error. Show readable error, not a misleading success.</li><li>Keep learner content and review answers separated by phase. Browser local protection is educational workflow, not secure high-stakes invigilation: public JS/JSON can be inspected. Never claim tamper-proof exam security or automated academic grading. Avoid personal learner data in public files; preserve privacy.</li><li>Route from source to exact Core1A anchor and exact cycle, and back to exact source identity. Verify both directions at actual HTTP URLs. A canonical UID collision or missing bank item must remain visible; do not guess ID from question number or create a fake reverse link. Coordinate shared map/hub scripts with platform owner.</li></ol>\n<pre><code>Illustrative project outputs \u2014 use assigned real paths\nsource-register / scope-and-coverage ledger / source-gap register\ndisciplinary-warrants + topic-adapter + subject Blueprint pin\nnative package: targets, Core1A, Core1B INSTANCE/MAIN\nsupport: hints, boundary model, input figures + content hashes\nroute manifest + exact Core2 construction map\nchapter overview + each standalone textbook/practice + MAIN\nreview packet + native validator output + pytest/browser tests\nhandoff + unresolved gate ledger + release manifest (candidate only)\nhistorical version pins and previous route links</code></pre><aside class=\"callout\"><strong>R2 toolchain boundary:</strong> the canonical author submission is the <a href=\"../docs/agent-entry/quality-gate-r2/EVIDENCE_PACKET.template.json\">typed JSON evidence packet</a>; check exact bytes with <a href=\"../docs/agent-entry/quality-gate-r2/verify_evidence_packet.py\">the packet validator</a>. PR-level item/file coverage uses <a href=\"../docs/agent-entry/quality-gate-r2/enforce_pr_packets.py\">the production guard</a> only when the accepted Golden policy is ACTIVE. Do not silently treat PILOT_NOT_ENFORCED as required branch protection.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"qa\"><h2>22 \u00b7 Mechanical QA and adversarial tests</h2>\n<p>Run native validators and full repository tests, not just your new happy-path test. Use the actual configured Python versions and CI jobs. Preserve exact commit, tree, command/output, warnings, skips, failure logs and artifacts. Existing Physics workpacks used Python 3.11/3.12, pytest, native contract inspection and HTTP Chromium; other subjects must resolve their own native validation.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Test surface</th><th scope=\"col\">Required evidence / negative control</th></tr></thead><tbody><tr><td>Schema &amp; links</td><td>Missing/wrong schema, invalid source role, duplicate ID, dangling prerequisites, cross-subject reference, unbound target, missing MAIN member, unknown cell, stale version rejected.</td></tr><tr><td>Identity &amp; history</td><td>Exact original and previous package/support SHA-256 (or explicitly Git blob pins); changed content invalidates stale attempt; prior URLs remain readable. Hash type labelled correctly.</td></tr><tr><td>Correctness witnesses</td><td>Exact arithmetic or proof witness, units and sign, domain, limiting cases, independent check; use rational arithmetic where helpful. Tests do not replace disciplinary review.</td></tr><tr><td>Freshness</td><td>Compare old/new task prompt, inputs, W and boundary; verify original anchor and task differ; independent novelty still required.</td></tr><tr><td>Prompt figures</td><td>Actual original input graph values match text, accessible labels; no solution before attempt; changing cycle clears old figures.</td></tr><tr><td>Scoped routes</td><td>All subtopic selectors exact, MAIN separate, chapter links, exact source and return, external locator not misrepresented as canonical.</td></tr><tr><td>Full journeys</td><td>Both tablet orientations: predict, save first, lock original, H1\u2192H3, reconstruct, self-report, repair, save boundary, reveal, refresh; exercise each new INSTANCE and each revised MAIN.</td></tr><tr><td>Help and state</td><td>Pre/post linked-help tracking, immutable original, exposure on boundary, no assisted mastery, storage denied/failed writes, stale revisions and copyable unsaved input.</td></tr><tr><td>Accessibility</td><td>Keyboard focus/activation, touch, page width, readable labels, text alternatives, responsive graphs, no overlapping or inaccessible controls.</td></tr><tr><td>Failure handling</td><td>Network/asset errors, corrupted content/hash, missing storage, invalid status and wrong scope must fail closed. No tests silently skipped or hidden.</td></tr></tbody></table></div>\n<pre><code># Adapt commands to the actual repository and selected contracts\ngit status --short\ngit rev-parse HEAD\npython -m pytest -q\n# Run the native validator for the selected package, after checking --help.\n# Serve repo over HTTP using the repository's documented QA entry.\n# Run actual Chromium/Playwright suite for exact scoped HTML journeys.\n# Record command, exact commit, exit code, stdout, warnings, artifacts.</code></pre>\n<p>Do not use a successful old commit as proof of a changed one. For a documentation-only revision report its own checks and note which learning bytes are unchanged. Distinguish test added, test executed, PASS and NOT_RUN. CI green does not authorize academic release. See <a href=\"review-guide.html\">Review &amp; Audit Guide</a> and <a href=\"../docs/agent-entry/05-qa-publication.md\">QA/publication entry</a>.</p><aside class=\"callout\"><strong>R2 negative controls:</strong> Golden Sample = eight injected fault families. Routine items = wrong-dimension, numeric-clone and hint-leak negatives, plus batch-wide protected-state/figure tests. Each test needs a real mutation, command and observed rejection log linked to the exact source revision. The <a href=\"../tests/test_physics_quality_gate_r2.py\">adversarial suite</a> tests the gate, not the academic quality of an authored lesson.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"review\"><h2>23 \u00b7 Independent review, separation and release</h2>\n<p>Separate author, technical reviewer and academic/QRT reviewer. The Owner/Shared authority decides admission and release; neither author nor validator can manufacture external human receipts. Labels such as R00 technical and R01 independent academic are workpack-specific, not automatically appointed roles.</p>\n<ol><li>Author hands off exact head, immutable artifact pins, source registers, candidate W/band and competing routes, anchor-versus-transfer novelty, B1\u2013B7 evidence, source custody gaps, tests and explicit limitations. This is author-exposed material.</li><li>Technical reviewer checks implementation, exact package and native contracts, complete browser journeys, leakage, state, source route and failure controls. Report REQUEST_CHANGES or scoped technical pass/HOLD with exact SHA and reproducible finding; not academic approval.</li><li>For a cold first pass, dispatcher supplies only exact source/task/figure inputs, approved subject rubric, scope and seal destination. Withhold author solutions, keys, labels, review packet and prior exact-task outcomes. Reviewer independently solves, records conditions, shortest alternatives, W, five factors and ambiguity; seal bytes/digest before revealing prior material. If exposed, disclose, do not claim blindness.</li><li>Separately reconcile source fidelity, scientific correctness, QRT/source role, teaching sufficiency, freshness, protected attempts and diagnosis/transfer. A source key conflict requires independent reconciliation, not silent alteration. Review exact new versions after changes; prior approval is not inherited.</li><li>Owner verifies rights/privacy, trusted reviewer scope and digest, source eligibility, applicable gate outcomes, deployment destination and explicit release authorization. Missing or stale evidence is HOLD, contradiction FAIL. Do not merge/deploy protected content because a user asked for draft authoring or because tests passed.</li></ol>\n<aside class=\"callout\"><strong>Independent reviewer route.</strong> Use <a href='../docs/agent-entry/07-independent-review.md'>source-only entry</a> for a sealed academic first pass. This page and any author solution packet are not suitable before sealing. Never auto-create an approval receipt, infer review authority from a name, or rename an author to create independence.</aside><aside class=\"callout\"><strong>R2 authority correction:</strong> the Owner selects and approves <em>one complete Golden exemplar/standard</em>, not every new question. Delegated R00 technical and separate independent R01 Physics/QRT reviewers handle continuing risk-based batches using <a href=\"../docs/agent-entry/quality-gate-r2/REVIEWER_AND_GOLDEN_TEMPLATES.md\">reviewer-owned forms</a>. If the reviewer previously authored the task or saw its key, disclosure is mandatory and that review cannot be labelled blind. Return exact task SHA and specific defects.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"batch\"><h2>24 \u00b7 Batch strategy, coverage closure and corrections</h2>\n<p>Work in coherent slices sized for exact verification. Batch by shared construction, not by arbitrary question count: finish source-gap analysis, teaching, fresh tasks, MAIN membership, route, native tests and browser tests in the same revision. Avoid task inflation after a reviewer asks for corrections.</p>\n<ol><li>Baseline: read previous green head and reviewer comments. Distinguish actual approved content from author candidate work; identify pending test and review gates.</li><li>Select highest-impact source gaps: missing decisive construction, weak primary link, source role confusion, untested main journey or repeated anchor. Make a traceable acceptance table before implementing.</li><li>Implement a bounded group of related construction gaps with exact source IDs and new task IDs. Preserve earlier working versions. If source identity isn't authorized, use locator-only proposals and keep counts separate.</li><li>Revisit affected MAIN tasks and scoped routes; update teaching/adapter/support/ledger and native/browser regression together. Run exact-head tests, fix failures before expanding. Report any partial commit or unfinished batch explicitly.</li><li>After engineering tests, hand off to independent review, not another expansion by default. If review identifies stale source, nonfresh assessment, wrong primary operation or missing test, correct that specific flaw in a new revision, reverify and disclose the changed scope.</li><li>Complete the corpus audit even for excluded rows; report unscreened years, dropped items, secondary evidence, unresolved collisions, cross-topic owners and source gaps. Only claim closure at the level evidenced: author construction implemented vs independently qualified vs released.</li></ol>\n<p>PH01 lessons that generalize: a theorem copied into the protected task was mathematically correct but insufficiently fresh; MAIN selectors alone did not test complete journeys; a source URL resolved to a different paper; an external year was absent from the registry; and broad preparation links inflated apparent coverage. Corrective work introduced inverse designs, full journey tests, explicit paper locators and a separate association ledger. These are workflow lessons, not authority for a particular subject or current release.</p><aside class=\"callout\"><strong>R2 batch gate:</strong> freeze candidate UIDs and revisions before reviewer selection; require grounded packets for <em>every</em> changed item, an independently selected deterministic sample of at least 20% and one per topic, and 100% review for new Physics laws, D4 proofs, key disputes, failures and P0/P1 risk triggers. Unsampled items must not be described as individually reviewed. No routine Owner-per-question signatures.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"templates\"><h2>25 \u00b7 Reusable workpack and handoff templates</h2>\n<p>Copy these conceptual templates into the assigned artifact structure. They do not replace native schemas or approve new fields. All example statuses are candidate/HOLD. Record actual evidence rather than filling a checkbox with optimistic prose.</p>\n<h3>A \u00b7 Construction record and coverage row</h3><pre><code>subject / topic / subtopic / construction ID\nlearning goal + prerequisite IDs + direction\nsource locator / canonical UID (nullable) / content revision\nsource role / scope disposition / source evidence status / rights\nsource W / shortest source route / proposed operation + band\nsubject Blueprint + QRT template + adapter + warrant pins\nCore1A step IDs / anchor / figures / exit / misconception IDs\nCore1B fresh task ID / actual W / novelty / factors / proposed cell\nhint H1-H3 / diagnosis / repair / boundary / independent checks\nMAIN membership and actual integration witness\nB1-B7 evidence references / seven gate statuses / reviewers / gaps\nsource-to-task fit: author nomination, independent HOLD</code></pre>\n<h3>B \u00b7 New agent workpack prompt</h3><pre><code>You are [author role], assigned ONLY [subject/topic/subtopics].\nRead AGENTS.md, Start_here.md, CURRENT_CHECKPOINT.md, master issue,\nproduct scope, required-reading map, architecture guide and actual\nsubject contracts. Pin exact baseline and list unavailable authority.\nDo not merge/deploy or alter another topic/shared runtime without scope.\n\n1. Inventory existing Core2 and source corpus; separate scope and custody.\n2. Independently solve exact tasks, propose shortest W, operation and\n   five factors under the pinned subject rubric; document alternatives.\n3. Build exposition claim/condition register and topic adapter.\n4. Join actual source requirements to Core1A textbook constructions.\n5. Design genuinely fresh Core1B INSTANCE and coherent MAIN; protect W,\n   diagnose specific wrong models, repair and test changed conditions.\n6. Implement native records and independent scoped HTML routes.\n7. Run exact native/pytest/HTTP browser tests; preserve previous bytes.\n8. Return candidate coverage ledger, review packet, exact head/test\n   evidence, blockers, decisions and explicit no academic approval.\nStop at unsupported authority; do not invent source IDs or fill bands.</code></pre>\n<h3>C \u00b7 PR / author handoff</h3><pre><code>Task / master-issue subsection / exact authorization:\nScope / subject / subtopics / exclusions:\nBase SHA + head SHA + tree / version + digest pins:\nFiles changed and behavior:\nSource research and evidence limitations:\nCoverage denominators (registry, external locators, authenticated items,\n  direct/bridge/authored, associations, focused/weak, D3/D4, MAIN):\nConstruction signatures / shortest routes / W and factor nominations:\nCore1A sufficiency / Core1B novelty / MAIN integration witnesses:\nB1-B7 evidence + separate gate matrix:\nNative CLI examples + verbatim outputs / full pytest / browser runs:\nFailures, warnings, skipped/not-run tests / unresolved gaps:\nPrior versions/attempt retention / shared-owner coordination:\nIndependent reviewer roles and requested exact-head decisions:\nRights/privacy/release authorization status:\nNo academic approval inferred from software validation.\nNo merge/deploy unless separately authorized.</code></pre>\n<h3>D \u00b7 Reviewer request (author-exposed technical handoff)</h3><pre><code>Exact target commit and changed artifact digests:\nReview scope: technical / scientific / QRT / teaching / assessment\nPrior known defects and acceptance requirements:\nReproducible test steps and expected outcomes:\nSpecific B1\u2013B7 evidence/falsifiers:\nDecision requested per gate, with findings and exact SHA:\nKeep author material separate from cold source-only reviewer packet.</code></pre><aside class=\"callout\"><strong>R2 copy/paste contract supersedes loose completion prose:</strong> start with the <a href=\"../docs/agent-entry/quality-gate-r2/EVIDENCE_PACKET.template.json\">actual complete JSON template</a>, not only the conceptual records below. Submit the typed evidence packet and the separate <a href=\"../docs/agent-entry/quality-gate-r2/REVIEWER_AND_GOLDEN_TEMPLATES.md\">R00/R01/Golden/Batch receipt forms</a>. Retain each exact artifact hash and its quotations. The unfilled template intentionally fails validation; authors must not hand-edit the validator to make it pass.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"done\"><h2>26 \u00b7 Definition of done and failure checklist</h2>\n<p>A workpack is not done merely because files exist. Use this checklist on the actual authorized scope. An unselected Blueprint, source conflict or lack of independent review may prevent academic completion even when candidate engineering is complete.</p>\n<div class=\"table-wrap\"><table><thead><tr><th scope=\"col\">Must be evidenced</th><th scope=\"col\">Reject / HOLD when</th></tr></thead><tbody><tr><td>Scope and corpus declared, every registry row dispositioned, external corpus gaps explicit.</td><td>Keyword search only, denominator omitted, duplicates counted as originals.</td></tr><tr><td>Source identity/figure/key and rights distinct; metadata vs authenticated counts clear.</td><td>Original unavailable, invented ID, dropped item counted, secondary copy treated as original.</td></tr><tr><td>Every direct source has shortest W, operation/band proposal and construction fit or explicit gap.</td><td>Task band assumed from exam, no competing route, forced cells.</td></tr><tr><td>Qualified warrant/condition register and complete teaching narrative.</td><td>Formula dump, missing proof/conditions, unreviewed scientific claim.</td></tr><tr><td>Core1A worked anchor and genuinely distinct Core1B assessment, all six stages.</td><td>Identical proof or target graph revealed; generic repair or boundary.</td></tr><tr><td>All applicable INSTANCE targets and genuinely integrated MAIN under actual contract.</td><td>One giant page, arbitrary filler, membership only, wrong scope.</td></tr><tr><td>Exact routes, original figures, protected persistence, full native/HTTP tests on exact revision.</td><td>Old green result, selector-only MAIN, storage leak, inaccessible page.</td></tr><tr><td>Independent scientific/QRT/B1\u2013B7 and technical reviews, rights/privacy/release approval.</td><td>Author self-certification, stale/forged receipt, incomplete source or release gate.</td></tr></tbody></table></div>\n<div class=\"callout\"><strong>Final reporting language:</strong> \u201cCandidate implementation complete for the stated scope; exact tests [actual results]; source authenticity / academic qualification / release [actual gate states].\u201d If implementation is partial, say what remains. Do not call a subject finished while direct-question scope, exact fit or academic gates are unresolved.</div>\n<p>Required next decision belongs to the assigned reviewer or Owner. Stop at the boundary of your authority.</p><aside class=\"callout\"><strong>R2 Definition of done:</strong> author packet byte-grounded <em>AND</em> scientific warrant independently accepted <em>AND</em> Core1A teaching judged substantive <em>AND</em> Core1B fresh, protected and tested <em>AND</em> accurate Core2 item/source status <em>AND</em> delegated review/Golden policy satisfied. Any absent applicable witness is HOLD, even if every existing HTML/UI/Python check is green. During PILOT, report the R2 policy as NOT ENFORCED.</aside><a class=\"back-top\" href=\"#top\">Back to contents</a></section>\n<section class=\"field-section\" id=\"references\"><h2>27 \u00b7 Authority, references and actual reading order</h2>\n<p>This guide is a synthesis of the repository's authoring and review requirements, not a new specification. Resolve the current version at your actual base. Links below are navigation to repository documentation; protected owner-local sources referenced in those documents may not exist on the public site.</p>\n<ol><li><a href='../AGENTS.md'>Repository instructions</a>, <a href='https://github.com/reallakshman19/Grade9v4.0/issues/1'>master Issue #1</a>, <a href='../Start_here.md'>Start_here</a>, <a href='../CURRENT_CHECKPOINT.md'>checkpoint</a>, <a href='../docs/product-scope.md'>product scope</a> \u2014 authority and constraints.</li><li><a href='../docs/agent-entry/00-required-reading.md'>Required reading</a>, <a href='../docs/agent-entry/CURRENT_PATHS.json'>active path map</a>, <a href='../docs/agent-entry/CURRENT_WORKFLOW.json'>workflow dependencies</a>, <a href='../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md'>current companion</a>, <a href='../docs/agent-entry/concept-report-v4.html'>concept report</a> \u2014 conceptual and version history.</li><li><a href='../docs/agent-entry/01-source-intake.md'>Source intake</a>, <a href='../docs/agent-entry/02-skills.md'>SL1/SL2</a>, <a href='../docs/smart-skills-integration.md'>native integration</a> \u2014 actual skill contracts and evidence gates.</li><li><a href='../docs/agent-entry/03-blueprint-adapters.md'>Blueprint/adapter entry</a>, <a href='../templates/physics-blueprint/physics-blueprint.D3-D4.json'>Physics draft Blueprint</a>, <a href='../schemas/v2/subject-intake.schema.json'>candidate v2 intake envelope</a> \u2014 resolve subject-specific authority; do not reuse Physics assumptions in other subjects.</li><li><a href='../docs/agent-entry/04-output.md'>Native output construction</a>, <a href='guidebook.html'>Architecture guidebook</a>, <a href='core2-source-to-learning-pipeline.html'>Pipeline flowchart</a> \u2014 two routes and binder.</li><li><a href='review-guide.html'>Review & audit guide</a>, <a href='production-checklist.html'>Production checklist</a>, <a href='../docs/agent-entry/05-qa-publication.md'>QA/publication</a>, <a href='../docs/agent-entry/07-independent-review.md'>source-only independent review</a> \u2014 exact review scope and release boundaries.</li><li><a href='https://github.com/reallakshman19/Grade9v4.1/pull/10'>PH01 author candidate PR #10</a> \u2014 historical case-study only, author-exposed, not a qualified exemplar. Read exact pinned review evidence if authorized.</li></ol>\n<p>Guide prepared as documentation at repository base <code>218b9f2da4b71e0eb03d6769c8ad6c842434e652</code>. Master Issue #1 returned HTTP 404 through the connected GitHub session during this documentation pass; owner-local source archive and native reviewer receipts were not available. This is a proposed operational guide, not a change to Shared, a new academic standard, or authorization to release. Subject-specific contracts and current Owner instructions take precedence.</p><p><strong>Physics-specific R2 integration (after Golden adoption):</strong> <a href=\"../docs/agent-entry/quality-gate-r2/README.md\">Quickstart</a> \u2192 <a href=\"../docs/agent-entry/quality-gate-r2/AUTHORING_QUALITY_CONTRACT_R2.md\">authoring quality rules</a> \u2192 <a href=\"../docs/agent-entry/quality-gate-r2/EVIDENCE_PACKET.template.json\">evidence packet</a> / <a href=\"../docs/agent-entry/quality-gate-r2/evidence-packet.schema.json\">schema</a> \u2192 <a href=\"../docs/agent-entry/quality-gate-r2/verify_evidence_packet.py\">validator</a> \u2192 <a href=\"../docs/agent-entry/quality-gate-r2/REVIEWER_AND_GOLDEN_TEMPLATES.md\">independent and delegated review</a> \u2192 <a href=\"../docs/agent-entry/quality-gate-r2/quality-policy.v1.json\">actual activation policy</a>. These draft addenda are not, by themselves, new academic authority or global cross-subject requirements.</p><a class=\"back-top\" href=\"#top\">Back to contents</a></section></article>",
  "guidebook": "<div class=\"status\"><strong>How to use this book</strong><p>This is a <b>documented decision protocol</b> and source map, not a hidden reasoning transcript, an adopted Shared contract, an academic reviewer receipt or authorization to run native promotion. It summarizes the current repository sources; source-specific uncertainties remain HOLD. A fresh blind reviewer must use the <a href=\"../docs/agent-entry/07-independent-review.md\">source-only entry</a> instead of this author-exposed guidebook.</p></div>\n<div class=\"guide-layout\"><aside class=\"toc\" aria-label=\"Guidebook contents\"><b>Guidebook contents</b>\n<a href=\"#map\">00 \u00b7 Whole process</a><a href=\"#scope\">01 \u00b7 Scope and authority</a><a href=\"#subtopic\">02 \u00b7 Subtopic and task identity</a><a href=\"#source\">03 \u00b7 Source custody</a><a href=\"#two-routes\">04 \u00b7 Two evidence routes</a><a href=\"#sl\">05 \u00b7 SL1, optional P1 and SL2</a><a href=\"#demand\">06 \u00b7 Demand factors</a><a href=\"#qrt\">07 \u00b7 Independent QRT</a><a href=\"#thought-protocol\">08 \u00b7 Decision protocol</a><a href=\"#blueprint\">09 \u00b7 Blueprint and adapter</a><a href=\"#warrants\">10 \u00b7 Warrants and conditions</a><a href=\"#core2\">11 \u00b7 Native Core2</a><a href=\"#binder\">12 \u00b7 B1\u2013B7 / Core1A and Core1B</a><a href=\"#checks\">13 \u00b7 Checks and balances</a><a href=\"#example\">14 \u00b7 Worked WPE illustration</a><a href=\"#handoff\">15 \u00b7 Evidence handoff</a><a href=\"#sources\">16 \u00b7 Primary source index</a><a href=\"core2-source-to-learning-pipeline.html\">Core2-led pipeline \u2197</a><a href=\"review-guide.html\">Review &amp; audit guide \u2197</a><a href=\"production-checklist.html\">Production checklist \u2197</a></aside>\n<div>\n<section class=\"chapter\" id=\"map\"><h2>00 \u00b7 The whole method on one page</h2><p>Navigation often reads \u201csubtopic \u2192 demands \u2192 QRT \u2192 Core1A.\u201d That is a useful <em>learner-content planning view</em>, but not the full academic dependency chain. The <strong>subject\u2019s authority, Blueprint and topic adapter must be consulted before task classification</strong>; and source exposition reaches Core1A through a distinct route.</p>\n<div class=\"flowchart\"><pre>SUBJECT: Physics / Mathematics / Chemistry\n     \u2193 current Shared rules + subject Blueprint + topic adapter\nCHAPTER \u2192 SUBTOPIC / prerequisite construction\n     \u251c\u2500 QUESTION ROUTE: exam + textbook questions\n     \u2502    exact task \u2192 SL1 \u2192 optional P1 \u2192 SL2 proposal\n     \u2502    \u2192 independent QRT operation / demand / source role\n     \u2502    \u2192 qualified native Core2 question\n     \u2502\n     \u2514\u2500 EXPOSITION ROUTE: book text + syllabus + figures\n          exact source units \u2192 condition/claim register\n          \u2192 candidate scientific or disciplinary warrants\n          \u2192 construction obligations (+ reviewed task join)\n     BOTH \u2192 QUALIFIED BINDER + B1\u2013B7\n          \u2192 Core1A sufficient teaching\n          \u2192 Core1B fresh protected reconstruction\n     ALL \u2192 independent QA + Owner / Shared release\n</pre></div>\n<div class=\"callout\">A line in this diagram is an <strong>evidence dependency</strong>, not an automatic approval. In the Owner\u2019s current WPE work, the authoring order remains Core2 completion \u2192 Owner scope acceptance \u2192 Core1A \u2192 Owner acceptance \u2192 Core1B, while properly scoped book preparation can happen in parallel. D3.1 remains PAUSED.</div>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Current companion</a> \u00b7 <a href=\"../docs/agent-entry/CURRENT_WORKFLOW.json\">Current workflow dependency map</a> \u00b7 <a href=\"../docs/agent-entry/concept-report-v4.html#current-workflow-2026-11-02\">Dated concept-report addendum</a>.</p></section>\n<section class=\"chapter\" id=\"scope\"><h2>01 \u00b7 Start with the scope and decision owner</h2><p><strong>Three subject tabs, separate authority.</strong> The Shared layer controls canonical records, roles, governance and release. Each subject needs an appropriate Blueprint, qualified disciplinary library and topic adapters. Physics/WPE is a pilot; it does not transfer Physics demand scores or laws to Mathematics or Chemistry.</p><table><thead><tr><th>Layer</th><th>Owns</th><th>Cannot infer</th></tr></thead><tbody><tr><td>Shared</td><td>Canonical IDs, permissions, six-Core boundaries, publication authority</td><td>Subject correctness from a schema match</td></tr><tr><td>Subject Blueprint</td><td>Operation/demand teaching architecture and cognitive tile requirements</td><td>Qualification from a \u201cdraft\u201d version number</td></tr><tr><td>Topic adapter + library</td><td>Topic-level law, limits, examples, misconceptions and representation binding</td><td>A universal cross-subject method</td></tr><tr><td>Independent QRT</td><td>Exact-task operation, intrinsic demand, source/coverage role</td><td>Final examination authenticity or Owner release</td></tr><tr><td>Grade9QA</td><td>Mechanical evidence reconciliation, B1\u2013B7 checks and HOLD/FAIL reporting</td><td>A human subject reviewer or approval receipt</td></tr></tbody></table>\n<p><strong>Before doing work, record:</strong> subject; scoped chapter/subtopic; exact role and Owner instruction; active version/hash pins; intended output and release boundary. Mark missing authorized selection as HOLD.</p>\n<p class=\"source\">Basis: <a href=\"../docs/product-scope.md\">Product scope</a> \u00b7 <a href=\"../AGENTS.md\">Repository rules</a> \u00b7 <a href=\"../docs/implementation-status.md\">Current engineering status</a>.</p></section>\n<section class=\"chapter\" id=\"subtopic\"><h2>02 \u00b7 From chapter to subtopic\u2014without losing the task</h2><p>A <b>subtopic</b> describes the conceptual construction to teach (for example, signed work from force and displacement). A <b>question/task</b> is an exact source item that may demand that construction, perhaps with additional conditions. A <b>representation</b> is an explanatory or problem-specific diagram. These are related, not interchangeable IDs.</p><ol><li>Choose the subject and chapter from an authorized scope. Physics \u2192 WPE exists; no first Mathematics or Chemistry chapter is approved.</li><li>Give each construction a bounded competency: what learner-owned transformation or judgment should be possible later?</li><li>Record prerequisites and the directional distinction (e.g. from potential to force is not proof of the reverse from force to potential).</li><li>Identify exact source tasks only through their individual identities; do not assign a blanket D-band to a whole subtopic.</li><li>Keep authored practice examples separate from authenticated direct-exam evidence.</li></ol><div class=\"callout good\"><strong>Output:</strong> a subject/chapter/subtopic construction statement, prerequisites, source role and explicit unresolved dependencies\u2014not yet an approved lesson or QRT cell.</div><p class=\"source\">Basis: <a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Two-route companion</a> \u00b7 <a href=\"../docs/product-scope.md\">Subject namespace requirements</a>.</p></section>\n<section class=\"chapter\" id=\"source\"><h2>03 \u00b7 Source-based requirements and exact custody</h2><p>Every claim starts with an identified occurrence, immutable or versioned source bytes where available, locator and declared provenance. <strong>Scientific correctness, official examination identity and answer-key custody are three different judgments.</strong></p>\n<table><thead><tr><th>Input</th><th>Minimum record</th><th>Important HOLD</th></tr></thead><tbody>\n<tr><td>Exam question</td><td>Paper, session, exact task/variant, question text, options, figures, answer-key source and separately verified identity</td><td>Coaching solution \u2260 authenticated official key; an image placeholder \u2260 original figure</td></tr>\n<tr><td>Textbook question</td><td>Book/edition/page/problem number, exact stem, figures, rights, source classification</td><td>A book problem \u2260 past examination evidence</td></tr>\n<tr><td>Exposition / syllabus</td><td>Exact passage/page/figure and scope of each candidate claim</td><td>Source wording \u2260 fully qualified general law</td></tr>\n<tr><td>Authored transfer</td><td>Author, version, synthetic designation, reproducible physical assumptions</td><td>May teach/check a construction, but does not fill direct-exam target slots</td></tr>\n</tbody></table>\n<p><strong>Protocol:</strong> collect \u2192 fingerprint \u2192 resolve duplicate versus variant \u2192 bind exact figure/key independently \u2192 document rights and source role \u2192 fail closed. Where original graphs are missing, create a recovery task; do not substitute a newly drawn diagram and claim the original was authenticated.</p>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/01-source-intake.md\">Source intake</a> \u00b7 <a href=\"../docs/smart-skills-integration.md\">SL1 source/key distinction</a> \u00b7 <a href=\"../preview/batches/b08-source-gates.json\">Example unverified graph cases</a>.</p></section>\n<section class=\"chapter\" id=\"two-routes\"><h2>04 \u00b7 Two evidence routes meet at a construction requirement</h2>\n<div class=\"cards two\"><article class=\"card\" style=\"min-height:unset\"><small>ROUTE A \u00b7 QUESTIONS</small><h3>What must the learner do?</h3><p>Exam/textbook question \u2192 source identity \u2192 SL1 \u2192 SL2 proposed decisive operation and demand \u2192 independent QRT \u2192 exact question/requirement role.</p></article><article class=\"card\" style=\"min-height:unset\"><small>ROUTE B \u00b7 EXPOSITION</small><h3>What must be taught to make that possible?</h3><p>Book/syllabus/figure \u2192 exact units \u2192 candidate claims + conditions \u2192 warranted law \u2192 construction obligations \u2192 appropriate Core1A instruction.</p></article></div>\n<p>The <b>join</b> is not simply a matching keyword such as \u201cspring\u201d or \u201cenergy.\u201d It needs a reviewed connection between the exact task\u2019s decisive transformation and the specific passage, law, conditions and teaching evidence. A construction can be prepared without a reviewed QRT task, but it cannot claim to qualify that task until the join is adjudicated.</p>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Companion</a> \u00b7 <a href=\"../docs/agent-entry/04-output.md\">Output construction</a>.</p></section>\n<section class=\"chapter\" id=\"sl\"><h2>05 \u00b7 Native SL1 \u2192 optional P1 \u2192 proposed SL2</h2>\n<h3>SL1 \u2014 identity and eligibility</h3><p>SL1 records exact source, answer, paper, figure, integrity, version and practice fitness gates. It may show that two bytes or records match; that is not independent scientific truth or official authentication.</p>\n<h3>P1 \u2014 only when an actual learner\u2019s initial evidence exists</h3><p>Optional P1 can preserve the real first response before any hint/key exposure, including sequence history. If missing, label it absent/unknown. Missing P1 must not block static question analysis or create a false claim of independent mastery.</p>\n<h3>SL2 \u2014 requirement proposal, not a verdict</h3><p>SL2 describes: primary intellectual operation candidate; alternative credible operations; shortest valid route; decisive reasoning move; model validity; five intrinsic-demand factors; and actual evidence links. A long explanation, many hints or the label \u201cD3\u201d does not certify intrinsic task difficulty.</p>\n<div class=\"callout\"><strong>Deliverables:</strong> version-pinned SL1 record and checker output, optional provenance of P1, and <code>PROPOSED / UNREVIEWED</code> SL2 evidence. The independent decision remains outside SL2. No new \u201cSL3\u201d is introduced by this workflow.</div>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/02-skills.md\">SL skills</a> \u00b7 <a href=\"../docs/smart-skills-integration.md\">R2 gate mapping</a>.</p></section>\n<section class=\"chapter\" id=\"demand\"><h2>06 \u00b7 Derive demand from the exact shortest task route</h2><p>Current reviewed Physics SL2 proposals use <b>five intrinsic-demand factors</b>, each scored in the repository candidate examples on a <b>0\u20132</b> scale. The evidence, not the arithmetic alone, determines the claim. The displayed factor names below match the recorded rubric keys.</p>\n<table><thead><tr><th>Factor</th><th>What to inspect in the exact task</th><th>Check against inflation</th></tr></thead><tbody>\n<tr><td><code>concept_model_selection</code></td><td>Is a law/model obvious, chosen among rivals or requiring justification?</td><td>Do not reward a verbose explanation of a routine law.</td></tr>\n<tr><td><code>representation_translation</code></td><td>What graph, diagram, coordinate or source model must be interpreted?</td><td>Missing picture is a source defect, not intrinsic difficulty.</td></tr>\n<tr><td><code>reasoning_chain_length</code></td><td>How many necessary nonroutine transitions must a shortest valid route take?</td><td>Count decisions, not the number of written steps.</td></tr>\n<tr><td><code>algebra_computational_load</code></td><td>Actual algebra/calculation that cannot be shortened legitimately</td><td>Calculator steps and optional derivations do not manufacture D3.</td></tr>\n<tr><td><code>trap_exception_sensitivity</code></td><td>Conditions, exceptional cases and answer-selection pitfalls truly present</td><td>Unstated initial speed or ambiguous source is a HOLD, not a new trap.</td></tr>\n</tbody></table>\n<p>Do not invent D-band score thresholds here. The subject\u2019s approved rubric, exact factor evidence and independent task decision must supply any final D-band. <strong>D1/D2 common Blueprint remains <code>SPEC_PENDING</code></strong>; a reviewed D2 support question cannot be force-fitted into D3/D4 cells.</p>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/02-skills.md\">SL2 role</a> \u00b7 <a href=\"../preview/batches/b07-qrt-evidence.json\">Recorded D2 first-pass examples</a> \u00b7 <a href=\"../preview/batches/b08-source-gates.json\">Example invalid task\u2013factor correspondence</a>.</p></section>\n<section class=\"chapter\" id=\"qrt\"><h2>07 \u00b7 Independent QRT: seven operations, one exact task verdict</h2><p>The current common <em>operation vocabulary</em> is <code>RETRIEVE</code>, <code>EXPLAIN</code>, <code>APPLY</code>, <code>MODEL</code>, <code>REPRESENT</code>, <code>SYNTHESIZE</code> and <code>JUSTIFY</code>. This list is not a universal Physics-to-Chemistry transfer of scoring or examples.</p>\n<p>For each exact task, QRT must independently establish the decisive primary operation, credible alternatives, shortest valid route, five-factor demand and <strong>coverage role</strong>. The three recorded roles are <code>DIRECT_EXAM_EVIDENCE</code>, <code>PREREQUISITE_BRIDGE</code> and <code>AUTHORED_TRANSFER</code>. Only authenticated direct-exam evidence can qualify the respective direct-exam target; a bridge or authored example is a different contribution.</p>\n<h3>Source-only first-pass protocol</h3><ol><li>Authorize and scope a reviewer, exact task/version, subject rubric, figure inputs and seal destination.</li><li>Withhold prior labels, the author\u2019s worked answer, answer key and academic reconciliation until the independent pass is sealed.</li><li>Reviewer independently solves and records the decisive route, model conditions, operation, demand evidence, ambiguity and source limitations.</li><li>Seal the original first-pass report and digest; only <em>afterwards</em> compare with prior opinions and keys.</li><li>Adjudicate source role and academic admission separately; no answer exposure is retroactively \u201cblind.\u201d</li></ol>\n<div class=\"callout\">Anyone who has read this guide\u2019s named prior task outcomes is author-exposed. They should not claim to perform a blind independent first pass on those same tasks. Give a new reviewer the <a href=\"../docs/agent-entry/07-independent-review.md\">source-only reviewer entry</a>, not this guide or the cumulative reader.</div>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/07-independent-review.md\">Independent reviewer protocol</a> \u00b7 <a href=\"../docs/smart-skills-integration.md\">QRT responsibility and roles</a>.</p></section>\n<section class=\"chapter\" id=\"thought-protocol\"><h2>08 \u00b7 Transparent protocol for the difficult decisions</h2><p>Instead of a hidden internal thought trace, retain a <strong>reviewable evidence-and-decision record</strong>: observations \u2192 candidate interpretations \u2192 disconfirming checks \u2192 authority boundary \u2192 output state. The questions below can guide an author or reviewer without treating either party\u2019s first guess as a verdict.</p>\n<table><thead><tr><th>Decision point</th><th>Questions to document</th><th>Fail-closed outcome</th></tr></thead><tbody>\n<tr><td>Identity</td><td>Is this the same task/version? Are figure, source and key independently matched?</td><td>Missing \u2192 HOLD; contradiction \u2192 FAIL</td></tr>\n<tr><td>Model</td><td>Which body/system, frame, forces, contacts and initial state are necessary? Can a different valid model change the result?</td><td>Ambiguous conditions \u2192 HOLD and escalate</td></tr>\n<tr><td>Shortest route</td><td>Can a simpler valid route solve it? What is the decisive transformation? What tempting longer route is optional?</td><td>Unscored/author proposal until independent review</td></tr>\n<tr><td>Operation</td><td>Which of the seven labels is primary? Which credible rival did the shortest route eliminate?</td><td>Conflicting proposals \u2192 no QRT cell</td></tr>\n<tr><td>Demand</td><td>Does every factor explanation correspond to this exact task, not another problem\u2019s physics?</td><td>Irrelevant factor evidence \u2192 FAIL</td></tr>\n<tr><td>Source role</td><td>Original authenticated exam, textbook prerequisite or authored transfer? Does the target require direct exam evidence?</td><td>Wrong role \u2192 no target coverage</td></tr>\n<tr><td>Construction</td><td>Did the lesson teach the exact direction and conditions needed for future fresh reasoning?</td><td>String/ID match alone \u2192 HOLD</td></tr>\n<tr><td>Release</td><td>Are rights, independent receipts, runtime and Owner authority truly present?</td><td>Missing approvals \u2192 HOLD regardless of green CI</td></tr>\n</tbody></table><p>Record <code>PASS</code> only for checks actually executed and within scope, <code>HOLD</code> for missing trusted evidence and <code>FAIL</code> for demonstrably contradictory evidence. Do not \u201caverage away\u201d a failed source or authority gate because other stages pass.</p>\n<p class=\"source\">Basis: <a href=\"../AGENTS.md\">Repository fail-closed rules</a> \u00b7 <a href=\"../docs/agent-entry/05-qa-publication.md\">QA ownership</a> \u00b7 <a href=\"../preview/batches/b09-corrective-evidence.json\">Unscored M69 corrective candidate</a>.</p></section>\n<section class=\"chapter\" id=\"blueprint\"><h2>09 \u00b7 Resolve the subject Blueprint and topic adapter</h2><p>Formula for a candidate Physics teaching tile: <strong>reviewed operation and demand cell + selected WPE adapter + qualified subject warrant</strong>. For an independently adjudicated <code>APPLY / D3</code>, the present <em>draft</em> Physics matrix suggests cell <code>D3.3</code>. This is a structural illustration, not a review outcome or an approved build.</p>\n<ul><li>Current <a href=\"../templates/physics-blueprint/physics-blueprint.D3-D4.json\">Physics Blueprint v0.2.0</a> has 14 D3/D4 cells, status <code>DRAFT_OWNER_REVIEW</code>.</li><li>The WPE topic-adapter candidates have unequal byte versions and no single Owner-approved selection. Same version string does <b>not</b> imply same content.</li><li>The adapter must bind law, model conditions, context, pitfalls, representations, attempts and checks to the selected cell. If a common Blueprint capability is missing, issue a <strong>Blueprint gap note</strong>; do not silently rewrite the common matrix.</li><li>For Mathematics/Chemistry, select their own approved subject rules and warrants before classification. Physics/WEP v1 topic schema cannot be universalized by renaming an ID.</li><li>Any D2 task requires the as-yet-unqualified D1/D2 treatment: <code>SPEC_PENDING</code>.</li></ul>\n<div class=\"callout\"><strong>Minimum bound record:</strong> exact task ID + independently reviewed QRT decision + subject Blueprint/version/hash + topic adapter/version/hash + qualified law/conditions + cell-to-witness map. If a binding is unavailable, the academic result stays HOLD.</div>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/03-blueprint-adapters.md\">Subject/adapter governance</a> \u00b7 <a href=\"../templates/physics-blueprint/physics-blueprint.D3-D4.json\">Draft Physics matrix</a> \u00b7 <a href=\"../docs/product-scope.md\">Three-subject boundaries</a>.</p></section>\n<section class=\"chapter\" id=\"warrants\"><h2>10 \u00b7 Source passage \u2192 conditional warrant \u2192 teaching obligation</h2><p>An explanation is insufficient if it hides the conditions under which the law is valid. Build a claim ledger with <b>exact source passage, proposed meaning, assumptions, exceptions, subject expert status</b> and the direction required by the assessed task.</p>\n<table><thead><tr><th>What the binder needs</th><th>Ask</th></tr></thead><tbody><tr><td>Physical or disciplinary law</td><td>What is the precise relation, units, model and frame? Has the appropriate expert independently checked it?</td></tr><tr><td>Conditions</td><td>Where does the law apply? Initial speed, friction, conservative field, contact and boundary conditions explicit?</td></tr><tr><td>Representation</td><td>Does the diagram faithfully express the exact needed physical relation, not substitute for an absent exam image?</td></tr><tr><td>Direction</td><td>Does taught <code>U(x) \u2192 F(x)</code> actually support tested <code>F(x) \u2192 U(x)</code>, or is that a distinct construction?</td></tr><tr><td>Question join</td><td>Can the reviewer point to the exact step that links a law in this passage to the task\u2019s decisive move?</td></tr></tbody></table>\n<p>Source preparation may reveal missing canonical relations and figures; record those as unresolved warrants, not invented \u201cfacts from the book.\u201d A strong software diagram is not independent scientific qualification.</p>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Current source-to-Core1A companion</a> \u00b7 <a href=\"../docs/agent-entry/04-output.md\">Native output obligations</a>.</p></section>\n<section class=\"chapter\" id=\"core2\"><h2>11 \u00b7 Core2 \u2014 exact question construction</h2><p>Core2\u2019s question route consumes authorized exact source task records with distinct paper/key/figure custody. It must preserve answer type (including multiple-correct), source identity, the correct scientific model, learner attempt and staged hints without leaking the answer through accessibility text, thumbnails or keyboard state.</p>\n<ol><li>Check that source, key and figure bytes have the required provenance and rights.</li><li>Bind actual question IDs and source roles to native bank/manifest/template; do not copy a public synthetic exercise and relabel it as an exam original.</li><li>Represent conditions that are actually in the task; omitted initial data is not silently repaired by changing the source.</li><li>Render native output and audit keyboard, state restoration, reveal order, duplicate identifiers, answer semantics and every displayed figure.</li><li>Retain independently reviewed scientific/academic and Owner gates. A successful render is a technical receipt only.</li></ol>\n<p>For this Owner-scoped WPE route, completed and accepted Core2 scope precedes new native Core1A authoring; preparation dossiers can exist in parallel. No step of this guide grants admission to the draft reader.</p>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/04-output.md\">Output agent entry</a> \u00b7 <a href=\"../docs/agent-entry/CURRENT_WORKFLOW.json\">Owner-specific dependencies</a> \u00b7 <a href=\"../preview/batches/reader.html\">Synthetic technical reader (not native)</a>.</p></section>\n<section class=\"chapter\" id=\"binder\"><h2>12 \u00b7 Core1A teaching and Core1B fresh reconstruction: B1\u2013B7</h2><p><strong>Core1A</strong> must actually teach the target reasoning; <strong>Core1B</strong> must elicit a genuinely fresh, protected reconstruction rather than the same worked example copied back. The construction binder needs evidence of every obligation below, independent of whether a page looks complete.</p>\n<table><thead><tr><th>Obligation</th><th>Evidence question</th></tr></thead><tbody>\n<tr><td><strong>B1 \u2014 Target</strong></td><td>What precise task-level cognitive requirement and direction will be taught?</td></tr>\n<tr><td><strong>B2 \u2014 Construction signature</strong></td><td>What distinctive reasoning move, prerequisites and model selection define it?</td></tr>\n<tr><td><strong>B3 \u2014 Teaching sufficiency</strong></td><td>Do worked and guided steps actually establish the decisive move and its validity conditions?</td></tr>\n<tr><td><strong>B4 \u2014 Fresh reconstruction</strong></td><td>Can a learner perform an unseen but appropriately matched task without copying the demonstrated route?</td></tr>\n<tr><td><strong>B5 \u2014 Attempt protection</strong></td><td>Is a real attempt secured before hints/key exposure, including saved-state, alt text and keyboard behavior?</td></tr>\n<tr><td><strong>B6 \u2014 Diagnosis & changed-condition transfer</strong></td><td>Can the lesson diagnose a specific wrong model and teach a boundary/changed-case transfer?</td></tr>\n<tr><td><strong>B7 \u2014 Physics/provenance</strong></td><td>Are scientific laws, exact sources, adapter pins and independent subject checks qualified?</td></tr>\n</tbody></table>\n<p><strong>Noncompensatory rule:</strong> If B3 or B4 is not evidenced, a correct label and valid HTML cannot fill the gap. Correctness and cognitive qualification must be checked separately. A source dossier is preparation, not an accepted Core1A lesson.</p>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">B1\u2013B7 requirements</a> \u00b7 <a href=\"../docs/agent-entry/04-output.md\">Native Core output</a> \u00b7 <a href=\"../docs/implementation-status.md\">Current B1\u2013B7 engine status</a>.</p></section>\n<section class=\"chapter\" id=\"checks\"><h2>13 \u00b7 Checks and balances: what each role can honestly report</h2><table><thead><tr><th>Check</th><th>Valid PASS scope</th><th>Not proven</th></tr></thead><tbody>\n<tr><td>Schema/checksum</td><td>Bytes and declared structure match a specified input</td><td>Scientific correctness, official paper or independent reviewer</td></tr>\n<tr><td>Source integrity + key</td><td>Exact bound source/answer matches the checked record</td><td>Official provenance without independent paper/key authority</td></tr>\n<tr><td>SL2 rubric completeness</td><td>All proposed factors and reason fields exist and are task-relevant</td><td>Independent cognitive operation/demand</td></tr>\n<tr><td>QRT independent review</td><td>Signed, scoped and appropriately sealed task decision</td><td>Owner release, copyright or native runtime safety</td></tr>\n<tr><td>B1\u2013B7 mechanical engine</td><td>Witness structure and dependencies are present and consistent</td><td>Actual teaching/reconstruction sufficiency without expert assessment</td></tr>\n<tr><td>Browser QA</td><td>Specified viewport, input order, reveal, keyboard and accessibility paths tested</td><td>Academic admission or all devices and failure states</td></tr>\n<tr><td>Owner/Shared release</td><td>Authorized separate decision for that version, content and destination</td><td>Permanent validity after source or build changes</td></tr>\n</tbody></table>\n<div class=\"callout\"><strong>One gate fails, no silent promotion.</strong> Missing or stale authority \u2192 HOLD; demonstrable contradiction \u2192 FAIL. Do not auto-generate reviewer receipts, backfill tests that were not run, or describe a CI green check as student release. Record which checks are NOT_RUN.</div>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/05-qa-publication.md\">QA and publication</a> \u00b7 <a href=\"../docs/smart-skills-integration.md\">Gate semantics</a> \u00b7 <a href=\"../AGENTS.md\">Repository operating rules</a>.</p></section>\n<section class=\"chapter\" id=\"example\"><h2>14 \u00b7 Worked method illustration: Physics \u2192 WPE \u2192 signed work</h2><p>This is a newly authored example of <em>how to plan and document</em> a construction. It is not an authenticated examination question, approved Blueprint placement or QRT score.</p>\n<ol><li><strong>Subtopic and direction.</strong> Signed work for a constant force over a specified displacement; future learner must evaluate the dot product and interpret the sign.</li><li><strong>Fresh synthetic check.</strong> A particle moves by <code>\u0394r=(3, \u22122) m</code> under constant <code>F=(4, \u22121) N</code>. The intended check is <code>W=4\u00b73+(\u22121)(\u22122)=14 J</code>. State inertial frame, force constant over the displacement and one particle.</li><li><strong>SL1/source role.</strong> <code>AUTHORED_TRANSFER</code>; original exam-paper custody and official key are not claimed. Record the origin and version of this newly written task.</li><li><strong>SL2 proposal.</strong> Describe the decisive move (final-minus-initial displacement, componentwise signed projection) and plausible misconception (multiply magnitudes; lose the negative sign). Score no D-band unless an independently reviewed task/rubric actually supports it.</li><li><strong>QRT HOLD.</strong> No examiner has independently adjudicated this authored task; it cannot be counted toward the 21 original D3/D4 exam targets.</li><li><strong>Blueprint/adapter HOLD.</strong> No approved WPE adapter selected; the draft D3/D4 Physics matrix is not a qualification. A lesson designer may use it only as <em>candidate</em> design guidance.</li><li><strong>Source/warrant.</strong> Bind the constant-force dot-product law with its conditions and exact teaching direction; request independent Physics verification for academic use.</li><li><strong>Core1A candidate.</strong> Teach projection, two contrasting signs, why perpendicular force gives zero work and an actual incorrect-route diagnosis.</li><li><strong>Core1B fresh candidate.</strong> Use different force/displacement vectors and change one sign; protect the first attempt before hints; verify transfer without copying the example.</li><li><strong>Disposition.</strong> Technical illustration may render publicly as synthetic; academic and native authoring status stays <code>HOLD</code>.</li></ol>\n<p>The example deliberately separates a mathematically correct result from the nontrivial evidence needed to say the lesson is <em>qualified</em>.</p>\n<p class=\"source\">Structural basis: <a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Construction-to-task distinctions</a> \u00b7 <a href=\"../docs/agent-entry/02-skills.md\">SL1/SL2 candidate roles</a>. Numerical example above is <strong>new explanatory material</strong>, not sourced from the repository.</p></section>\n<section class=\"chapter\" id=\"handoff\"><h2>15 \u00b7 Five-part evidence handoff template</h2><p>Each future chapter/subtopic construction should produce a small, legible, decision-ready report. Below is a <em>recommended report structure</em>, not an official native schema:</p>\n<table><thead><tr><th>Part</th><th>Required content and recipient</th></tr></thead><tbody>\n<tr><td>1 \u00b7 Identity and source</td><td>Subject, chapter, subtopic, exact task IDs, source paths/digests, paper/key/figure/rights status \u2192 Source/SL1 reviewer</td></tr>\n<tr><td>2 \u00b7 Demand and QRT</td><td>Shortest route, competing operations, factor evidence, reviewed decision, source role, exposure/seal status \u2192 Independent QRT reviewer</td></tr>\n<tr><td>3 \u00b7 Binding and warrants</td><td>Subject Blueprint version/hash, selected adapter/library pins, physical conditions and task-direction join \u2192 Subject expert / Owner</td></tr>\n<tr><td>4 \u00b7 Construction witnesses</td><td>Core2 source render, Core1A B1\u2013B7 teaching evidence, Core1B fresh attempt and diagnosis \u2192 Independent content and runtime reviewers</td></tr>\n<tr><td>5 \u00b7 Disposition and next consumer</td><td>PASS/HOLD/FAIL/NOT_RUN per gate; exact build/tests; unresolved questions; explicit Owner release status \u2192 Governance/QA</td></tr>\n</tbody></table><div class=\"callout good\">A valid next deliverable is sometimes a single well-evidenced <strong>HOLD</strong>. Discovering a wrong SL2 factor, missing original figure or unselected adapter is progress toward correctness without inventing an academic admission.</div>\n<p class=\"source\">Basis: <a href=\"../docs/agent-entry/00-required-reading.md\">Onboarding handoff check</a> \u00b7 <a href=\"../docs/agent-entry/05-qa-publication.md\">QA report requirements</a> \u00b7 <a href=\"../docs/agent-entry/CURRENT_WORKFLOW.json\">Current dependencies</a>.</p></section>\n<section class=\"chapter\" id=\"sources\"><h2>16 \u00b7 Primary repository documents and reading discipline</h2><p>Read the actual pinned source, not only this derived guide. These documents are not all equally current: historical concept reports, legacy migration notes and local checkpoint details retain their original scope. The current companion and active workflow clarify what has subsequently changed; they do not themselves create approval.</p>\n<ol><li><a href=\"../docs/product-scope.md\">Product scope \u2014 the three-subject rule and candidate v2 migration</a>.</li><li><a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Current concept companion \u2014 two routes, B1\u2013B7 and academic boundaries</a>.</li><li><a href=\"../docs/agent-entry/concept-report-v4.html#current-workflow-2026-11-02\">Concept report and dated current workflow addendum</a>.</li><li><a href=\"../docs/agent-entry/01-source-intake.md\">Source intake \u2014 custody, rights and exact identities</a>.</li><li><a href=\"../docs/smart-skills-integration.md\">Smart Skills R2 candidate mapping \u2014 SL1/P1/SL2/QRT</a>.</li><li><a href=\"../docs/agent-entry/03-blueprint-adapters.md\">QRT, Physics Blueprint and WPE adapter status</a>.</li><li><a href=\"../templates/physics-blueprint/physics-blueprint.D3-D4.json\">Physics D3/D4 Blueprint draft v0.2.0</a>.</li><li><a href=\"../docs/agent-entry/07-independent-review.md\">Fresh source-only independent reviewer instruction</a>.</li><li><a href=\"../docs/agent-entry/04-output.md\">Output/Core1A/B/2 agent instructions</a>.</li><li><a href=\"../docs/agent-entry/05-qa-publication.md\">Technical/academic QA and publication separation</a>.</li><li><a href=\"../docs/implementation-status.md\">Engineering status: candidate versus qualified P0/P1/P2/P3 stages</a>.</li><li><a href=\"guidebook-sources.json\">Machine-readable source register with the read Git blob identities</a>.</li></ol>\n<p><strong>Current dated review baseline:</strong> 0 academic admissions; four independently assessed APPLY/D2 supports; ten unreviewed nominations; seven original vacancies; eleven unsupported D3/D4 target slots; ten source-preparation dossiers not independently accepted as teaching. The latest public WPE preview has eight batches and 40 technical review entries, which are separate from academic coverage.</p>\n<p class=\"source\">Read-first exception: <a href=\"../docs/agent-entry/07-independent-review.md\">blind reviewers must get only a sealed source-only packet</a> until their first pass is complete. This book is not that packet.</p></section>\n</div></div><section class=\"panel\"><h2>Production handoff \u00b7 12.7-inch tablet Core2</h2><p>The next Core2 technical review must use a first-class full page, not an embedded reader. The <a href=\"production-checklist.html#tablet-core2\">Production Checklist</a> defines tablet portrait/landscape, input, reveal, navigation, evidence and deploy checks. It is a release test obligation, not a QRT or academic admission.</p></section>",
  "pipeline-benchmarks": "<div class=\"status\">\n      <strong>Universal Governance Invariant (Rule 13 \u00b7 AGENTS.md)</strong>\n      <p>This page is the <strong>Core2-led source-question production route</strong>, not a universal textbook sequence. For independent curriculum-first Core1A/B use the <a href=\"core1ab-agent-guide.html\">Agent Field Guide</a>; for actual auditing use the <a href=\"review-guide.html\">Independent Audit Field Guide</a>. Green CI checks software, not scientific or educational truth. R2 is currently <code>PILOT_AWAITING_OWNER_GOLDEN</code>; Owner approves the first Golden exemplar only, then delegates routine batch reviews.</p>\n    </div>\n\n    <section class=\"panel\">\n      <h2>High-Level Authoring Pipeline</h2>\n      <p>When production starts from a genuine examination question, follow these eight source-to-learning stages. Curriculum-first Core1A teaching can proceed independently; it joins this route through exact question-to-lesson-to-transfer identities.</p>\n      <div class=\"flowchart\">\n        <pre>\n[ AUTHENTIC SOURCE QUESTION(S) ] \u2500\u2500\u2500 (Stems, Figures, Keys)\n       \u2502\n       \u25bc\n[ STAGE 1: Source Custody & Intake ] \u2500\u2500\u2500 Skills: smart-labelling-1 | Template: TEMPLATE-intake.json\n       \u2502  Benchmark: Bit-for-bit SHA-256 byte parity, unswapped assets, zero duplicate IDs across subjects\n       \u25bc\n[ STAGE 2: Cognitive Demand Profiling ] \u2500\u2500\u2500 Skills: smart-labelling-2 | Engine: grade9qa/demand.py\n       \u2502  Benchmark: 5 factors in [0..2], sum = score (0..10), exact D-band monotonicity\n       \u25bc\n[ STAGE 3: Independent Blind QRT Adjudication ] \u2500\u2500\u2500 Binding: grade9qa qrt-bind | Entry: 07-independent-review.md\n       \u2502  Benchmark: Sealed first-pass SHA-256, strictly 1 of 7 Canonical Verbs (RETRIEVE..JUSTIFY)\n       \u25bc\n[ STAGE 4: Disciplinary Warrants & Topic Adapter ] \u2500\u2500\u2500 Schema: warrant.schema.json | Blueprint: physics-blueprint\n       \u2502  Benchmark: Explicit assumptions/domain/sign, directional parity (A\u2794B \u2260 B\u2794A)\n       \u25bc\n[ STAGE 5: Native Core2 Interactive Tablet Module ] \u2500\u2500\u2500 Skill: ag-core2 | Template: TEMPLATE-bank.json\n       \u2502  Benchmark: 12.7\" Tablet 0px overflow, commitment-first derivations, evaluation banners, reset control\n       \u25bc\n[ STAGE 6: Core1A Master Lesson & Core1B Fresh Transfer ] \u2500\u2500\u2500 Skill: source-to-core1a-r2 | Companion: CURRENT_CONCEPT_COMPANION\n       \u2502  Benchmark: B1\u2013B7 Non-Compensatory Rubric (B4 fresh unseen twin, B5 attempt protection)\n       \u25bc\n[ STAGE 7: Dual-Engine Engineering Verification (Academic HOLD) ] \u2500\u2500\u2500 CLI: pytest -q | Harness: preview_ui_regression.py\n       \u2502  Benchmark: 100% pytest pass, 100% tablet Playwright pass, Fail-Closed HOLD status preserved\n       \u25bc\n[ STAGE 8: Independent Review & Delegated Batch Admission ] \u2500\u2500\u2500 Receipts: B1\u2013B7 signed JSON | Scoped Sign-off\n       \u2502  Benchmark: External human faculty sign-off, cryptographic receipt, {Unvalidated} \u2794 {Admitted}\n       \u25bc\n[ SOURCE-QUALIFIED LEARNING ROUTE / DELEGATED BATCH STATUS ]\n        </pre>\n      </div>\n      <div class=\"linklist\">\n        <a href=\"guidebook.html\">Read full Architecture Guidebook</a>\n        <a href=\"review-guide.html\">Open Independent Audit Field Guide</a>\n        <a href=\"production-checklist.html\">Open 12.7\" Tablet Production Checklist</a>\n      </div>\n    </section>\n\n\n    <section class=\"panel\" id=\"route-boundary\">\n      <h2>When to use this reference</h2>\n      <p><strong>Use this eight-stage pipeline</strong> when starting from an identified examination question to produce a faithful Core2 reader and traceable learning routes. For a syllabus-driven chapter without an authenticated source question, use the curriculum-first <a href=\"core1ab-agent-guide.html\">Core1A/Core1B Field Guide</a> without fabricating Core2 source admission.</p>\n      <p><strong>Auditing is separate:</strong> the <a href=\"review-guide.html\">Independent Audit Field Guide</a> defines R00/R01 evidence review, science falsification, first-attempt integrity, quality decisions and one-time Golden Sample governance. This process map cannot independently award academic approval. Redistribution-rights questions are outside this educational quality protocol.</p>\n    </section>\n\n    <h2 class=\"section-title\">Stage-by-Stage Reference, Templates &amp; Benchmarks</h2>\n\n    <!-- STAGE 1 -->\n    <article class=\"flow-card\" id=\"stage-1\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 1 \u00b7 Question Intake, Source Custody &amp; Fingerprinting</h3>\n        <span class=\"stage-badge\">Stage 01</span>\n      </div>\n      <p>Segregate question items into Git-excluded custody (<code>workspace/sources/&lt;topic&gt;/</code>). Decompose each item into 3 independent files: stem text, diagram/raster, and official answer key. Calculate SHA-256 byte hashes and mint unique stable IDs.</p>\n      <p><b>Tools &amp; Templates Used:</b> <span class=\"tool-badge\">templates/skills/smart-labelling-1/scripts/check_sl1.py</span> <span class=\"tool-badge\">templates/core2-exam-card/TEMPLATE-intake.json</span> <span class=\"tool-badge\">schemas/v1/source.schema.json</span></p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable Pass Benchmark</span>\n        Exact 64-character SHA-256 cryptographic match between file bytes and metadata record (`declared_matches_observed: true` across 100% of candidate items). Zero duplicate IDs across the entire repository (cross-topic and cross-year disambiguation, e.g. <code>NSEJS-2019-P-OPT-Q01/Q02</code> vs <code>NSEJS-2019-P-ELEC-Q01/Q14</code>). Clear separation between <code>EXAM_PAPER</code> vs <code>TEXTBOOK</code> vs <code>AUTHORED_TRANSFER</code>.\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict Falsifier / Failure Trigger</span>\n        Modifying a single character in the question stem, swapping an image locator, substituting a redrawn diagram without flagging as <code>DERIVED_FIGURE</code>, or collision between historical IDs immediately trips <code>HASH_MISMATCH / INTEGRITY_FAIL</code>.\n      </div>\n    </article>\n\n    <!-- STAGE 2 -->\n    <article class=\"flow-card\" id=\"stage-2\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 2 \u00b7 Cognitive Demand Profiling (SL1 \u2794 Optional P1 \u2794 SL2)</h3>\n        <span class=\"stage-badge\">Stage 02</span>\n      </div>\n      <p>Trace the shortest valid solution route. Identify the decisive mental move. Score the 5 intrinsic complexity dimensions on a 0\u20132 scale. If real unassisted student attempt data exists, record P1; otherwise, explicitly set P1 to <code>NOT_APPLICABLE</code> (never fake student attempt history).</p>\n      <p><b>Tools &amp; Templates Used:</b> <span class=\"tool-badge\">templates/skills/smart-labelling-2/scripts/check_sl2.py</span> <span class=\"tool-badge\">src/grade9qa/demand.py</span> <span class=\"tool-badge\">schemas/v1/assessment.schema.json</span></p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable Pass Benchmark</span>\n        Every factor $c_i \\in \\{0, 1, 2\\}$, total score $\\sum c_i = \\text{difficulty.score} \\in [0, 10]$. Strict D-Band alignment: D1 (0\u20132), D2 (3\u20135), D3 (6\u20137), D4 (8\u201310). Zero empty factor evidence fields. Proposed status strictly marked <code>PROPOSED / UNREVIEWED</code>.\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict Falsifier / Failure Trigger</span>\n        $\\sum c_i \\neq \\text{score}$ or score outside declared D-band trips <code>BAND_MISMATCH</code> in <code>demand.py</code>. Generic justification text trips <code>MISSING_DEMAND_EVIDENCE</code>.\n      </div>\n    </article>\n\n    <!-- STAGE 3 -->\n    <article class=\"flow-card\" id=\"stage-3\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 3 \u00b7 Independent Blind QRT Adjudication</h3>\n        <span class=\"stage-badge\">Stage 03</span>\n      </div>\n      <p>Assemble a sanitized, source-only packet (stripping author solutions, hints, and keys). An authorized independent expert solves the question blind, selects the primary cognitive operation, and assigns the coverage role.</p>\n      <p><b>Tools &amp; Templates Used:</b> <span class=\"tool-badge\">grade9qa qrt-bind</span> <span class=\"tool-badge\">src/grade9qa/qrt_binding.py</span> <span class=\"tool-badge\">docs/agent-entry/07-independent-review.md</span></p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable Pass Benchmark</span>\n        Primary operation must belong strictly to the 7 canonical verbs: <code>RETRIEVE</code>, <code>EXPLAIN</code>, <code>APPLY</code>, <code>MODEL</code>, <code>REPRESENT</code>, <code>SYNTHESIZE</code>, <code>JUSTIFY</code>. The first-pass review must be sealed with a SHA-256 digest <i>before</i> answer key exposure. Verified against <code>versioned independent reviewer receipt and eligibility registry (see R2 audit templates)</code>.\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict Falsifier / Failure Trigger</span>\n        Use of non-canonical verbs (e.g., <code>CALCULATE</code>, <code>SOLVE</code>), self-review by the author, or unsealed evaluations immediately fails QRT admission.\n      </div>\n    </article>\n\n    <!-- STAGE 4 -->\n    <article class=\"flow-card\" id=\"stage-4\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 4 \u00b7 Disciplinary Warrants &amp; Topic Adapter</h3>\n        <span class=\"stage-badge\">Stage 04</span>\n      </div>\n      <p>Explicitly bound every formula and physical law. Document the exact physical claim, validity domain, assumptions, exceptions, and coordinate/sign conventions. Ensure directional consistency.</p>\n      <p><b>Tools &amp; Templates Used:</b> <span class=\"tool-badge\">schemas/v1/warrant.schema.json</span> <span class=\"tool-badge\">templates/physics-blueprint/physics-blueprint.D3-D4.json</span> <span class=\"tool-badge\">grade9qa subjects-audit</span></p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable Pass Benchmark</span>\n        Every warrant must contain non-empty arrays for <code>assumptions</code>, <code>validity_domain</code>, and <code>exceptions</code>. Taught reasoning direction must strictly match tested task direction ($A \\to B \\neq B \\to A$).\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict Falsifier / Failure Trigger</span>\n        Reversing directional claims or omitting boundary assumptions (e.g., assuming $F = -GMm/r^2$ inside a hollow planet) trips <code>WARRANT_DIRECTION_MISMATCH</code>.\n      </div>\n    </article>\n\n    <!-- STAGE 5 -->\n    <article class=\"flow-card\" id=\"stage-5\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 5 \u00b7 Native Core2 Interactive Tablet Module &amp; Learning Bridge</h3>\n        <span class=\"stage-badge\">Stage 05</span>\n      </div>\n      <p>Construct the interactive, full-page student question card for 12.7-inch tablets. Structure explanations into 4 cognitive slots ($X$ Setup, $Y$ Law, $Z$ Formulation, $W$ Crux). Implement 3-tier progressive hints ($H_1, H_2, H_3$), commitment-first event handlers, interactive attempt evaluation banners, misconception retry controls, and direct learning bridge routes into Stage 6 master lessons.</p>\n      <p><b>Tools &amp; Templates Used:</b> <span class=\"tool-badge\">ag-core2 skill (v4.1)</span> <span class=\"tool-badge\">per-topic HTTP Playwright QA (confirm actual path)</span> <span class=\"tool-badge\">templates/core2-exam-card/TEMPLATE-bank.json</span> <span class=\"tool-badge\">nsejs/js/core2-learning-route.js</span> <span class=\"tool-badge\">architecture/production-checklist.html</span></p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable Pass Benchmark (Four Core2 pillars plus tablet ergonomics)</span>\n        <ul style=\"margin:6px 0 6px 18px;padding:0;line-height:1.6;\">\n          <li><b>1. Procedure:</b> Full 3-state evaluation lifecycle: <code>Uncommitted</code> \u2794 <code>Committed (Feedback Banner + Badges)</code> \u21cc <code>[\ud83d\udd04 Reset &amp; Try Again]</code> that creates a linked revision and never deletes the first persisted attempt. Single Master Topic Navigation bar positioned directly above in-place <code>#topicWorkspace</code> (zero scroll-hunting; zero duplicate bars). Client-side cache busting via <code>?v=4.1.x</code> on script tags and <code>{ cache: \"no-store\" }</code> on dynamic JSON fetches.</li>\n          <li><b>2. Workflow:</b> Adversarial Jargon Filter strictly enforced: zero developer mock strings (<code>producer proposal</code>, <code>differs from producer</code>, <code>asserted stem digest agrees with display</code>) on student surfaces. Technical hashes and QRT formulas strictly encapsulated in a collapsed <code>&lt;details class=\"q-source-custody-drawer\"&gt;</code>.</li>\n          <li><b>3. Self-Check:</b> Automated Playwright assertion banning forbidden strings (regex match on <code>/producer/i</code>), W3C SVG XML strictness audit (zero HTML named entities like <code>&amp;middot;</code>), and global repository-wide ID uniqueness check.</li>\n          <li><b>4. Evidences:</b> Mandatory post-commitment visual screenshot proof (<code>playwright_evidence_qXX_[width].png</code>) verifying banners and option badges before release, plus HTTP 200 cache-bypass network verification.</li>\n          <li><b>5. Layout &amp; Ergonomics:</b> 0px horizontal scroll overflow at 1000\u00d71600 portrait and 1600\u00d71000 landscape, plus appropriate responsive viewports. Touch targets $\\ge 48\\text{px}$ (WCAG AAA). Derivations strictly inert (<span class=\"code\">display: none</span>) until commit. W3C SVG font size $\\ge 14\\text{px}$.</li>\n        </ul>\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict Falsifier / Failure Trigger</span>\n        Horizontal scrollbar on any viewport, hint leaking Slot $W$, solution visible in DOM/alt text prior to commit, developer mock strings (`differs from producer proposal`, `asserted stem digest agrees with display`) visible in student UI, HTML named entities in SVGs crashing the XML parser, missing reset/retry control, or missing visual screenshot proof immediately fails Stage 5 audit.\n      </div>\n    </article>\n\n    <!-- STAGE 6 -->\n    <article class=\"flow-card\" id=\"stage-6\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 6 \u00b7 Core1A Master Lesson &amp; Core1B Fresh Transfer</h3>\n        <span class=\"stage-badge\">Stage 06</span>\n      </div>\n      <p>Author Core1A to sufficiently teach the decisive mental pivot. Author Core1B as an unseen twin problem testing the exact same reasoning signature under altered physical conditions. Tab 1 must render the complete Core 2 Reference Item with vector diagram and commitment box; never an empty disclaimer. Compile the B1\u2013B7 witness ledger.</p>\n      <p><b>Tools &amp; Templates Used:</b> <span class=\"tool-badge\">templates/skills/source-to-core1a-r2</span> <span class=\"tool-badge\">templates/skills/source-to-core1a-r2/references/benchmarks.md</span> <span class=\"tool-badge\">docs/agent-entry/CURRENT_CONCEPT_COMPANION.md</span></p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable Pass Benchmark (Non-Compensatory B1\u2013B7 Rubric)</span>\n        All 7 witnesses satisfied: <b>B1 Target</b> (explicit demand &amp; full Tab 1 question rendering), <b>B2 Signature</b> (distinctive pivot), <b>B3 Sufficiency</b> (Core1A teaches the crux), <b>B4 Reconstruction</b> (Core1B is fresh &amp; unseen), <b>B5 Protection</b> (attempt secured before hints), <b>B6 Diagnosis</b> (diagnoses wrong models), <b>B7 Provenance</b> (expert physics sign-off). Tab 1 must display the complete target stem, vector SVG, and interactive options.\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict Falsifier / Failure Trigger</span>\n        If Core1B only alters numbers without testing altered physical boundaries, B4 fails. Missing first-attempt enforcement fails B5. Placeholder disclaimers in Tab 1 (\"source authority note\") without problem statement fails B1 Target. Non-compensatory rule: failing one witness holds the entire lesson.\n      </div>\n    </article>\n\n    <!-- STAGE 7 -->\n    <article class=\"flow-card\" id=\"stage-7\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 7 \u00b7 Dual-Engine Verification &amp; Technical Preview Gate</h3>\n        <span class=\"stage-badge\">Stage 07</span>\n      </div>\n      <p>Execute automated unit test suites, headless Chromium viewport regression audits, and build pipelines. Report mechanical compliance while strictly holding academic release.</p>\n      <p><b>Tools &amp; Templates Used:</b> <span class=\"tool-badge\">pytest -q</span> <span class=\"tool-badge\">tools/preview_ui_regression.py</span> <span class=\"tool-badge\">per-topic HTTP Playwright QA (confirm actual path)</span> <span class=\"tool-badge\">.github/workflows/deploy.yaml</span></p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable Pass Benchmark</span>\n        100% pass on pytest (schemas, DAG reference cycles, SHA hashes, global ID uniqueness, attempt evaluation suites). 100% pass on Playwright tablet regression suite (0 console errors, 0px overflow, zero XML entity errors in SVGs, 0 matches for <code>/producer/i</code>, verified attempt commitment &amp; <code>[\ud83d\udd04 Reset &amp; Try Again]</code> controls). Mandatory generation of post-commitment visual screenshots (<code>playwright_evidence_*.png</code>) as tangible proof of UI compliance. Status explicitly output as <code>MECHANICAL_PASS / HOLD: ACADEMIC_ADMISSION</code>. All question badges are derived from actual source and academic status; <code>{Reviewed}</code> or peer-audited wording cannot coexist with unresolved admission HOLD.\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict Falsifier / Failure Trigger</span>\n        Any automated test failure, broken link, SVG XML parsing crash, forbidden developer mock string leak, missing reset control, missing visual proof screenshot, or auto-generated human approval receipt aborts publication immediately. Software passing tests must never remove Rule 13 HOLD or claim academic authority.\n      </div>\n    </article>\n\n    <!-- STAGE 8: independent review and delegated release -->\n    <article class=\"flow-card\" id=\"stage-8\">\n      <div class=\"flow-stage-header\">\n        <h3>Stage 8 \u00b7 Independent Academic Review &amp; Delegated Batch Admission</h3>\n        <span class=\"stage-badge\" style=\"background:#fef3c7;color:#92400e;\">Academic gate</span>\n      </div>\n      <p>Source-authenticated Core2 status, scientific accuracy, actual QRT demand and B1\u2013B7 learning quality require independent evidence. R00 checks exact-head technical proof; a genuinely unexposed R01 independently solves and evaluates the scientific teaching and fresh transfer. The Owner approves <strong>one representative Golden exemplar and standard</strong>, not individual routine questions. Subsequent batches follow delegated, risk-based review when the policy is activated.</p>\n      <p><b>References:</b> <a href=\"../docs/agent-entry/quality-gate-r2/AUTHORING_QUALITY_CONTRACT_R2.md\">R2 Quality Contract</a>, <a href=\"../docs/agent-entry/quality-gate-r2/REVIEWER_AND_GOLDEN_TEMPLATES.md\">R00/R01/Golden/Batch receipts</a>, <a href=\"../docs/agent-entry/quality-gate-r2/quality-policy.v1.json\">actual policy status</a>, and <a href=\"review-guide.html\">Independent Audit Field Guide</a>.</p>\n      <div class=\"benchmark-box\">\n        <span class=\"benchmark-title\">Measurable source qualification and delegated review</span>\n        <ol style=\"margin:8px 0 4px 20px;padding:0;line-height:1.65;\">\n          <li><b>Exact source:</b> paper, set, question, stem, options, figure and answer/key identities agree. Authored transfers remain distinct from authenticated examination questions.</li>\n          <li><b>Independent science/QRT:</b> R01 independently derives the physics, assesses primary operation and five demand factors, and evaluates every applicable B1\u2013B7 witness; author labels do not confer D3/D4 acceptance.</li>\n          <li><b>Golden approval once:</b> a complete representative Core2 + Core1A + Core1B exemplar passes the scientific, novel-task, attempt-protection and adverse test gates. Owner approves the pinned exemplar and production standard once.</li>\n          <li><b>Delegated continuing review:</b> require an evidence packet per changed item, with a proposed independent minimum sample of 20% and at least one item per topic per batch. Review all new Physics laws, D4 proofs, disputed keys and defect-triggered items individually.</li>\n          <li><b>Honest admission status:</b> a scoped independent/delegated receipt\u2014not an author badge or green software test\u2014governs any academic-status promotion.</li>\n        </ol>\n      </div>\n      <div class=\"benchmark-box falsifier\">\n        <span class=\"benchmark-title\">Strict falsifier / failure trigger</span>\n        A fabricated reviewer receipt, contradictory source identity, incorrect law, cloned transfer, leaked precommit answer or changed question with no evidence packet holds the affected scope. <code>quality-policy.v1.json</code> remains <code>PILOT_AWAITING_OWNER_GOLDEN</code>; a passing pilot is not enforced branch protection or a Golden acceptance.\n      </div>\n    </article>\n\n    <!-- THE 4 PILLARS OF CORE 2 QUALITY -->\n    <section class=\"panel\" style=\"margin-top:28px;\">\n      <h2>The 4 Non-Bypassable Pillars of Core 2 Production (V4.1 Specification)</h2>\n      <p>To permanently eliminate developer regressions, stale cache loops, and jargon leaks, every candidate question module must satisfy all four operational dimensions before delivery:</p>\n      <div class=\"qa-table\">\n        <table>\n          <thead>\n            <tr>\n              <th style=\"width: 18%;\">Dimension</th>\n              <th style=\"width: 32%;\">V4.0 Legacy Defect / Failure Mode</th>\n              <th style=\"width: 50%;\">V4.1 Invariant Architecture Standard</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><b>1. Procedure</b><br><span class=\"stage-badge\" style=\"background:#e0f2fe;color:#0369a1;\">Execution Steps</span></td>\n              <td>\n                \u2022 Unspecified attempt lifecycle (options locked with no result banner).<br>\n                \u2022 Duplicate topic navigation bars (<code>#topicNav</code> vs header).<br>\n                \u2022 Stale disk caching of client-side scripts.\n              </td>\n              <td>\n                \u2022 <b>Three visible states with immutable evidence:</b> <code>Uncommitted</code> \u2794 <code>Committed (Feedback)</code> \u21cc <code>[\ud83d\udd04 New Linked Attempt]</code>. Preserve first response, content digest, help exposure and timestamp on retry.<br>\n                \u2022 <b>Single Master Controller:</b> One unified topic controller mounted immediately above in-place <code>#topicWorkspace</code> (zero scroll hunting).<br>\n                \u2022 <b>Cache Busting Protocol:</b> Explicit <code>?v=4.1.x</code> on all script tags and <code>{ cache: \"no-store\" }</code> on dynamic JSON fetches.\n              </td>\n            </tr>\n            <tr>\n              <td><b>2. Workflow</b><br><span class=\"stage-badge\" style=\"background:#fef3c7;color:#92400e;\">Boundary Gates</span></td>\n              <td>\n                \u2022 Developer mock phrases (<code>PRODUCER-PROPOSED</code>, <code>DIFFERS FROM PRODUCER</code>) leaked into student cards.<br>\n                \u2022 Raw SHA-256 hash digests and QRT formulas exposed in student card headers.<br>\n                \u2022 Building frontend readers before Gate 0 source sealing.\n              </td>\n              <td>\n                \u2022 <b>Adversarial Jargon Filter:</b> Strict segregation of student UI (clean badges, official keys, clear options) from internal audit registers.<br>\n                \u2022 <b>Encapsulated Audit Drawer:</b> All technical digests and QRT math are encapsulated inside a collapsed <code>&lt;details class=\"q-source-custody-drawer\"&gt;</code>.<br>\n                \u2022 <b>Fail-Closed Gate Hierarchy:</b> Gate 0 (Custody) \u2794 Gate 1 (QRT) \u2794 Gate 2 (DOM) \u2794 Gate 3 (Dual Verification).\n              </td>\n            </tr>\n            <tr>\n              <td><b>3. Self-Check</b><br><span class=\"stage-badge\" style=\"background:#fce7f3;color:#9d174d;\">Automated Linters</span></td>\n              <td>\n                \u2022 CI checks only verified <code>exit_code == 0</code> and <code>console_errors == 0</code>, allowing ugly mock strings and missing retry controls to pass as \"green\".<br>\n                \u2022 HTML named entities (<code>&amp;middot;</code>) crashed Chromium XML parser unnoticed.\n              </td>\n              <td>\n                \u2022 <b>Forbidden Jargon Linter:</b> Automated Playwright assertion regex testing <code>body</code> for <code>/producer/i</code>, <code>/differs from producer/i</code>, and <code>/stem digest agrees/i</code> (fails closed on match).<br>\n                \u2022 <b>W3C SVG XML Entity Linter:</b> Pre-commit check forbidding HTML named entities; enforcing UTF-8 literal characters (<code>\u00b7</code>, <code>\u2192</code>, <code>\u2715</code>) or numeric entities (<code>&amp;#183;</code>).<br>\n                \u2022 <b>Global ID Collision Linter:</b> Enforcing 100% unique question IDs across all subjects and examination years.\n              </td>\n            </tr>\n            <tr>\n              <td><b>4. Evidences</b><br><span class=\"stage-badge\" style=\"background:#dcfce7;color:#15803d;\">Tangible Proof</span></td>\n              <td>\n                \u2022 Handoffs relied solely on terminal text logs (<code>pytest passed</code>).<br>\n                \u2022 No visual verification that the committed state or retry flow actually functioned in the browser.\n              </td>\n              <td>\n                \u2022 <b>Visual Post-Commitment Screenshots:</b> Mandatory capture of timestamped Playwright screenshots (<code>playwright_evidence_qXX_[width].png</code>) visually proving feedback banner, option badges, and active reset button.<br>\n                \u2022 <b>Network Cache-Bypass Receipt:</b> Proof of HTTP 200 responses with updated payload bytes, ensuring reviewer inspects fresh code.<br>\n                \u2022 <b>Sealed Review Manifest:</b> SHA-256 manifest of all payload files under Rule 13 HOLD disposition.\n              </td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <!-- KEY PIPELINE LESSONS TABLE -->\n    <section class=\"panel\" style=\"margin-top:28px;\">\n      <h2>Key Pipeline Lessons &amp; Architecture Invariants (V4.1 Standard)</h2>\n      <div class=\"qa-table\">\n        <table>\n          <thead>\n            <tr>\n              <th>Operational Challenge</th>\n              <th>V4.0 Legacy Vulnerability</th>\n              <th>V4.1 Invariant Architecture Standard</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><b>Adversarial Developer Mock Strings &amp; Jargon</b></td>\n              <td>Defensive internal developer/mock phrases (<code>SELECTED \u00b7 DIFFERS FROM PRODUCER PROPOSAL</code>, <code>PRODUCER-PROPOSED</code>, <code>asserted stem digest agrees with display \u00b7 QRT HOLD</code>) leaked onto student question cards.</td>\n              <td>Completely eradicated all \"producer\" and raw hash strings. Use clean status labels from actual independently qualified state; do not hardcode Reviewed or peer-audited on candidate questions, instant evaluation banners (<code>\u2705 CORRECT</code> / <code>\u274c INCORRECT</code>), option badges, and interactive <code>\ud83d\udd04 Reset &amp; Try Again</code> controls. Cryptographic digests are strictly encapsulated inside collapsed <code>&lt;details&gt;</code> drawers.</td>\n            </tr>\n            <tr>\n              <td><b>Single Master Topic Navigation Bar</b></td>\n              <td>Two competing topic pill bars (one at top, another below for question filters) forced users to hunt and scroll, causing disorientation and mismatched topic filtering across subjects.</td>\n              <td>A single unified Master Topic Navigation Bar sits directly above the question bank, bidirectionally synchronized with the search bar, filter dropdowns, and deep-dive workspaces across Physics, Chemistry, and Biology.</td>\n            </tr>\n            <tr>\n              <td><b>W3C SVG Asset Standards &amp; XML Strictness</b></td>\n              <td>Embedded SVG diagrams containing HTML named entities (<code>&amp;middot;</code>, <code>&amp;rarr;</code>, <code>&amp;cross;</code>) triggered fatal XML parser errors in Chromium (<code>Entity 'middot' not defined</code>), causing blank diagrams on tablets.</td>\n              <td>All vector assets must strictly adhere to W3C XML standards using UTF-8 literal characters (<code>\u00b7</code>, <code>\u2192</code>, <code>\u21d2</code>, <code>\u2715</code>) or numeric entities (<code>&amp;#183;</code>, <code>&amp;#8594;</code>), with typography $\\ge 14\\text{px}$ and verified zero-error rendering across headless Playwright viewports.</td>\n            </tr>\n            <tr>\n              <td><b>Bit-for-Bit Stem SHA-256 Sealing &amp; Deduplication</b></td>\n              <td>Dummy placeholder hashes and duplicate question IDs (e.g. collisions between 2019 Optics and Electrostatics) tripped <code>asserted stem digest CONFLICTS with display</code> warnings and broke candidate custody.</td>\n              <td>Gate 0 enforces 100% unique question IDs across all subjects and bit-for-bit SHA-256 agreement between displayed stems and declared integrity manifests (<code>declared_matches_observed: true</code> across 100% of candidate records).</td>\n            </tr>\n            <tr>\n              <td><b>Client-Side Cache Invalidation &amp; Attempt Migration</b></td>\n              <td>Tablet browsers aggressively cached JavaScript and data JSONs on disk, running stale prototype code even after repository updates were deployed.</td>\n              <td>Enforce versioned query parameters (<code>?v=4.1.5</code>) on all script tags and <code>{ cache: \"no-store\" }</code> on dynamic JSON fetches, with backward-compatible <code>localStorage</code> attempt migration so user attempts are preserved across updates.</td>\n            </tr>\n            <tr>\n              <td><b>Disconnected Candidate Banks</b></td>\n              <td>Stage 5 candidate question bank was an isolated silo with no links to Stage 6 learning modules.</td>\n              <td>Every candidate card and topic header features dynamic <code>#topic-core1-ribbon</code> and direct touch buttons bridging into 3-stage / 6-stage master lessons.</td>\n            </tr>\n            <tr>\n              <td><b>Empty Tab 1 Disclaimers</b></td>\n              <td>Stage 6 Core 1 modules hid target problems behind legal disclaimers (\"Source authority note\").</td>\n              <td>Tab 1 must render the complete, self-contained reference problem statement, vector SVG diagram, and unassisted attempt commitment box across 100% of lessons.</td>\n            </tr>\n            <tr>\n              <td><b>Removing {Unvalidated} in CI</b></td>\n              <td>Confusion over whether passing green unit tests allowed removing Rule 13 warning banners.</td>\n              <td>Software CI only certifies Stage 7 mechanical compliance. Rule 13 HOLD is an immutable Stage 8 gate, strictly removable only by human academic review receipts.</td>\n            </tr>\n            <tr>\n              <td><b>12.7\" Tablet Ergonomics</b></td>\n              <td>Cramped inline anchor tags and squished topic links failed tablet touch targets.</td>\n              <td>All interactive filters, buttons, and route cards strictly adhere to $\\ge 48\\text{px}$ touch targets, zero layout shifts, and 0px horizontal scroll overflow.</td>\n            </tr>\n            <tr>\n              <td><b>Blueprint Validation Boundaries</b></td>\n              <td>Assuming author-proposed QRT demand scores (<code>MODEL / D2</code>) or green build passes constituted \"Blueprint Validation\".</td>\n              <td>Software generation is candidate authoring only. Physics blueprint is a draft WPE pilot; Chemistry and Biology blueprints are unapproved. All items remain under fail-closed <code>HOLD: ACADEMIC_ADMISSION</code> until blind Stage 8 expert review.</td>\n            </tr>\n            <tr>\n              <td><b>QRT Operation &amp; Demand Visibility</b></td>\n              <td>QRT cognitive terms (<code>RETRIEVE</code>, <code>MODEL</code>, <code>SYNTHESIZE</code>) and D1\u2013D4 Demand bands were buried in internal JSON maps, invisible on top-level cards.</td>\n              <td>Every candidate card, recovery module, and lesson directory must surface high-visibility QRT Operation pills, D-Band ratings, and decisive Crux Move tags directly in the user interface.</td>\n            </tr>\n            <tr>\n              <td><b>Elimination of Internal Agent Jargon</b></td>\n              <td>Internal multi-agent plumbing and handoff stubs (<code>Agent A</code>, <code>Agent B</code>, <code>remain with Agent A</code>, <code>Core 2 status</code>) leaked into student-facing lesson headers and tab bars.</td>\n              <td>All user-facing headers, tabs, and metadata must strictly adhere to clean disciplinary standards (<code>1. Core 2 Target Problem</code>, <code>Target Item \u2022 Demand Band \u2022 QRT Operation \u2022 Crux Move</code>) with zero internal agent role terminology.</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </section>",
  "production-checklist": "<div class=\"status\"><strong>Current Core2 publication scope: technical review only</strong><p>Academic admissions 0; source authenticity, figures, official keys, independent QRT and Owner release remain distinct gates. D3.1 PAUSED. This checklist is an engineering acceptance specification, not a grant of academic release.</p></div>\n<section class=\"panel\" id=\"tablet-core2\"><h2>Required: 12.7-inch tablet QA for Core2</h2><p>Before each production deployment of the Physics/WPE Core2 Question Bank, open the actual first-class page at <a href=\"../preview/question-status.html\">Question Bank</a> directly\u2014<strong>not in an iframe</strong>. Run tests on the exact commit and collect screenshots at the minimum CSS viewport sizes below. The physical 12.7-inch diagonal does not uniquely determine CSS pixels; test at known CSS viewport and DPR settings and record the device/browser used.</p><div class=\"qa-table\"><table><thead><tr><th>Test</th><th>Target viewport (CSS px)</th><th>Acceptance requirement</th></tr></thead><tbody><tr><td>Tablet landscape A</td><td>1280 \u00d7 800</td><td>Sidebar and reader both visible; no page horizontal overflow; all controls reachable</td></tr><tr><td>Tablet landscape B</td><td>1024 \u00d7 768</td><td>Question navigator, question text, source warnings and buttons readable without clipping</td></tr><tr><td>Tablet portrait A</td><td>900 \u00d7 1280</td><td>Two-column layout remains usable without excessive compression; no clipped options/figures</td></tr><tr><td>Tablet portrait B</td><td>800 \u00d7 1280</td><td>Compact stacked layout, short navigator list, reader immediately below, no nested iframe scrolling</td></tr><tr><td>Regression check</td><td>1365 \u00d7 768 and 390 \u00d7 844</td><td>Desktop and narrow fallback not broken by the tablet styles</td></tr></tbody></table></div><ol class=\"tick\"><li>Open direct URL and confirm <span class=\"code\">document.querySelectorAll('iframe').length === 0</span>.</li><li>Confirm <span class=\"code\">document.documentElement.scrollWidth &lt;= innerWidth</span> at all target sizes; inspect tables, math, figures and long source labels.</li><li>Verify there is <strong>one site navigation</strong> and a clear Physics \u2192 WPE \u2192 Question Bank path; no duplicate app nav or nested page scrollbar.</li><li>Open a real question with a long prompt/diagram, last question, filtered question and an empty filter result; check Previous/Next, search, source filter and proposed-band filter.</li><li>Enter an answer, commit the local attempt, reveal hints in order, reveal the author-proposed solution deliberately; ensure key text does not leak before the permitted step.</li><li>Verify keyboard focus, selectable text, visible tab controls, minimum touch targets ~44 CSS px and readable contrast; test actual on-device zoom if available.</li><li>Record screen dimensions, DPR, browser version, page SHA, screenshots, browser console failures, pass/fail disposition and remaining NOT_RUN. Device testing cannot be inferred from a stylesheet review.</li></ol><div class=\"callout\"><b>Core2 UI no-go:</b> iframe inside a second scrolling page, side-by-side content too narrow to read, inaccessible buttons, viewport overflow, or unrecoverable navigation. Fix and retest before a claim of technical production readiness.</div></section>\n<section class=\"panel\" id=\"preview-navigation\"><h2>Student preview branches and tablet navigation</h2><p>The old Physics demo and its linked pages\u2014Explore, Learn WPE, Practice, My Progress, What\u2019s Next, and the WPE collections\u2014must use one shared site navigation, not two overlapping menus. Subject links and chapter shortcuts have different purposes; never repeat the same Home / Learn / Practice bar in the page header.</p><ol class=\"tick\"><li>Verify the same four subject/Architecture destinations on all branch pages, and working WPE chapter, Learn, Practice, Question Bank, Examples and Progress links.</li><li>Keep the practice question visible without an oversized warning. A short visible preview notice must retain a discoverable full explanation of academic HOLDs.</li><li>Test the actual <strong>selected answer \u2192 explanation \u2192 attempt recorded \u2192 deliberate solution reveal \u2192 session progress</strong> sequence, plus slider input on Learn WPE and local progress reset.</li><li>At tablet widths 1280, 1024, 900 and 800 CSS px check no duplicated navigation, no horizontal document overflow, readable MathML and natural card wrapping. Include a narrow regression and both light/dark user preferences.</li><li>Capture source revision, browser results, screenshots and failed/error state. A deploy workflow success alone is not tablet acceptance.</li></ol><p>Automatic regression workflow: <a href=\"https://github.com/reallakshman19/Grade9v4.0/blob/main/.github/workflows/preview-ui.yml\">Preview tablet and practice UI QA</a> (use its actual completed run, not this link, to assert PASS).</p></section><section class=\"panel\" id=\"source\"><h2>Source, scientific and cognitive gates</h2><ol class=\"tick\"><li>Exact exam/source identity, variant, paper, answer-key source, figures and rights are independently accounted for. Hold every unresolved asset; do not use synthetic figures as authenticated originals.</li><li>SL1 exact source identity and eligibility, optional real P1 attempt history, SL2 proposed task-specific factors and shortest valid reasoning route are pinned to this revision.</li><li>Subject Blueprint and WPE topic adapter version/hash are properly selected by the authorized Owner. The current Physics D3/D4 draft and WPE adapter candidates are not approved selections.</li><li>Independent QRT resolves operation, five-factor demand, direct exam versus authored transfer role and any counterexample. Author/computational self-tests cannot substitute for blind review.</li><li>Core2 answer semantics, stage reveals and conditions are preserved. Core1A/1B teaching and fresh reconstruction require B1\u2013B7 evidence and independent scientific checks.</li></ol><p class=\"small\">Source: <a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Current concept companion</a>, <a href=\"../docs/agent-entry/07-independent-review.md\">Independent review entry</a>, <a href=\"../docs/agent-entry/04-output.md\">Native output rules</a>.</p></section>\n<section class=\"panel\" id=\"oracle-core1a\"><h2>Core1A Oracle: coordination and handoff</h2><p>The Owner has designated this conversation as an <b>Oracle for Core1A</b> coordination point. This does not itself select standalone versus OTM mode, authorize dispatch or approve native content. Apply <a href=\"https://github.com/reallakshman19/Common/blob/main/skills/agent-work/START_HERE.md\">Common agent-work START_HERE</a> and the relevant <a href=\"https://github.com/reallakshman19/Common/blob/main/skills/agent-work/nudge-designer/references/ORACLE_EXECUTION.md\">Oracle execution rules</a>; the <a href=\"https://github.com/reallakshman19/Common/blob/main/skills/agent-work/oracle-standalone/SKILL.md\">standalone mode</a> applies only if selected for this project.</p><ol class=\"tick\"><li>Identify the governing existing Progress/WBS step, exact native issue, Owner aim and task source; do not create a parallel WBS or invented Cycle state.</li><li>Check current Core2 completion and actual Owner acceptance for this WPE-specific dependency before native Core1A promotion. Parallel read-only source preparation does not imply lesson acceptance.</li><li>Review raw candidate/relay inputs, expected wrong case, independent scientific reviewer status, permitted artifact transfer and latest recorded return.</li><li>Keep acting Oracle coordination separate from implementation self-review and a truly independent reviewer; no self-issued academic PASS or Owner acceptance.</li><li>When a Core1A slice is authorized, provide one bounded task with original evidence, model conditions, expected output, a discriminating test and exact return route; update the existing Project Home/Progress rather than a substitute report.</li></ol><p class=\"small\">Mode, existing WBS and authorized task state are <strong>not verified in this UI-only publication</strong>. No Oracle Cycle, agent relay or protected Core1A authoring has been initiated by this page.</p></section>\n<section class=\"panel\" id=\"deployment\"><h2>Publish and evidence</h2><ol class=\"tick\"><li>Check the final Git tree paths and link integrity: Home \u2192 Physics \u2192 WPE \u2192 Question Bank, Architecture \u2192 Concept \u2192 Checklist, the 79-record source index and the older direct URL.</li><li>Run JavaScript syntax/behavior checks and release-level browser tests on the complete original Core2 content; record precise viewport results and distinguish NOT_RUN from FAIL.</li><li>Check CI and GitHub Pages result for the exact HEAD SHA; do not announce deployed until the workflow confirms success.</li><li>Retain the old URL and protect source data. Only the actually authorized public technical-preview site is published; no native Core1A or QRT promotion is inferred.</li></ol><p class=\"small\">This checklist is effective as an engineering <strong>requirement to test</strong>, not a claim that today's tests have all passed. Use fail-closed status until device evidence exists.</p><div class=\"linklist\"><a href=\"../docs/agent-entry/concept-report-v4.html#production-checklist\">Concept report entry</a><a href=\"guidebook.html#checks\">Architecture guidebook checks</a><a href=\"../physics/wpe/index.html\">WPE chapter</a></div></section>",
  "review-guide": "<div class=\"status\">\n <strong>Reviewer rule: attempt to falsify the author's claims.</strong>\n <p>A file hash proves which bytes were examined; CI proves specific software behavior. Neither proves scientific accuracy, textbook teaching sufficiency, new cognitive demand or independent student mastery. Author evidence, R00 technical review, independent R01 review and Owner acceptance are different authorities.</p>\n</div>\n<div class=\"auditor-shell\">\n<aside class=\"auditor-toc\" aria-label=\"Audit guide contents\">\n  <b>Auditor contents</b>\n  <a href=\"#scope\">00 \u00b7 Scope and status</a>\n  <a href=\"#roles\">01 \u00b7 Roles and independence</a>\n  <a href=\"#intake\">02 \u00b7 Exact-head intake</a>\n  <a href=\"#science\">03 \u00b7 Physics science audit</a>\n  <a href=\"#core1a\">04 \u00b7 Core1A textbook audit</a>\n  <a href=\"#core1b\">05 \u00b7 Core1B transfer audit</a>\n  <a href=\"#core2\">06 \u00b7 Core2 source/reader audit</a>\n  <a href=\"#qrt\">07 \u00b7 QRT and B1\u2013B7</a>\n  <a href=\"#runtime\">08 \u00b7 Browser and negative tests</a>\n  <a href=\"#coverage\">09 \u00b7 Coverage and integration</a>\n  <a href=\"#findings\">10 \u00b7 Findings and stop rules</a>\n  <a href=\"#receipt\">11 \u00b7 Exact-head audit return</a>\n  <a href=\"#golden\">12 \u00b7 Golden and batch review</a>\n  <a href=\"#references\">13 \u00b7 Reading order and references</a>\n  <a href=\"core1ab-agent-guide.html\">Authoring guide</a>\n  <a href=\"core2-source-to-learning-pipeline.html\">Core2-led pipeline</a>\n</aside>\n<div>\n<section class=\"audit-section\" id=\"scope\">\n <h2>00 \u00b7 What this guide does\u2014and does not\u2014govern</h2>\n <span class=\"audit-label\">R00 \u00b7 Technical</span><span class=\"audit-label\">R01 \u00b7 Independent academic</span><span class=\"audit-label hold\">R2 policy currently PILOT</span>\n <p>This page is the <strong>auditor-facing operating manual</strong>. The <a href=\"core1ab-agent-guide.html\">Core1A/Core1B Agent Field Guide</a> explains how agents author curriculum-first textbook and protected learning journeys. The <a href=\"core2-source-to-learning-pipeline.html\">Core2-Led Source-to-Learning Pipeline</a> explains the examination-question-first eight-stage route. Neither substitutes for this independent audit.</p>\n <div class=\"audit-grid\">\n  <div class=\"audit-tile\"><strong>Curriculum-first evidence</strong> Audit complete scientific teaching, the subtopic scope and genuinely new Core1B tasks even when no authenticated exam question is available. Core2 linkage may remain explicitly unqualified.</div>\n  <div class=\"audit-tile\"><strong>Core2-led evidence</strong> Audit source question identity, stem/figure/key fidelity, cognitive profiling, the native question reader and justified connections to Core1A and Core1B.</div>\n </div>\n <div class=\"audit-rule warning\"><strong>Current activation fact:</strong> the repository's <a href=\"../docs/agent-entry/quality-gate-r2/quality-policy.v1.json\">R2 policy</a> remains <code>PILOT_AWAITING_OWNER_GOLDEN</code> and <code>production_enabled=false</code>. A green pilot workflow is not proof that authors are blocked by production branch protection. Do not claim the Golden Sample was accepted unless a real Owner receipt and active policy exist.</div>\n <p><strong>Scope boundary:</strong> this protocol evaluates education, science, source identity and runtime evidence. Redistribution-rights assessment is excluded from this quality audit at Owner direction. Source authenticity and figure completeness are still required.</p>\n</section>\n<section class=\"audit-section\" id=\"roles\">\n <h2>01 \u00b7 Authority, independence and reviewer eligibility</h2>\n <div class=\"audit-table\"><table><thead><tr><th>Role</th><th>Permitted actions</th><th>Prohibited claims/actions</th></tr></thead><tbody>\n  <tr><td><strong>Author</strong></td><td>Construct teaching, solve problems, run self-checks, inject negative faults and submit an author evidence packet.</td><td>Cannot sign R00/R01/Owner receipts or promote its own D-band, science, QRT or release claims.</td></tr>\n  <tr><td><strong>R00 \u2014 Technical auditor</strong></td><td>Verify scope, exact files, hashes, CI/browser, actual learner state, coverage and contradictions; issue technical PASS-pending-academic, REQUEST_CHANGES or HOLD_BLOCKER.</td><td>Cannot turn a green test into academic approval, forge R01 evidence or quietly rewrite the author's chapter under reviewer-only mode.</td></tr>\n  <tr><td><strong>R01 \u2014 Independent Physics/QRT reviewer</strong></td><td>Independently solve unseen tasks before reading the key, derive Physics, assess Core1A sufficiency, Core1B freshness, B1\u2013B7 and exact cognitive demand.</td><td>Cannot claim blind review if exposed to the solution, or approve an uninspected source/revision.</td></tr>\n  <tr><td><strong>Owner</strong></td><td>Select and approve one representative Golden exemplar and standard, delegate routine batch review, authorize exceptional specification changes.</td><td><strong>Not required to approve each subsequent question.</strong></td></tr>\n </tbody></table></div>\n <p><strong>Exposure declaration is mandatory.</strong> R00 previously contributed to PH01 and the C06 v1.1 interface. R00 may audit those technically but cannot independently issue a cold R01 academic verdict on them. A reviewer who has viewed an author's answer before the independent attempt must record <code>EXPOSED</code>.</p>\n <div class=\"audit-rule\">In reviewer-only mode, corrections belong to the author/coding agent. The auditor returns an exact reproduction and required fix, then inspects the revised commit. If the Owner changes the auditor's role to fixer, disclose that role change and do not count the subsequent self-review as independent.</div>\n</section>\n<section class=\"audit-section\" id=\"intake\">\n <h2>02 \u00b7 Audit intake: freeze the real object under review</h2>\n <ol class=\"audit-steps\">\n  <li><strong>Pin exact identity.</strong> Record PR and exact head/base SHA, branch, author workpack, topic/subtopic IDs, source item UIDs and the proposed denominator. Check merge status and parents; an unmerged PR is not production.</li>\n  <li><strong>Pin contracts.</strong> Record C01\u2013C08 version, selected C06 v1/v1.1 rule, Shared 28-QRT source/blob, subject Physics Blueprint, adapter and any Golden Sample pin. Unselected or paused rules remain HOLD.</li>\n  <li><strong>Compare actual changed files.</strong> Enumerate full PR diff, deleted/renamed assets, other agents' paths, new figures, content packages, generated pages and tests. Challenge unexpected scope and silent rewriting of historical evidence.</li>\n  <li><strong>Verify author packet from bytes.</strong> Inspect the actual <a href=\"../docs/agent-entry/quality-gate-r2/EVIDENCE_PACKET.template.json\">R2 packet schema</a> and run the <a href=\"../docs/agent-entry/quality-gate-r2/verify_evidence_packet.py\">evidence validator</a>. Confirm every cited file SHA-256, smallest relevant line span and verbatim excerpt. Reject recycled quotes or fake log labels.</li>\n  <li><strong>Compare declared with observed.</strong> The author may describe a passing suite, scientific law, learner behavior or source status. Independently check the underlying code/page, test trace, artifact receipt or source record before repeating that claim.</li>\n </ol>\n <div class=\"audit-rule failure\"><strong>Automatic HOLD:</strong> wrong branch/contract, missing governing source, unresolvable citation, contradicted SHA, fabricated reviewer receipt, unowned path edit, or a new source claim with no authentication evidence. Continue unrelated review where safe, but do not certify the affected item.</div>\n</section>\n<section class=\"audit-section\" id=\"science\">\n <h2>03 \u00b7 Physics science: five independently inspectable witnesses</h2>\n <p>The auditor must check physical truth, not just whether an equation exists. For R01, solve the task <strong>before opening the authored model solution</strong>; record an independent derivation and compare only afterwards.</p>\n <div class=\"audit-table\"><table><thead><tr><th>Witness</th><th>Required evidence</th><th>Auditor's falsifier</th></tr></thead><tbody>\n <tr><td>Primary law and derivation</td><td>Physical model, defined variables, assumptions, starting principle, valid steps and stated conclusion.</td><td>Re-derive from first principles; locate the first unjustified inference.</td></tr>\n <tr><td>Independent check</td><td>Different reasoning route, conservation check, graphical reconstruction or independent numeric substitution.</td><td>Reproduce without copying the author's algebra.</td></tr>\n <tr><td>Units and signs</td><td>Dimensions of both sides, coordinate convention, sign of physical quantity, conversions.</td><td>Inject an omitted density/mass factor or reverse the axis; should expose a contradiction.</td></tr>\n <tr><td>Model limits</td><td>Validity domain, regime assumptions and meaningful limiting cases.</td><td>Apply at a boundary or beyond the valid interval and show the failure.</td></tr>\n <tr><td>Counterexample/figure</td><td>A counterexample to an attractive false generalization, physically accurate scientific diagram.</td><td>Flip a force or ray, remove an axis or test impossible values; determine if the intended inference changes.</td></tr>\n </tbody></table></div>\n <p><strong>Example mandatory unit trap:</strong> for upward-positive height in a uniformly accelerating fluid container, <span class=\"audit-inline\">dP/dy = \u2212\u03c1(g+a)</span>, not <span class=\"audit-inline\">\u2212(g+a)</span>. The latter has incorrect dimensions; a lesson with the wrong scientific relation must not pass because its surrounding prose looks complete.</p>\n <div class=\"audit-rule\">Scoring: each of law fidelity, causal teaching, representation, misconception diagnosis and independent checking is 0\u20133. A zero is HOLD, a one requires changes; a high average cannot compensate for a wrong equation. Mechanical hash compliance does not adjudicate Physics.</div>\n</section>\n<section class=\"audit-section\" id=\"core1a\">\n <h2>04 \u00b7 Core1A: audit a real textbook, not answer scaffolding</h2>\n <p>Hide the Core2 source question, key and worked solution. Ask whether the chapter remains a coherent independent lesson and whether a new learner can reconstruct the required scientific idea from its own explanation.</p>\n <div class=\"audit-grid\">\n   <div class=\"audit-tile\"><strong>A1\u2013A3 \u00b7 Intuition and mechanism</strong> Observable phenomenon, necessary prerequisites, conceptual cause before formula. No unexplained new variable or unsupported model jump.</div>\n   <div class=\"audit-tile\"><strong>A4\u2013A5 \u00b7 Warrant and visuals</strong> Derivation, assumptions, validity, accurate scientific axes/labels and a meaningful diagram that supports reasoning rather than decoration.</div>\n   <div class=\"audit-tile\"><strong>A6\u2013A7 \u00b7 Worked progression and misconception</strong> Foundation / Connected / Advanced examples with genuinely increasing reasoning; specific plausible wrong model, first error and repair.</div>\n   <div class=\"audit-tile\"><strong>A8\u2013A9 \u00b7 Boundary and synthesis</strong> Counterexample, limitations, an independently solvable concept check and an expected scientific explanation.</div>\n </div>\n <h3>Auditor challenges</h3>\n <ul>\n  <li>Remove the source question. Can the reader still explain why the law works, not merely use it?</li>\n  <li>Hide the worked anchor. Could the reader answer a <em>new</em> conceptual challenge using only the chapter's taught prerequisites?</li>\n  <li>Does the advanced example add a genuine physical inference or only more arithmetic and changed numbers?</li>\n  <li>Is every critical equation unit/sign checked and every graph/figure consistent with its scientific claim?</li>\n </ul>\n <div class=\"audit-rule failure\"><strong>Reject B3 teaching sufficiency</strong> when the chapter consists only of formula boxes, abbreviated worked answers or stock hints; when the decisive physical move is not taught; or when diagrams are missing/misleading. Word count, headings and three examples alone are never proof of textbook quality.</div>\n</section>\n<section class=\"audit-section\" id=\"core1b\">\n <h2>05 \u00b7 Core1B: prove genuinely fresh learner-owned work W</h2>\n <p>For each proposed INSTANCE and MAIN, inspect actual student-visible text\u2014not only metadata. Create a side-by-side anchor-versus-transfer comparison and independently solve the shortest valid route.</p>\n <div class=\"audit-table\"><table><thead><tr><th>Compare</th><th>Core1A worked anchor</th><th>Core1B fresh task</th></tr></thead><tbody>\n  <tr><td>Given information and model</td><td>Actual stated premises and assumptions</td><td>Actual materially different premises/assumptions</td></tr>\n  <tr><td>Decisive work W</td><td>Model choice, inference or proof already taught</td><td>Which decision the learner must now independently make</td></tr>\n  <tr><td>Shortest valid solution</td><td>Verified full route</td><td>Verified full independent route and constraints</td></tr>\n  <tr><td>Competing wrong model</td><td>Known shortcut and its failure</td><td>New boundary or misconception that makes blind copying fail</td></tr>\n  <tr><td>QRT operation</td><td>Teaching aim, not automatically a QRT band</td><td>One proposed primary operation and independently checked five-factor demand</td></tr>\n </tbody></table></div>\n <div class=\"audit-rule failure\"><strong>Hard freshness rejection:</strong> remove numerical values from both problems. If the same model, algorithm or exact proof solves both without any new inference, mark B4 HOLD even if the wording or context changes. In addition, inspect the Core1A explanation for exact symbolic identities that give away the Core1B proof.</div>\n <h3>Six-stage protection and diagnosis</h3>\n <ol>\n  <li><strong>Predict:</strong> learner commits a meaningful model/sign expectation, not an answer copied from a hint.</li>\n  <li><strong>Attempt:</strong> an independent first answer and content SHA are persisted before explanations or H1\u2013H3 unlock. Storage failure is fail-closed.</li>\n  <li><strong>Reconstruct:</strong> full correct scientific solution is revealed only after successful saving; previous first answer immutable.</li>\n  <li><strong>Diagnose:</strong> identify a plausible first wrong inference, not a generic \u201ccheck your calculation\u201d message.</li>\n  <li><strong>Repair:</strong> learner writes revised reasoning separately without overwriting the first attempt.</li>\n  <li><strong>Boundary:</strong> learner first tackles a materially changed condition before seeing its model solution.</li>\n </ol>\n <p><strong>H1/H2/H3:</strong> clarify observation \u2192 correlate relevant relationships \u2192 open a route without disclosing decisive W. Check hints, pre-rendered DOM, SVG labels and source-return links for early solution leakage.</p>\n <p><strong>C06 v1.1 integrated MAIN:</strong> one MAIN per populated QRT cell with at least two distinct subtopic instances, all bound members and a genuine joint inference. Metadata listing several instances is not proof that the task uses them together.</p>\n</section>\n<section class=\"audit-section\" id=\"core2\">\n <h2>06 \u00b7 Core2: examination fidelity, reasoning and honest reader status</h2>\n <p>Keep <strong>DIRECT_EXAM_EVIDENCE</strong>, <strong>PREREQUISITE_BRIDGE</strong> and <strong>AUTHORED_TRANSFER</strong> distinct. Audit original paper/year/set/question, exact source stem/options/figure/key digest when an original is claimed. A candidate or preparation association is not an authenticated exam question.</p>\n <ul>\n  <li><strong>Complete visual question:</strong> if a required graph, force diagram, ray or circuit figure is missing, the affected question remains HOLD. Do not silently delete a <span class=\"audit-inline\">[FIG]</span> marker and proceed as if complete.</li>\n  <li><strong>Independent answer:</strong> derive the correct result with units, constraints and explanation. A key letter without a physically coherent route is not sufficient.</li>\n  <li><strong>Commitment-first UX:</strong> feedback and key remain locked until the first response is saved. Retry creates a new linked revision, never deletes the original attempt.</li>\n  <li><strong>Canonical status:</strong> the displayed badge is derived from genuine qualified source/academic state; hardcoded <span class=\"audit-inline\">{Reviewed}</span> or peer-audit claims are prohibited without receipts.</li>\n  <li><strong>Learning join:</strong> verify exact question UID \u2192 scientific demand \u2192 Core1A teaching \u2192 fresh Core1B task. If qualification is missing, show a truthful gap instead of invented completeness.</li>\n </ul>\n <div class=\"audit-rule warning\">The question-first Core2 production stages are documented in the separately renamed <a href=\"core2-source-to-learning-pipeline.html\">Core2-Led Source-to-Learning Pipeline</a>. A curriculum-first Core1A chapter may proceed without authentic Core2 exam coverage; the missing exam-source link must remain explicit.</div>\n</section>\n<section class=\"audit-section\" id=\"qrt\">\n <h2>07 \u00b7 QRT and B1\u2013B7: verify the mental move independently</h2>\n <p>For a claimed QRT task, determine one <strong>primary</strong> operation from the actual shortest reasoning route, not the author's title. The seven Shared operations are RETRIEVE, EXPLAIN, APPLY, MODEL, REPRESENT, SYNTHESIZE and JUSTIFY. Apply the source-pinned five factors (each 0\u20132), and disclose disputed or paused Blueprint cells. A long calculation is not automatically D4.</p>\n <div class=\"audit-table\"><table><thead><tr><th>Witness</th><th>Minimum auditor finding</th></tr></thead><tbody>\n <tr><td><strong>B1 Target</strong></td><td>Appropriate scientific learning target, prerequisites and scoped source.</td></tr>\n <tr><td><strong>B2 Construction</strong></td><td>Correct primary operation, protected W and five-factor demand evidence.</td></tr>\n <tr><td><strong>B3 Core1A</strong></td><td>Actual teaching of the decisive inference, checked cold-read and full concept explanation.</td></tr>\n <tr><td><strong>B4 Core1B</strong></td><td>Unseen transfer requiring a new genuine inference, not a numerical clone.</td></tr>\n <tr><td><strong>B5 Protection</strong></td><td>Immutable first response, revision-specific digest, pre-first help state and no leak.</td></tr>\n <tr><td><strong>B6 Repair/Boundary</strong></td><td>Specific first-error diagnosis, learner repair and changed-condition reasoning.</td></tr>\n <tr><td><strong>B7 Physics/Provenance</strong></td><td>Defensible laws, sign/limits, diagram, source-role fidelity and exact revision.</td></tr>\n </tbody></table></div>\n <p>R00 may validate task bindings, score arithmetic and evidence integrity. Only an eligible, genuinely unexposed R01 can present an independent scientific/QRT/B1\u2013B7 academic determination. Every witness is noncompensatory: another PASS cannot substitute for a HOLD.</p>\n</section>\n<section class=\"audit-section\" id=\"runtime\">\n <h2>08 \u00b7 Exact-head engineering, HTTP Chromium and fault injection</h2>\n <p>Run or independently inspect unchanged full Python QA and real served HTTP Chromium. Confirm the **same exact content head** as the audited PR, and record job IDs, artifacts and untested paths. A successful synthetic fixture is not a student-page end-to-end receipt.</p>\n <div class=\"audit-grid\">\n <div class=\"audit-tile\"><strong>12.7-inch tablet</strong> 1000\u00d71600 portrait and 1600\u00d71000 landscape; keyboard/touch, no horizontal overflow, navigation, refresh, readable figures.</div>\n <div class=\"audit-tile\"><strong>Protected evidence</strong> First answer/choice before hint or solution; failed storage, reset, stale content, source/textbook return, H1\u2013H3 exposure and boundary gating.</div>\n </div>\n <h3>Eight Golden Sample negative controls</h3>\n <div class=\"audit-table\"><table><thead><tr><th>Mutation</th><th>Expected observed rejection</th></tr></thead><tbody>\n  <tr><td>WRONG_DIMENSION</td><td>Units check rejects omitted density/mass or dimensional inconsistency.</td></tr>\n  <tr><td>WRONG_SIGN_OR_LIMIT</td><td>Scientific check rejects wrong frame, reversed sign or invalid model domain.</td></tr>\n  <tr><td>NUMERIC_CLONE</td><td>Freshness audit rejects Core1A answer with only new numbers.</td></tr>\n  <tr><td>HINT_LEAK</td><td>Early H1\u2013H3/DOM/diagram disclosure is detected.</td></tr>\n  <tr><td>BAD_SOURCE_FIGURE</td><td>Missing or inverted critical figure blocks question.</td></tr>\n  <tr><td>SAVE_FAILURE</td><td>Failed persistence does not unlock solution or claim a first attempt.</td></tr>\n  <tr><td>STALE_REVISION</td><td>Old content digest cannot be treated as an attempt on new revision.</td></tr>\n  <tr><td>FALSE_REVIEW_BADGE</td><td>Unqualified item cannot display independent approval labels.</td></tr>\n </tbody></table></div>\n <p>Golden: all eight families. Subsequent item packets: at least wrong-dimension, numeric-clone and hint-leak tests, plus inherited batch-wide runtime/figure regressions. The reviewer must check <em>actual injection, command, observed rejection log and reason for rejection</em>. A handwritten <span class=\"audit-inline\">REJECTED</span> string does not prove a test ran.</p>\n <div class=\"audit-code\">python -m pytest -q\npython -m pytest -q tests/test_physics_quality_gate_r2.py\npython docs/agent-entry/quality-gate-r2/verify_evidence_packet.py \\\n  review/quality-packets/physics/PHxx/&lt;task-uid&gt;.packet.json\npython docs/agent-entry/quality-gate-r2/enforce_pr_packets.py \\\n  --base &lt;exact-parent-SHA&gt;</div>\n <p class=\"audit-foot\">The packet validator can report EVIDENCE_STRUCTURALLY_GROUNDED while academic_status remains HOLD. Pilot PR enforcement may report PILOT_NOT_ENFORCED; do not mislabel either as educational acceptance.</p>\n</section>\n<section class=\"audit-section\" id=\"coverage\">\n <h2>09 \u00b7 Question-level coverage and cross-agent reconciliation</h2>\n <p>Audit a <strong>stable UID + exact revision</strong> per task. Reconcile every source question to its exact Core1A teaching and Core1B INSTANCE/MAIN coverage. Record source roles, missing dependencies, duplicate IDs, historical aliases and the selected contract version. Never substitute 56 authored cycles for 56 independently qualified exam questions.</p>\n <div class=\"audit-table\"><table><thead><tr><th>Separate denominator</th><th>What may be counted</th></tr></thead><tbody>\n  <tr><td>Candidate syllabus subtopics</td><td>Stable inventoried subtopic IDs; not proof of fully taught lessons.</td></tr>\n  <tr><td>Core1A authored / qualified</td><td>Substantive student-readable modules versus independently accepted B3.</td></tr>\n  <tr><td>Core1B INSTANCE / MAIN</td><td>Actually authored and runtime-tested cycles versus independently classified QRT/B4\u2013B6.</td></tr>\n  <tr><td>Core2 preparation links</td><td>Authored question-to-learning associations; not authenticated source items.</td></tr>\n  <tr><td>Authenticated original Core2</td><td>Only items with verified source identity, figure, answer and appropriate scoped review.</td></tr>\n  <tr><td>Owner/Golden or batch release</td><td>Actual approved exemplar and delegated policy receipt, not a green workflow alone.</td></tr>\n </tbody></table></div>\n <div class=\"audit-rule\">If a parent/stacked branch has changed, inspect all intervening diffs. Do not auto-rebase away student source identity, accept a contract downgrade or count an unmerged PR as deployed. Each author owns its assigned PHxx files; R00 reviews but does not silently author fixes.</div>\n</section>\n<section class=\"audit-section\" id=\"findings\">\n <h2>10 \u00b7 Decisions, P0/P1/P2 and noncompensatory STOP rules</h2>\n <div class=\"audit-table\"><table><thead><tr><th>Severity</th><th>Examples</th><th>Required action</th></tr></thead><tbody>\n  <tr><td><strong>P0 \u2014 HOLD_BLOCKER</strong></td><td>Materially wrong Physics, forged evidence, false source/approval label, leaked protected W, failed first save bypass, harmful merged ownership, silent schema downgrade.</td><td>Hold affected task/batch, independently inspect same defect family, return exact reproduction and protect against release.</td></tr>\n  <tr><td><strong>P1 \u2014 REQUEST_CHANGES</strong></td><td>Core1A too thin, Core1B clone, incorrect or incomplete example, inadequate diagnosis, missing evidence, broken keyboard state, source/coverage overclaim.</td><td>Agent fixes actual content and regenerates packet/tests; reviewer reevaluates exact revision.</td></tr>\n  <tr><td><strong>P2 \u2014 DOCUMENT_FOLLOWUP</strong></td><td>Nonblocking wording, figure readability, extra explanatory example, presentation improvement without misrepresentation.</td><td>Record with owner and due condition; promote if it affects teaching or safety of conclusions.</td></tr>\n </tbody></table></div>\n <p><strong>R00 dispositions:</strong> <span class=\"audit-inline\">HOLD_BLOCKER</span>, <span class=\"audit-inline\">REQUEST_CHANGES</span>, <span class=\"audit-inline\">TECHNICAL_PASS_PENDING_ACADEMIC</span>. An independent R01 receipt has its own scoped decision and cannot be created by the author or R00 impersonation. A reviewer should never suppress uncertainty to get a green badge.</p>\n <div class=\"audit-rule failure\"><strong>Stop escalation:</strong> a P0 holds the affected batch and triggers full same-family inspection; repeated P1 failures require remediation and a fresh bounded demonstration before continued production. All test failures/warnings and new D4 proofs receive targeted review. \u201cAll tests pass\u201d cannot override one incorrect scientific law.</div>\n</section>\n<section class=\"audit-section\" id=\"receipt\">\n <h2>11 \u00b7 Copy-ready exact-head R00 review return</h2>\n <p>Auditor receipts must be written and stored under reviewer-owned authority. Use the full <a href=\"../docs/agent-entry/quality-gate-r2/REVIEWER_AND_GOLDEN_TEMPLATES.md\">R00/R01/Owner/Batch forms</a>; this shortened version shows the minimum factual return. In reviewer-only mode, submit findings as an auditable PR comment or review receipt, not as a stealth code patch.</p>\n <div class=\"audit-code\">REVIEW TASK / REVIEWER ROLE / EXPOSURE STATUS:\nREPO / PR / EXACT HEAD / BASE SHA:\nAUTHOR WORKPACK / TOPIC / SUBTOPIC / ITEM UIDs:\nPINNED C01\u2013C08 / QRT / BLUEPRINT / ADAPTER / GOLDEN:\nCHANGED FILES / UNAUTHORIZED COLLISIONS:\nAUTHOR PACKET PATH + BYTE SHA / VERIFIER FINDINGS:\nINDEPENDENT SCIENCE DERIVATION / UNIT + LIMIT CHECK:\nCORE1A ACTUAL TEACHING / DIAGRAM / MISCONCEPTION:\nCORE1B ANCHOR W vs FRESH W / MAIN + INSTANCE / HINTS:\nCORE2 STEM / FIGURE / KEY / SOURCE ROLE / STATUS:\nB1\u2013B7 FINDINGS (R01 only for independent academic verdict):\nFULL PYTHON / HTTP CHROMIUM JOBS / EXACT SOURCE HEAD:\nFAULT INJECTIONS / COMMANDS / OBSERVED REJECTIONS:\nP0/P1/P2 FINDINGS \u2014 FILE:LINE / REPRO / REQUIRED FIX:\nQUESTION-LEVEL DENOMINATORS / UNREVIEWED ITEMS:\nR00 DECISION: HOLD_BLOCKER | REQUEST_CHANGES |\n              TECHNICAL_PASS_PENDING_ACADEMIC\nR01 ACADEMIC FINDING: SEPARATE RECEIPT / HOLD\nOWNER GOLDEN APPROVAL: NOT ASSUMED\nMERGE / RELEASE STATUS: NOT AUTOMATIC\nNO ACADEMIC APPROVAL INFERRED FROM SOFTWARE PASS.</div>\n <div class=\"audit-rule warning\">The R2 packet template is intentionally incomplete; its placeholder text must fail the checker. An auditor's duty is to review the actual file and log, not accept the author's claim that a form was filled. If a source or browser state could not be inspected, record <strong>NOT_OBSERVED</strong> and keep the corresponding scope HOLD.</div>\n</section>\n<section class=\"audit-section\" id=\"golden\">\n <h2>12 \u00b7 One-time Golden Sample, then delegated risk-based batches</h2>\n <ol class=\"audit-steps\">\n  <li><strong>Select one representative exemplar.</strong> Complete Core2 + substantial scientific Core1A + genuinely fresh protected Core1B, with all eight negative-test families and full source/figure/science witnesses.</li>\n  <li><strong>Audit it independently.</strong> R00 tests bytes/code/browser; a separate eligible R01 cold-solves and examines cognitive, science and B1\u2013B7. The Owner then accepts the <strong>exact Golden standard once</strong>, not question by question.</li>\n  <li><strong>Activate policy explicitly.</strong> Pin Golden SHA and Owner receipt; configure real GitHub required status checks, protected reviewer-owned receipt paths and CODEOWNERS. The policy file alone does not enforce permissions.</li>\n  <li><strong>Delegate continuing batches.</strong> Require an evidence packet for every new/changed item; independently review a reproducible reviewer-selected sample of <strong>at least 20% and one per topic per batch</strong> (proposed policy), with 100% targeted inspection for new laws, D4 proofs, key disputes, source contradictions and defects.</li>\n  <li><strong>Escalate by evidence.</strong> A P0 holds the affected batch; review 100% of the defect family. Report individually reviewed versus accepted-by-delegated-policy versus not-reviewed counts separately.</li>\n </ol>\n <div class=\"audit-rule\"><strong>No repeated Owner approval for routine questions.</strong> Owner approves the one representative Golden Sample standard once, not every subsequent question. Further Owner intervention is reserved for material changes to the standard and exceptional disputes requiring Owner authority. This risk-sampling policy is a proposed production contract until actually activated.</div>\n</section>\n<section class=\"audit-section\" id=\"references\">\n <h2>13 \u00b7 Source of truth and reading order</h2>\n <div class=\"audit-links\">\n  <a href=\"core1ab-agent-guide.html\">Core1A/B Agent Field Guide</a>\n  <a href=\"core2-source-to-learning-pipeline.html\">Core2-Led Source-to-Learning Pipeline</a>\n  <a href=\"guidebook.html\">Architecture Guidebook</a>\n  <a href=\"../docs/agent-entry/07-independent-review.md\">Independent reviewer source-only entry</a>\n  <a href=\"../docs/agent-entry/quality-gate-r2/AUTHORING_QUALITY_CONTRACT_R2.md\">R2 Quality Contract</a>\n  <a href=\"../docs/agent-entry/quality-gate-r2/REVIEWER_AND_GOLDEN_TEMPLATES.md\">Reviewer and Golden templates</a>\n  <a href=\"../docs/agent-entry/quality-gate-r2/evidence-packet.schema.json\">Evidence Packet Schema</a>\n  <a href=\"../docs/agent-entry/quality-gate-r2/verify_evidence_packet.py\">Evidence Validator</a>\n  <a href=\"../docs/agent-entry/quality-gate-r2/quality-policy.v1.json\">Current Policy State</a>\n </div>\n <p><strong>Reading order:</strong> reviewer assignment and exposure declaration \u2192 governing source-only task intake (if blind) \u2192 exact author packet and native sources \u2192 independent scientific derivation \u2192 Core1A/B/Core2 learner-page audit \u2192 adversarial browser/software tests \u2192 formal R00 or R01 return. For source-only blind review, avoid author-exposed solved examples before the first independent attempt.</p>\n <p class=\"audit-foot\">This page documents auditing practice and the current pilot contract. It cannot appoint independent reviewers, grant release authority, certify an examination question, or guarantee that every future lesson is high quality.</p>\n</section>\n</div>\n</div>",
  "manifesto": "<article class=\"field-section\" id=\"manifesto-principles\">\n  <h2>Grade9 Engineering & Curriculum Architecture Manifesto</h2>\n  <aside class=\"callout\">\n    <strong>Authoring Charter & Invariants:</strong> Foundational principles governing dual-route learning, cognitive demand, and immutable evidence bounds across Physics, Mathematics, and Chemistry.\n  </aside>\n\n  <h3>Pillar I \u00b7 Truthful Exactness & Dual-Source Immutability</h3>\n  <p>Never invent scientific truths, examination keys, historical figures, or learner performance records. Dual migration sources (Grade9v3.5 and Grade9v4.1) remain strictly immutable and read-only. Missing inputs must fail closed with an explicit <code>HOLD</code> rather than synthetic placeholders or fabricated solutions.</p>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr><th>Pillar</th><th>Guaranteed Invariant</th><th>Falsifier / Anti-Pattern</th></tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong>Truthful Exactness</strong></td>\n          <td>Every question stem, diagram, option set, and mathematical warrant is bound to a verified source fingerprint.</td>\n          <td>Inventing source IDs, altering numbers to simplify calculations, or drawing synthetic diagrams without attribution.</td>\n        </tr>\n        <tr>\n          <td><strong>Dual-Source Immutability</strong></td>\n          <td>Source trees are read-only; all migrations are recorded with forward commit history and cryptographic digests.</td>\n          <td>Rebasing, squashing, force-pushing, or mutating historic commits.</td>\n        </tr>\n        <tr>\n          <td><strong>Answer-Key Isolation (Fault N09)</strong></td>\n          <td>Examiner keys, private review notes, and author rationales are strictly excluded from client application bundles.</td>\n          <td>Embedding raw answer keys in public JavaScript objects or JSON fixtures.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3>Pillar II \u00b7 Cognitive Demand & QRT Architecture</h3>\n  <p>Intrinsic difficulty is an objective property of the shortest valid reasoning path connecting problem premises to decisive conclusions. Grade9 models cognitive demand across <strong>seven fundamental operations</strong>:</p>\n  <ul>\n    <li><strong>RETRIEVE (OP-1):</strong> Direct recall or inspection of a stated fact, formula, or figure feature.</li>\n    <li><strong>APPLY (OP-2):</strong> Standard procedural substitution into a single known relationship.</li>\n    <li><strong>INFER (OP-3):</strong> Logical deduction bridging two adjacent physical or mathematical states.</li>\n    <li><strong>CALCULATE (OP-4):</strong> Multi-step symbolic or numerical evaluation under strict constraints.</li>\n    <li><strong>REPRESENT (OP-5):</strong> Translating verbal descriptions into coordinate systems, free-body diagrams, or circuit topologies.</li>\n    <li><strong>TRANSFER (OP-6):</strong> Applying a known principle to an unfamiliar, structurally transformed context.</li>\n    <li><strong>PROVE (OP-7):</strong> Systematic non-circular deduction establishing general invariants or counterexamples.</li>\n  </ul>\n\n  <h3>Pillar III \u00b7 Dual-Route Pedagogical Architecture</h3>\n  <p>Direct practice without conceptual construction leads to rote memorization; conceptual exposition without deliberate practice leads to fragile intuition. Grade9 synthesizes both through two coordinated routes:</p>\n  <div class=\"route-grid\">\n    <div class=\"route\">\n      <h4>Route A \u00b7 Direct Examination Route (Core 2A / 2B)</h4>\n      <p>Preserves the authentic question in its original examination complexity. Scaffolding is requested on-demand through structured rungs (H1 Orientation &rarr; H2 Crux Breakdown &rarr; H3 Full Reconstruction) without spoiling the commitment step.</p>\n    </div>\n    <div class=\"route\">\n      <h4>Route B \u00b7 Foundational Teaching Route (Core 1A / 1B)</h4>\n      <p>Builds the decisive intellectual move (Construction W) through phenomenological inquiry, physical warrants, active recall, misconception diagnosis, and fresh isomorphic reconstruction.</p>\n    </div>\n  </div>\n\n  <h3>Pillar IV \u00b7 12.7\" Tablet Ergonomics & Visual Direct Manipulation</h3>\n  <p>Grade9 learning applications are engineered from first principles for 12.7-inch tablet ergonomics. Interactive touch targets must respect <code>HIT_TARGET_MIN_PX &ge; 48px</code> and <code>HIT_TARGET_PRIMARY_PX &ge; 56px</code>. Layouts must provide zero horizontal overflow across 1600&times;1000, 1000&times;1600, 1280&times;800, and 800&times;1280 viewports with legible base typography scaling up to 30px with crisp MathML.</p>\n\n  <h3>Pillar V \u00b7 Dual-Engine Verification & Zero Escape</h3>\n  <p>Software correctness is validated through automated dual-engine audits: Python unit tests and headless Playwright viewport audits. Bundles must strictly enforce the <strong>Zero Dist Bloat Invariant</strong>, ensuring all assets compile into structured modules with zero loose artifacts.</p>\n</article>",
  "pipeline": "<article class=\"field-section\" id=\"pipeline-architecture\">\n  <h2>Curriculum Generation & Authoring Pipeline Architecture</h2>\n  <aside class=\"callout\">\n    <strong>The 8-Stage Toolchain:</strong> End-to-end transformation workflow from authentic source intake to interactive tablet workbenches.\n  </aside>\n\n  <div class=\"flowchart\">\n    <pre>\n[Stage 1: Intake & Custody]      &rarr; Verify syllabus, exam identity, figures, and rights.\n           &darr;\n[Stage 2: Shortest Valid Route]  &rarr; Independent solver isolates decisive move W.\n           &darr;\n[Stage 3: Demand Scoring (QRT)]  &rarr; Score 7 operations and 5-factor rubric bounds [0..2].\n           &darr;\n[Stage 4: Blueprint Binding]     &rarr; Dynamic crux binding and commit-first inert derivations.\n           &darr;\n[Stage 5: Dual Construction]     &rarr; Core 1A textbook teaching + Core 1B fresh reconstruction.\n           &darr;\n[Stage 6: Multi-Engine Package]  &rarr; Single-bundle responsive HTML5 component compiler.\n           &darr;\n[Stage 7: Tablet Viewport Audit] &rarr; Headless Playwright multi-viewport touch ergonomics.\n           &darr;\n[Stage 8: Evidence Packets]      &rarr; B1&ndash;B7 correspondence witnesses &amp; independent review.\n    </pre>\n  </div>\n\n  <h3>Detailed Stage Specifications</h3>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr><th>Stage</th><th>Input Artifact</th><th>Transformation</th><th>Output Gate</th></tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong>01 \u00b7 Intake</strong></td>\n          <td>Raw exam paper PDF or textbook scan</td>\n          <td>Fingerprinting, OCR extraction, diagram cropping</td>\n          <td><code>source_receipt.json</code> (SHA-256 bound)</td>\n        </tr>\n        <tr>\n          <td><strong>02 \u00b7 Route</strong></td>\n          <td>Stated problem prompt + figures</td>\n          <td>Independent analytical derivation without solution key</td>\n          <td>Minimal reasoning path &amp; decisive construction W</td>\n        </tr>\n        <tr>\n          <td><strong>03 \u00b7 QRT</strong></td>\n          <td>Minimal reasoning path</td>\n          <td>Five-factor scoring: Novelty, Abstraction, Coupling, Execution, Formulation</td>\n          <td>Validated QRT Score (D1&ndash;D4 Band)</td>\n        </tr>\n        <tr>\n          <td><strong>04 \u00b7 Binding</strong></td>\n          <td>Subject Blueprint + Topic Adapter</td>\n          <td>Crux mapping, prerequisite graph, inert derivation binding</td>\n          <td>Qualified Lesson Specification</td>\n        </tr>\n        <tr>\n          <td><strong>05 \u00b7 Construction</strong></td>\n          <td>Lesson Specification</td>\n          <td>Authoring Core 1A textbook exposition and Core 1B six-stage journey</td>\n          <td>Interactive learning modules with misconception repair</td>\n        </tr>\n        <tr>\n          <td><strong>06 \u00b7 Packaging</strong></td>\n          <td>TypeScript source + SVG representations</td>\n          <td>Vite bundling, zero dist bloat assertion, type safety check</td>\n          <td>Production application bundle</td>\n        </tr>\n        <tr>\n          <td><strong>07 \u00b7 Viewport QA</strong></td>\n          <td>Production application bundle</td>\n          <td>Automated Playwright multi-viewport audit at 7 standard resolutions</td>\n          <td>Zero horizontal overflow &amp; &ge;48px touch targets</td>\n        </tr>\n        <tr>\n          <td><strong>08 \u00b7 Evidence</strong></td>\n          <td>All generated artifacts &amp; test receipts</td>\n          <td>Cryptographic verification of B1&ndash;B7 correspondence gates</td>\n          <td>Independent Review Packet (R00/R01 signed)</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n</article>",
  "roadmap": "<article class=\"field-section\" id=\"roadmap-architecture\">\n  <h2>Architecture & Migration Multi-Wave Roadmap</h2>\n  <aside class=\"callout\">\n    <strong>Progression across 19 Engineering Waves:</strong> Stepwise delivery achieving full parity, verifiable closure, and zero architectural debt.\n  </aside>\n\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr><th>Wave</th><th>Scope &amp; Deliverables</th><th>Parity Metric</th><th>Status</th></tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong>Waves 1&ndash;3</strong></td>\n          <td>Architectural Shell, Core Runtime, and Base Typography</td>\n          <td>100% Foundation Parity</td>\n          <td><span class=\"check\">&check; COMPLETED</span></td>\n        </tr>\n        <tr>\n          <td><strong>Waves 4&ndash;7</strong></td>\n          <td>Universal Core 1A/1B &amp; Core 2A/2B Modules, Six-Core Runtime</td>\n          <td>100% Core Engine Parity</td>\n          <td><span class=\"check\">&check; COMPLETED</span></td>\n        </tr>\n        <tr>\n          <td><strong>Waves 8&ndash;10</strong></td>\n          <td>Port-First Accounting Closure, Standalone Interactive Labs, Architecture Hub</td>\n          <td>100% Structural Parity</td>\n          <td><span class=\"check\">&check; COMPLETED</span></td>\n        </tr>\n        <tr>\n          <td><strong>Waves 11&ndash;13</strong></td>\n          <td>NSEJS Physics 12-Chapter Syllabus &amp; Chemistry 14-Topic Adapters</td>\n          <td>96.4% Curricular Parity</td>\n          <td><span class=\"check\">&check; COMPLETED</span></td>\n        </tr>\n        <tr>\n          <td><strong>Waves 14&ndash;16</strong></td>\n          <td>Core 2 Question Bank, Curricular Subtopic Adapters, Standalone Labs</td>\n          <td>98.2% Question Bank Parity</td>\n          <td><span class=\"check\">&check; COMPLETED</span></td>\n        </tr>\n        <tr>\n          <td><strong>Wave 17</strong></td>\n          <td>Curricular Mirroring, Architecture Contexts, and Navigation Parity</td>\n          <td>86.0% Reconciled Parity</td>\n          <td><span class=\"check\">&check; COMPLETED</span></td>\n        </tr>\n        <tr>\n          <td><strong>Wave 18</strong></td>\n          <td>Developer Collateral Reconciliation (156 Developer &amp; Benchmark Artifacts)</td>\n          <td>93.8% Verified Parity</td>\n          <td><span class=\"check\">&check; COMPLETED</span></td>\n        </tr>\n        <tr>\n          <td><strong>Wave 19</strong></td>\n          <td>Universal Search Dialog (Ctrl+K), Full Offline Ingestion, &amp; Remote Docs Bundling</td>\n          <td>100% Target Parity</td>\n          <td><span class=\"check\">&check; ACTIVE EXECUTION</span></td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n</article>",
  "overview": "<section class=\"panel\" id=\"core1ab-agent-authoring-guide\"><span class=\"tag\">New agent \u00b7 Core1A / Core1B</span><h2>Complete Core1A / Core1B Agent Authoring Field Guide</h2><p>A subject-independent, operational playbook: research the syllabus and actual questions, find the decisive construction, score QRT, bind Blueprint and topic adapter, write a continuous textbook, design fresh protected tasks and MAIN cycles, validate exact routes and hand off for independent review. Includes worked mini-cases, failure checks and reusable workpack templates.</p><div class=\"linklist\"><a class=\"button\" href=\"core1ab-agent-guide.html\">Open the complete authoring field guide \u2192</a><a href=\"guidebook.html\">Read the architecture guidebook</a><a href=\"../docs/agent-entry/07-independent-review.md\">Independent reviewer source-only route</a></div><p><strong>Author-facing:</strong> does not select a subject, qualify a task or grant release.</p></section><section class=\"panel\" style=\"background:#eaf7f1;border-color:#b7dfcd\"><span class=\"tag\">Production readiness</span><h2 style=\"margin:12px 0\">\u2705 Production checklist \u00b7 Core2 tablet QA</h2><p>Before each Core2 release, verify the direct full-page Question Bank on a 12.7-inch tablet in portrait and landscape. Check question navigation, source labels, hints and no iframe or horizontal overflow. Oracle Core1A coordination and academic approval are separate.</p><div class=\"linklist\"><a href=\"production-checklist.html\">Open Production Checklist</a><a href=\"../docs/agent-entry/concept-report-v4.html#production-checklist\">Concept \u2192 checklist</a></div></section>\n<section class=\"panel\"><span class=\"tag\">Start with the guidebook</span><h2 style=\"font-size:1.67rem;margin-top:13px\">Subtopic \u2192 Demands \u2192 QRT \u2192 Blueprint + Adapter \u2192 Core1A</h2><p>A practical illustrated methodology with both source routes, decisive-route analysis, five-factor demand, exact task joins, B1\u2013B7 witnesses, attempt protection, scientific checks, blind-review hygiene and release governance. Includes actual repository references and explicit unresolved requirements.</p><div class=\"linklist\"><a class=\"button\" href=\"guidebook.html\">Read the Architecture Guidebook \u2192</a><a class=\"button secondary\" href=\"core2-source-to-learning-pipeline.html\">Core2-Led Source-to-Learning Pipeline &amp; Benchmarks \u2192</a><a class=\"button secondary\" href=\"review-guide.html\">Independent Audit Field Guide \u2192</a><a href=\"../docs/agent-entry/00-required-reading.md\">Original required-reading map</a></div></section>\n<div class=\"status\"><strong>Authority boundary</strong><p>These links navigate existing documentation and technical previews. They do not create approved QRT decisions, authorize draft Blueprint/adapter selection or release native lessons. Independent reviewers must take the source-only route, not an author-exposed architecture page containing prior outcomes.</p></div>\n<h2 class=\"section-title\">Explore the learning blueprint</h2><div class=\"cards\">\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\ud83d\udee1\ufe0f</div><small>01 \u00b7 GOVERNANCE</small><h3>Scope & authority</h3><p>Three-subject product boundaries, Owner instructions, actual implementation status and historical checkpoint.</p><div class=\"linklist\"><a href=\"../docs/product-scope.md\">Product scope</a><a href=\"../AGENTS.md\">Repo rules</a><a href=\"../docs/implementation-status.md\">Implementation status</a><a href=\"https://github.com/reallakshman19/Grade9v4.0/issues/1\">Master issue</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\ud83d\udcc2</div><small>02 \u00b7 SOURCE</small><h3>Intake & custody</h3><p>Separate question-paper, textbook, diagram and source-exposition evidence with exact locators and copyright controls.</p><div class=\"linklist\"><a href=\"../docs/agent-entry/01-source-intake.md\">Source protocol</a><a href=\"../docs/agent-entry/CURRENT_PATHS.json\">Current paths</a><a href=\"../docs/agent-entry/ARTIFACT_REGISTER.json\">Artifact register</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\u270d\ufe0f</div><small>03 \u00b7 DEMANDS</small><h3>SL1, P1 and SL2</h3><p>Source identity, optional first-attempt evidence, decisive move, cognitive candidate and intrinsic-demand factors.</p><div class=\"linklist\"><a href=\"../docs/agent-entry/02-skills.md\">Native Smart Skills</a><a href=\"../docs/smart-skills-integration.md\">SL1/SL2 integration</a><a href=\"../docs/agent-entry/fixtures.html\">Fixture comparisons</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\ud83e\udde0</div><small>04 \u00b7 QRT</small><h3>Independent adjudication</h3><p>Seven operations, task-specific demand, shortest valid solution and distinct direct-exam/bridge roles.</p><div class=\"linklist\"><a href=\"../docs/agent-entry/03-blueprint-adapters.md\">QRT + adapter entry</a><a href=\"../docs/agent-entry/07-independent-review.md\">Source-only review</a><a href=\"../preview/batches/b07-preflight.html\">Author-exposed technical preflight</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\ud83e\udde9</div><small>05 \u00b7 SUBJECT</small><h3>Blueprint & topic adapter</h3><p>Physics D3/D4 draft, selected topic bindings and qualified scientific warrants; Mathematics/Chemistry need their own versions.</p><div class=\"linklist\"><a href=\"../templates/physics-blueprint/physics-blueprint.D3-D4.json\">Physics Blueprint draft</a><a href=\"../schemas/v2/subject-intake.schema.json\">Candidate multi-subject v2</a><a href=\"../docs/agent-entry/03-blueprint-adapters.md\">Version/adapter governance</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\ud83d\udca1</div><small>06 \u00b7 CORE</small><h3>Construct, reconstruct, protect</h3><p>Core2 exact-question route, Core1A sufficient teaching, Core1B fresh reasoning and B1\u2013B7 construction correspondence.</p><div class=\"linklist\"><a href=\"../docs/agent-entry/04-output.md\">Core output entry</a><a href=\"../docs/agent-entry/CURRENT_CONCEPT_COMPANION.md\">Current concept companion</a><a href=\"../docs/agent-entry/concept-report-v4.html\">Concept report + addendum</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\u2705</div><small>07 \u00b7 CHECKS</small><h3>QA, provenance & publication</h3><p>What tests can prove, what requires independent reviewers, separate authorizations and fail-closed decisions.</p><div class=\"linklist\"><a href=\"../docs/agent-entry/05-qa-publication.md\">QA/publication entry</a><a href=\"../docs/agent-entry/OPEN_GAPS.md\">Open gaps</a><a href=\"../docs/agent-entry/fixtures.html\">Positive and negative controls</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\ud83d\uddfa\ufe0f</div><small>08 \u00b7 CONTEXT</small><h3>Onboarding & current state</h3><p>Actual order of reading, working paths, the dated checkpoint and dependencies without overstating their authority.</p><div class=\"linklist\"><a href=\"../docs/agent-entry/index.html\">Agent onboarding</a><a href=\"../docs/agent-entry/CURRENT_WORKFLOW.json\">Current workflow map</a><a href=\"../CURRENT_CHECKPOINT.md\">Dated checkpoint</a></div></article>\n<article class=\"card\"><div class=\"tile-icon\" aria-hidden=\"true\">\ud83d\udd2c</div><small>09 \u00b7 EVIDENCE</small><h3>WPE review examples</h3><p>Read-only technical construction candidates and QRT blockers, not a bank of admitted examination tasks.</p><div class=\"linklist\"><a href=\"../preview/batches/reader.html\">Cumulative WPE reader</a><a href=\"../preview/batches/b06-evidence-map.json\">Source-to-Core1A mapping</a><a href=\"../preview/batches/b08-source-gates.json\">Exam source-gate blockers</a></div></article>\n</div>\n<section class=\"panel\"><h2>Suggested reading sequence (not the independent-review packet)</h2><div class=\"steps\"><div class=\"step\"><b>1. Scope</b><span>Three subjects, correct Owner/Shared role.</span></div><div class=\"step\"><b>2. Source</b><span>Exact question or passage, rights and custody.</span></div><div class=\"step\"><b>3. Requirement</b><span>SL1, SL2 and the parallel source claim route.</span></div><div class=\"step\"><b>4. Review</b><span>Independent QRT, qualified law and topic adapter.</span></div><div class=\"step\"><b>5. Learning</b><span>Core2/Core1A/B, B1\u2013B7 and release.</span></div></div><div class=\"linklist\"><a href=\"core1ab-agent-guide.html\">Core1A / Core1B authoring field guide</a><a href=\"guidebook.html\">Open complete step-by-step guidebook</a><a href=\"core2-source-to-learning-pipeline.html\">Authoring Core2-Led Source-to-Learning Pipeline &amp; Benchmarks</a><a href=\"review-guide.html\">Independent Audit Field Guide</a><a href=\"guidebook-sources.json\">Guidebook source register (JSON)</a></div></section>",
  "benchmarks": "<article class=\"field-section\" id=\"benchmarks-specimen\">\n  <h2>Quality Calibration Specimens & Tablet Benchmarks</h2>\n  <aside class=\"callout\">\n    <strong>Tablet Readiness & Verification Standards:</strong> 22 historical calibration specimens and 12.7\" responsive geometry criteria.\n  </aside>\n\n  <h3>Standard Tablet Viewport Matrix</h3>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr><th>Display Mode</th><th>CSS Resolution</th><th>Device Aspect Ratio</th><th>Acceptance Criterion</th></tr>\n      </thead>\n      <tbody>\n        <tr><td><strong>Landscape High-DPI</strong></td><td>1600 &times; 1000</td><td>16:10</td><td>Full dual-pane view, side-by-side navigator and reader</td></tr>\n        <tr><td><strong>Portrait High-DPI</strong></td><td>1000 &times; 1600</td><td>10:16</td><td>Single-column stacked view, sticky jump navigation</td></tr>\n        <tr><td><strong>Standard Landscape</strong></td><td>1280 &times; 800</td><td>16:10</td><td>Zero horizontal overflow, legible MathML &ge; 16px</td></tr>\n        <tr><td><strong>Standard Portrait</strong></td><td>800 &times; 1280</td><td>10:16</td><td>All touch targets &ge; 48px, compact controls</td></tr>\n        <tr><td><strong>Mobile Fallback</strong></td><td>390 &times; 844</td><td>19.5:9</td><td>Accessible single-column card layout, dialog sheets</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3>Rendering Performance Criteria</h3>\n  <ul>\n    <li><strong>Sub-200ms Initial DOM Render:</strong> All components mount within 200 milliseconds of route change.</li>\n    <li><strong>Zero Cumulative Layout Shift (CLS &lt; 0.01):</strong> Dynamic math and diagram loading preserve structural dimensions.</li>\n    <li><strong>Offline Durability:</strong> Progress state, question attempts, and notes persist locally via WebStorage across app reloads.</li>\n  </ul>\n</article>",
  "workspace-audit": "<h1>WPE Core2: academic review</h1><p><b>PARTIAL \u00b7 0 admissions \u00b7 product unchanged</b></p><section class=\"correction\"><h2>Correction: paper and key agree</h2><p>The Oracle misread a small superscript. Original paper/crop both print x\u2080\u00b2. The earlier source-conflict and silent-correction claims are withdrawn. The independent reviewer\u2019s sealed reading was correct. WEP07-03 answers: a,b,c,d.</p><a href=\"CORRECTION_NOTICE.md\">Correction and scope</a> \u00b7 <a href=\"SUPERSESSION_REGISTER.json\">Historical records superseded</a><p>Actual paper enlargement:</p><img src=\"reviewer-return/option-c-from-actual-PDF.png\" alt=\"Actual option c shows square root of alpha over two m x nought squared\"></section><section><h2>Coverage reconciliation</h2><p>Target21 \u00b7 historical14 nominations +7 vacancies \u00b7 now4 reviewed D2 +10 unreviewed nominations +7 original vacancies. <b>11 target slots currently lack a supported D3/D4 candidate.</b></p><p>Eight textbook questions and the synthetic control stay separately counted.</p></section><section><h2>Independent exact-task findings</h2><div style=\"overflow:auto\"><table><thead><tr><th>Task</th><th>Answer</th><th>Operation</th><th>Factors</th><th>Band</th><th>Limits</th></tr></thead><tbody><tr><td>EX-M62</td><td>D</td><td>APPLY</td><td>[1, 1, 1, 1, 0]</td><td>4/D2</td><td>Net translational power/no-loss idealization; shorter MCQ derivative check. Official paper/key join open.</td></tr><tr><td>EX-M73</td><td>C</td><td>APPLY</td><td>[1, 1, 1, 0, 0]</td><td>3/D2</td><td>Ideal/minimum lifting work via centre of mass. Arbitrary dissipative total-agent work is not determined. Official join open.</td></tr><tr><td>EX-M101</td><td>A</td><td>APPLY</td><td>[1, 1, 1, 0, 1]</td><td>4/D2</td><td>Distinguish fixed-force from fixed-extension spring work. This is not cut-spring MAIN. Official join open.</td></tr><tr><td>WEP07-03</td><td>a,b,c,d</td><td>APPLY</td><td>[1, 0, 2, 1, 1]</td><td>5/D2</td><td>NSEP2025/code61/Q57; actual paper, solution and final key agree. Source-conflict claim withdrawn.</td></tr></tbody></table></div></section><section><h2>Evidence and next steps</h2><p><a href=\"RECONCILIATION_REPORT.md\">Full reconciliation</a> \u00b7 <a href=\"reviewer-return/FINAL_REVIEW.md\">Independent review</a> \u00b7 <a href=\"reviewer-return/FIRST_PASS.json\">Sealed first pass</a> \u00b7 <a href=\"reviewer-return/FINAL_REVIEW.json\">Derivations and exposure</a> \u00b7 <a href=\"RECONCILED_STATUS.json\">Structured status</a></p><p>Owner reviews findings. Further source work, native examination conversion and distinct technical QA remain. No new routine begins from this report. Core1A awaits Core2 approval; Core1B awaits Core1A approval. D3.1 PAUSED.</p><small>Documentation view; no browser/layout QA claimed. Protected sources remain local/private.</small></section></html>",
  "evidence-packets": "<article class=\"field-section\" id=\"evidence-packets-spec\">\n  <h2>Historical Review Evidence Packets & Verification Checkers</h2>\n  <aside class=\"callout\">\n    <strong>R2 Evidence Gate Standard:</strong> Cryptographic verification of B1&ndash;B7 correspondence witnesses and fail-closed falsifiers.\n  </aside>\n\n  <h3>The B1&ndash;B7 Evidence Correspondence Matrix</h3>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr><th>Witness Gate</th><th>Evidence Obligation</th><th>Automated Falsifier Check</th></tr>\n      </thead>\n      <tbody>\n        <tr><td><strong>B1 \u00b7 Source Integrity</strong></td><td>Exact SHA-256 match of original paper or textbook scan</td><td><code>HASH_MISMATCH</code></td></tr>\n        <tr><td><strong>B2 \u00b7 Independent Route</strong></td><td>Minimal derivation without author or answer-key bias</td><td><code>SOLVER_CONTRADICTION</code></td></tr>\n        <tr><td><strong>B3 \u00b7 Core 1A Sufficiency</strong></td><td>Textbook exposition completely teaches construction W</td><td><code>INSUFFICIENT_W_TEACHING</code></td></tr>\n        <tr><td><strong>B4 \u00b7 Core 1B Freshness</strong></td><td>Task is structurally transformed, not a numeric clone</td><td><code>NUMERIC_CLONE_DETECTED</code></td></tr>\n        <tr><td><strong>B5 \u00b7 Runtime Protection</strong></td><td>Attempt committed before revealing hints or full solution</td><td><code>HINT_LEAK_PRECOMMIT</code></td></tr>\n        <tr><td><strong>B6 \u00b7 Scientific Warrants</strong></td><td>Units, dimensional consistency, and limiting cases verified</td><td><code>WRONG_DIMENSION_OR_LIMIT</code></td></tr>\n        <tr><td><strong>B7 \u00b7 Independent Audit</strong></td><td>Separated R00 technical and R01 academic review receipts</td><td><code>UNRATIFIED_PROMOTION</code></td></tr>\n      </tbody>\n    </table>\n  </div>\n</article>",
  "preview-batches": "<aside class=\"banner-disclosure\" role=\"note\" aria-label=\"Learning preview status\">\n            <div class=\"preview-note-line\"><span class=\"preview-pill\">Preview</span> <strong>Physics is a technical pilot. Mathematics and Chemistry chapters are not yet approved or released.</strong></div>\n            <details><summary>Why is this marked as a preview?</summary><p>Academic admissions: <strong>0</strong>. Original exam keys, figure rights, scientific review, topic-adapter qualification and learner-release approval remain pending where applicable. Successful website tests do not provide academic approval.</p></details>\n        </aside>\n\n        <section class=\"card\">\n            <h2>Our three subjects</h2>\n            <p>\n                Grade9 v4.0 is engineered for three equal core subjects: <strong>Physics, Mathematics, and Chemistry</strong>. Work-Power-Energy (WPE) serves exclusively as the initial technical exemplar within Physics.\n            </p>\n            <div class=\"table-responsive\">\n                <table>\n                    <thead>\n                        <tr>\n                            <th>Subject Domain</th>\n                            <th>Current stage</th>\n                            <th>Release Gate</th>\n                            <th>Topics being explored</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr>\n                            <td><strong>Physics</strong></td>\n                            <td><span class=\"badge badge-active\">Active Pilot</span></td>\n                            <td>Technical Exemplar Only (0/3 Admitted)</td>\n                            <td>Work, Kinetic &amp; Potential Energy, Conservative Wells, Turning Points</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Mathematics</strong></td>\n                            <td><span class=\"badge badge-hold\">Draft / Hold</span></td>\n                            <td>Hold: Subject Blueprint Pending</td>\n                            <td>Polynomial Invariants, Vieta's Relations, Functional Equations</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Chemistry</strong></td>\n                            <td><span class=\"badge badge-hold\">Draft / Hold</span></td>\n                            <td>Hold: Subject Blueprint Pending</td>\n                            <td>Chemical Equilibrium, Mass Action Kinetics, Thermochemistry</td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n        </section>\n\n        <section class=\"card\">\n            <h2>How we check lessons (B1\u2013B7)</h2>\n            <div class=\"table-responsive\">\n                <table>\n                    <thead>\n                        <tr>\n                            <th>Obligation</th>\n                            <th>Title &amp; Focus</th>\n                            <th>Alpha Verification Status</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr>\n                            <td><strong>B1</strong></td>\n                            <td>Blueprint Alignment</td>\n                            <td>Mapped to canonical cognitive operations (RETRIEVE, EXPLAIN, APPLY, MODEL, REPRESENT, SYNTHESIZE, JUSTIFY)</td>\n                        </tr>\n                        <tr>\n                            <td><strong>B2</strong></td>\n                            <td>Independent Academic Review</td>\n                            <td>Fail-closed governance: human subject review mandatory before student deployment</td>\n                        </tr>\n                        <tr>\n                            <td><strong>B3</strong></td>\n                            <td>Multi-Engine Verification</td>\n                            <td>Numerical demonstration values checked; wider academic multi-engine review remains gated</td>\n                        </tr>\n                        <tr>\n                            <td><strong>B4</strong></td>\n                            <td>Cognitive Fidelity</td>\n                            <td>Attempt-length gate (not semantic grading), followed by optional explicit solution reveal</td>\n                        </tr>\n                        <tr>\n                            <td><strong>B5</strong></td>\n                            <td>Offline &amp; Relative Integrity</td>\n                            <td>Offline-capable static execution; project-subpath 404 links repaired for HTTP and file URLs</td>\n                        </tr>\n                        <tr>\n                            <td><strong>B6</strong></td>\n                            <td>Learner Privacy Safeguards</td>\n                            <td>Session flags and chosen option stored locally; no in-app telemetry; host may log access</td>\n                        </tr>\n                        <tr>\n                            <td><strong>B7</strong></td>\n                            <td>Authority Discipline</td>\n                            <td>Distinct publishing gates requiring explicit Owner authorization</td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n            <div class=\"nav-actions\">\n                <a href=\"index.html\" class=\"btn btn-primary\">Return to Portal Home &rarr;</a>\n            </div>\n        </section>\n\n        <footer>\n            Grade9 v4.0 \u00b7 Original learning preview \u00b7 Not an approved examination release\n        </footer>",
  "test-fixtures": "<article class=\"field-section\" id=\"test-fixtures-spec\">\n  <h2>Test Harness Fixtures & Browser Host Containers</h2>\n  <aside class=\"callout\">\n    <strong>Automated Quality Assurance:</strong> Dual-engine test suites executing headless Playwright and Node-native test runners.\n  </aside>\n\n  <h3>Suite Invariants & Coverage</h3>\n  <ul>\n    <li><strong>Smoke &amp; Dist Invariant (<code>smoke.spec.ts</code>):</strong> Enforces that <code>dist/</code> contains only <code>index.html</code> and bundled JavaScript modules under <code>./assets/</code> with zero loose HTML/JSON bloat.</li>\n    <li><strong>Universal Search Suite (<code>universal_search_modal.spec.ts</code>):</strong> Verifies full keyboard navigation (Ctrl+K, Esc, arrow keys, Enter), instant multi-token filtering, and four categorized tab views.</li>\n    <li><strong>Representation Suite (<code>representation.spec.ts</code>):</strong> Audits SVG vector assets, coordinate systems, and responsive viewport scaling.</li>\n    <li><strong>Shell Suite (<code>shell.spec.ts</code>):</strong> Validates root diagnostic shell contracts and interactive element boundaries.</li>\n  </ul>\n</article>",
  "developer-tools": "<article class=\"field-section\" id=\"developer-tools-spec\">\n  <h2>Developer Diagnostic Tools & Run Builders</h2>\n  <aside class=\"callout\">\n    <strong>Authoring Agent Tooling:</strong> Operational utilities for question indexing, asset verification, and pipeline execution.\n  </aside>\n\n  <h3>Integrated Developer Toolchain</h3>\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr><th>Tool</th><th>Path / Command</th><th>Operational Purpose</th></tr>\n      </thead>\n      <tbody>\n        <tr><td><strong>Run Builder</strong></td><td><code>tools/run-builder/index.html</code></td><td>Curriculum execution pipeline monitor and stage visualizer</td></tr>\n        <tr><td><strong>Question Indexer</strong></td><td><code>web/runtime/universal-search-index.ts</code></td><td>Automated 416-item search index compiler and metadata extractor</td></tr>\n        <tr><td><strong>QRT Calculator</strong></td><td><code>07-orchestration/check.py</code></td><td>Five-factor intrinsic demand scoring and band assignment</td></tr>\n        <tr><td><strong>Audit Runner</strong></td><td><code>npm run test:browser</code></td><td>Headless Playwright audit suite across all 12 key tablet surfaces</td></tr>\n      </tbody>\n    </table>\n  </div>\n</article>",
  "peer-review": "<article class=\"field-section\" id=\"peer-review-spec\">\n  <h2>Physics & Multi-Disciplinary Parity Review</h2>\n  <aside class=\"callout\">\n    <strong>Blind Review Protocols:</strong> Academic evaluation procedures maintaining strict separation between authoring and independent verification.\n  </aside>\n\n  <h3>Source-Only Review Protocol</h3>\n  <ol>\n    <li><strong>Blind Examination:</strong> The reviewer receives only the authentic problem stem and official diagram without seeing the author's proposed solution or pedagogical hints.</li>\n    <li><strong>Independent Derivation:</strong> The reviewer independently derives the solution and calculates the intrinsic demand across all five factors.</li>\n    <li><strong>Correspondence Audit:</strong> Author and reviewer derivations are compared. Any discrepancy in decisive construction W or answer key triggers immediate <code>HOLD</code>.</li>\n    <li><strong>Multi-Disciplinary Bounds:</strong> Physics warrants require dimensional analysis and limiting cases; Mathematics warrants require algebraic closure; Chemistry warrants require stoichiometry and redox balance.</li>\n  </ol>\n</article>",  "portable-workbenches": "<nav class=\"field-nav\" aria-label=\"Guide contents\">\n  <h2>Contents</h2>\n  <a href=\"#charter\">01 · Architectural charter &amp; DEC-A59</a>\n  <a href=\"#cognitive-state\">02 · Cognitive state transitions (S0 → R → S1)</a>\n  <a href=\"#fail-closed\">03 · The 15 fail-closed rejection invariants</a>\n  <a href=\"#kid-simulation\">04 · Kid-accessible visual simulations &amp; telemetry</a>\n  <a href=\"#ergonomics\">05 · Ergonomics, zero-iframe policy &amp; touch standards</a>\n  <a href=\"#golden-specimens\">06 · Golden specimens &amp; dual-engine validation</a>\n  <a href=\"#authoring-runbook\">07 · Operational authoring runbook for new STEM explorers</a>\n</nav>\n<article class=\"field-body\" id=\"guide-content\">\n  <section class=\"field-section\" id=\"charter\">\n    <h2>01 · Architectural charter &amp; DEC-A59 governance</h2>\n    <p>Declarative Portable Workbenches provide an interactive, stateful exploratory medium where learners manipulate declarative models to verify physical, mathematical, and chemical truths. Unlike monolithic black-box widgets or external iframes, every workbench is governed by <strong>DEC-A59-PORTABLE-COMPATIBILITY-01 (Workpack A64)</strong>: packages are 100% declarative, data-only JSON files executing under a fail-closed host adapter.</p>\n    <aside class=\"callout\"><strong>Governance Rule 13:</strong> No academic approval is inferred from software validation. Green automated CI guarantees structural and syntactic compliance, not student release approval. All packages default to <code>academic_admission: HOLD</code>.</aside>\n    <div class=\"table-wrap\">\n      <table>\n        <thead><tr><th>Seam</th><th>Canonical Value</th><th>Enforcement</th></tr></thead>\n        <tbody>\n          <tr><td>packageSchema</td><td><code>portable-workbench-package</code></td><td>Strict match; rejection on divergence</td></tr>\n          <tr><td>packageVersion</td><td><code>1.0.0</code></td><td>Strict semantic version pin</td></tr>\n          <tr><td>componentApiVersion</td><td><code>0.1.0</code></td><td>Strict component API handshake</td></tr>\n          <tr><td>transformationIrVersion</td><td><code>0.1.0</code></td><td>Strict transformation IR specification</td></tr>\n          <tr><td>adapterApiVersion</td><td><code>0.2.0</code></td><td>Strict declarative adapter contract</td></tr>\n          <tr><td>scenePackageVersion</td><td><code>1.0.0</code></td><td>Strict scene package version</td></tr>\n          <tr><td>declarativeAdapterId</td><td><code>declarative-transfer-v1</code></td><td>Pure declarative transformation runner</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section class=\"field-section\" id=\"cognitive-state\">\n    <h2>02 · Cognitive state transitions (S0 → R → S1)</h2>\n    <p>A workbench is modeled as a discrete state machine: Initial Scene State S₀ evolves to S₁ when the learner triggers an authenticated semantic transformation rule R. The transformation applies an atomic declarative patch adding or removing entities and projections.</p>\n    <p>The state machine isolates the decisive cognitive act (the crucial insight):</p>\n    <ul>\n      <li><strong>Calculus (Riemann Sums):</strong> Slicing subintervals from N=2 to N=4 and N=8 progressively narrows the Darboux gap between under- and over-estimates, trapping the exact integral ∫₀¹ x² dx = 1/3 ≈ 0.3333.</li>\n      <li><strong>Arithmetic (Long Division):</strong> Decomposes 492 ÷ 4 into place-value bags: Hundreds (400 ÷ 4 = 100), Tens (90 ÷ 4 = 20, rem 10), and Units (12 ÷ 4 = 3).</li>\n      <li><strong>Chemistry (Redox Balance):</strong> Matches electron loss in oxidation (Fe²⁺ → Fe³⁺ + 1e⁻) with electron gain in reduction (Ce⁴⁺ + 1e⁻ → Ce³⁺), establishing 1e⁻ Lost = 1e⁻ Gained.</li>\n      <li><strong>Physics (Kinematics Shared Clock):</strong> Enforces physical simultaneity: horizontal x(2s) and vertical y(2s) share one clock (ACCEPTED), while mixed-time states x(2s), y(3s) are REJECTED.</li>\n    </ul>\n  </section>\n\n  <section class=\"field-section\" id=\"fail-closed\">\n    <h2>03 · The 15 fail-closed rejection invariants</h2>\n    <p>The host runtime operates as an immutable fail-closed boundary. The package parser rejects any corrupted or unsafe input:</p>\n    <div class=\"table-wrap\">\n      <table>\n        <thead><tr><th>Error Code</th><th>Trigger Condition</th><th>Severity</th></tr></thead>\n        <tbody>\n          <tr><td><code>PORTABLE_EXECUTABLE_FIELD_FORBIDDEN</code></td><td>Forbidden script/eval/handler keyword in keys or strings</td><td>FAIL_CLOSED</td></tr>\n          <tr><td><code>PORTABLE_PIXEL_COORDINATE_FORBIDDEN</code></td><td>Pixel coordinate keys (x, y, left, top) in placement</td><td>FAIL_CLOSED</td></tr>\n          <tr><td><code>PORTABLE_VERSION_MISMATCH</code></td><td>Seam mismatch in package, component, or adapter version</td><td>FAIL_CLOSED</td></tr>\n          <tr><td><code>PORTABLE_CANONICAL_RESOURCE_REF_REQUIRED</code></td><td>Missing resourceRef for CANONICAL_COMPILED_RESOURCE authority</td><td>FAIL_CLOSED</td></tr>\n          <tr><td><code>PORTABLE_CANONICAL_SOURCE_REFS_MISMATCH</code></td><td>Provenance sourceRefs differs from top-level sourceRefs</td><td>FAIL_CLOSED</td></tr>\n          <tr><td><code>PORTABLE_GRID_ENTITY_MISMATCH</code></td><td>Projection references missing grid, row, column, or entity</td><td>FAIL_CLOSED</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section class=\"field-section\" id=\"kid-simulation\">\n    <h2>04 · Kid-accessible visual simulations &amp; telemetry</h2>\n    <p>Internal compiler diagnostics (e.g. <code>rule-refine-n4</code>, <code>COL-N2</code>) must never be presented as the primary interface for students. The workbench compiles every package into four kid-accessible visual tiers:</p>\n    <ol>\n      <li><strong>The 4-Part Kid Guide:</strong> A high-contrast card providing a plain-language analogy title, clear mission statement, color-coded 3-step breakdown, and memorable mnemonic (e.g. <em>OIL RIG</em>).</li>\n      <li><strong>Live Dynamic SVG Simulation:</strong> Responsive geometry rendered directly into the native DOM (curve plots, division brackets, electron balance beams, stroboscopic timelines).</li>\n      <li><strong>Real-Time Telemetry (Squeeze-O-Meter):</strong> A dynamic progress gauge showing quantitative convergence, upper/lower bounds, and refinement error gap.</li>\n      <li><strong>Humanized Transformation Actions:</strong> 48px+ action buttons labeled with clear educational intent, icons, and explanatory subtitles while preserving <code>data-rule-id</code> for automated test assertions.</li>\n    </ol>\n  </section>\n\n  <section class=\"field-section\" id=\"ergonomics\">\n    <h2>05 · Ergonomics, zero-iframe policy &amp; touch standards</h2>\n    <p>In accordance with the 12.7\" Tablet Specification (Workpack A64):</p>\n    <ul>\n      <li><strong>Zero Iframes:</strong> All simulations execute in-DOM without cross-origin boundary issues, script lag, or mobile iframe clipping.</li>\n      <li><strong>No Coordinate Hacks:</strong> Zero <code>position: absolute</code> and zero <code>translate3d</code> in generated markup. Layout uses semantic HTML tables with <code>role=\"table\"</code> and CSS Flexbox.</li>\n      <li><strong>Touch Target Compliance:</strong> All buttons, projection pills, and rotate controls satisfy WCAG 2.5.5 AAA touch targets of ≥ 48px.</li>\n      <li><strong>Lossless 90° Rotation:</strong> State is preserved across orientation flips via immutable state export and restore.</li>\n    </ul>\n  </section>\n\n  <section class=\"field-section\" id=\"golden-specimens\">\n    <h2>06 · Golden specimens &amp; dual-engine validation</h2>\n    <p>Every workbench package undergoes dual-engine automated verification:</p>\n    <ul>\n      <li><strong>Engine 1 (Python / Node Fail-Closed Validator):</strong> Certifies 100% adherence to all 15 rejection rules and schema version seams.</li>\n      <li><strong>Engine 2 (Playwright Chromium Audit):</strong> Launches headless Chromium, mounts the workbench in 1600×1000 and 1000×1600 viewports, validates inert labels, checks 48px touch targets, and executes state transitions.</li>\n    </ul>\n  </section>\n\n  <section class=\"field-section\" id=\"authoring-runbook\">\n    <h2>07 · Operational authoring runbook for new STEM explorers</h2>\n    <ol>\n      <li>Author package JSON adhering strictly to <code>portable-workbench-package</code> schema <code>1.0.0</code>.</li>\n      <li>Verify with <code>python scripts/validate_workbench_package.py &lt;file.json&gt;</code>.</li>\n      <li>Register educational analogies and SVG graphics in <code>web/applications/portable/component.ts</code>.</li>\n      <li>Verify rendered DOM ergonomics with <code>node scripts/verify_component_html.js</code>.</li>\n      <li>Run full smoke and regression tests: <code>npm run test:smoke</code>.</li>\n    </ol>\n  </section>\n</article>",

};
